// Selected, sourced historical relationships; positions are not a time scale.
const CONNECTION_TYPES={"union":{"label":"Union","color":"#3b8274","description":"Crowns, states or constituent territories joined. The specific legal form matters."},"division":{"label":"Division","color":"#b88636","description":"An administrative division, fragmentation or territorial separation, as specified by the event."},"conquest":{"label":"Conquest","color":"#aa6355","description":"Military defeat or annexation; the target state may already have existed."},"independence":{"label":"Independence","color":"#638350","description":"A change in sovereignty, often achieved in stages rather than on one date."},"continuation":{"label":"Change of rule","color":"#5d7f9d","description":"A dynasty, title, government or institutional framework changed or continued. This does not imply unchanged territory or one continuous regime."},"contact":{"label":"Contact / influence","color":"#8b7297","description":"Rivalry, diplomacy, artistic influence or a stated tradition; not necessarily political descent."},"colonial":{"label":"Colonial rule","color":"#9a8055","description":"Colonial expansion or administration, not the beginning of the inhabitants’ histories."},"context":{"label":"Context / overlap","color":"#92917a","description":"A shared period, geographical frame or later heritage. This is not a claim of direct political succession or descent."},"period":{"label":"Period transition","color":"#7d8c6f","description":"A conventional change of archaeological or cultural period. Populations, institutions and practices can continue across it."}};
const CONNECTION_MAPS=[{"id":"britain-atlantic","title":"Britain & the Atlantic","width":1600,"height":1839,"nodes":[{"id":"england","x":100,"y":220,"label":"England"},{"id":"scotland","x":470,"y":220,"label":"Scotland"},{"id":"greatbritain","x":285,"y":475,"label":"Great Britain"},{"id":"britishempire","x":1030,"y":475,"label":"British Empire"},{"id":"cn-ireland","x":60,"y":705,"label":"Kingdom of Ireland"},{"id":"britishamerica","x":1000,"y":705,"label":"British America"},{"id":"newfrance","x":1330,"y":705,"label":"New France"},{"id":"unitedkingdom","x":285,"y":960,"label":"United Kingdom"},{"id":"unitedstates","x":690,"y":960,"label":"United States"},{"id":"cn-britishnorth","x":1210,"y":960,"label":"British northern colonies"},{"id":"cn-irishfree","x":285,"y":1215,"label":"Irish Free State"},{"id":"canada","x":1210,"y":1215,"label":"Canada"},{"id":"cn-ireland-modern","x":285,"y":1475,"label":"Ireland"}],"connections":[{"id":"union1707","from":["england","scotland"],"to":["greatbritain"],"type":"union","label":"1707 · union","dates":"1707","summary":"The English and Scottish kingdoms and parliaments united as Great Britain.","note":"The 1603 Union of the Crowns had already created a shared monarch; parliamentary union came later.","sources":["union1707"],"x":399,"y":415},{"id":"english-expansion","from":["england"],"to":["britishempire"],"type":"colonial","label":"1600s · overseas expansion","dates":"Late 16th–17th centuries","summary":"English overseas settlements and trading ventures developed into a wider imperial system.","note":"The British Empire was not a new country replacing England. Scottish ventures and the later British state also shaped it.","sources":["britishAmerica"],"x":1144,"y":350,"fromSide":"right","trunkY":345},{"id":"british-colonies","from":["britishempire"],"to":["britishamerica"],"type":"colonial","label":"Colonial administration","dates":"17th–18th centuries","summary":"British America grouped colonies within the wider empire.","note":"The colonies had different institutions; Indigenous peoples and political orders continued alongside and under colonial expansion.","sources":["britishAmerica"],"x":1114,"y":645},{"id":"union1801","from":["greatbritain","cn-ireland"],"to":["unitedkingdom"],"type":"union","label":"1801 · union","dates":"1801","summary":"Great Britain and Ireland entered a parliamentary union as the United Kingdom.","note":"This was a political union, not the beginning of the peoples or cultures of either island.","sources":["union1801"],"x":399,"y":880},{"id":"atlantic1783","from":["britishamerica"],"to":["unitedstates","cn-britishnorth"],"type":"division","label":"1776–83 · independence & remaining colonies","dates":"1776–1783","summary":"Thirteen colonies declared independence and became the United States. Britain retained other North American colonies.","note":"This is a selected branching of colonial jurisdictions, not a division of the entire population into two homogeneous peoples.","sources":["america1783","canadaHistory"],"x":920,"y":880},{"id":"canada1763","from":["newfrance"],"to":["cn-britishnorth"],"type":"conquest","label":"1763 · cession of Canada","dates":"1763","summary":"The Treaty of Paris transferred French Canada to British control.","note":"Other former French territories had different outcomes, including transfers to Spain. The arrow concerns Canada, not all New France.","sources":["canadaHistory"],"x":1400,"y":880,"xOffset":85},{"id":"canada-confederation","from":["cn-britishnorth"],"to":["canada"],"type":"union","label":"1867 · Confederation","dates":"1867","summary":"The Province of Canada, New Brunswick and Nova Scotia federated as the Dominion of Canada.","note":"Other colonies and territories joined later; 1867 was not a single moment of complete independence.","sources":["canada1867"],"x":1324,"y":1140},{"id":"irish-state","from":["unitedkingdom"],"to":["cn-irishfree"],"type":"independence","label":"1922 · Free State established","dates":"1922","summary":"The Irish Free State was established, while Northern Ireland remained within the United Kingdom.","note":"The Free State initially had dominion status. Later constitutional changes followed in 1937 and 1949.","sources":["irish1922"],"x":399,"y":1140},{"id":"ireland-constitution","from":["cn-irishfree"],"to":["cn-ireland-modern"],"type":"continuation","label":"1937 / 1949 · constitutional changes","dates":"1937 and 1949","summary":"A new constitution replaced the Free State framework in 1937; the republic description and departure from the Commonwealth followed in 1949.","note":"The constitution came into operation in December 1937. Ireland is the state name; these constitutional changes did not end the separate position of Northern Ireland.","sources":["ireland1937","irish1922"],"x":399,"y":1400}],"region":"europe","continuations":[{"map":"iron-age-roman-encounters","history":"england","label":"Iron Age communities, Rome & post-Roman Britain"}]},{"id":"rome-francia","title":"Rome, Frankish realms & modern successors","width":1600,"height":2650,"nodes":[{"id":"romanrepublic","x":190,"y":220,"label":"Roman Republic"},{"id":"cn-romanempire","x":190,"y":460,"label":"Roman Empire"},{"id":"cn-westrome","x":150,"y":720,"label":"Western Roman Empire"},{"id":"byzantium","x":720,"y":720,"label":"Eastern Roman / Byzantium"},{"id":"sasanian","x":1260,"y":720,"label":"Sasanian Empire"},{"id":"carolingian","x":150,"y":1010,"label":"Carolingian Empire"},{"id":"ottoman","x":880,"y":1010,"label":"Ottoman Empire"},{"id":"cn-westfrancia","x":45,"y":1250,"label":"West Francia"},{"id":"cn-middlefrancia","x":410,"y":1250,"label":"Middle Francia"},{"id":"cn-eastfrancia","x":775,"y":1250,"label":"East Francia"},{"id":"francekingdom","x":45,"y":1455,"label":"French kingdom"},{"id":"holyroman","x":775,"y":1455,"label":"Holy Roman Empire"},{"id":"francemodern","x":45,"y":1730,"label":"France · modern eras"},{"id":"poster-europe-089","x":650,"y":1730,"label":"German Confederation"},{"id":"poster-europe-099","x":1180,"y":1730,"label":"Austrian Empire"},{"id":"cn-northgerman","x":650,"y":1990,"label":"North German Confederation"},{"id":"poster-europe-100","x":1180,"y":1990,"label":"Austria-Hungary"},{"id":"germanymodern","x":650,"y":2250,"label":"Germany · modern eras"},{"id":"austriamodern","x":1180,"y":2250,"label":"Austria · republican eras"},{"id":"turkiye","x":80,"y":2250,"label":"Republic of Türkiye"}],"connections":[{"id":"principate","from":["romanrepublic"],"to":["cn-romanempire"],"type":"continuation","label":"27 BC · principate","dates":"27 BC","summary":"Augustus established the principate within the continuing Roman state.","note":"Republican forms and institutions did not vanish overnight; this is a conventional political transition.","sources":["romanRepublic"],"x":304,"y":385},{"id":"roman-division","from":["cn-romanempire"],"to":["cn-westrome","byzantium"],"type":"division","label":"395 · separate imperial courts","dates":"395 AD","summary":"After Theodosius I, separate emperors ruled the eastern and western courts.","note":"Division developed over time. The eastern empire continued to understand itself as Roman, rather than representing an unrelated new civilisation.","sources":["roman","byzantium"],"x":450,"y":645},{"id":"roman-revival","from":["cn-westrome"],"to":["carolingian"],"type":"contact","label":"800 · Roman imperial title revived","dates":"800 AD","summary":"Charlemagne’s coronation revived a western claim to Roman imperial authority.","note":"This indicates a political model and claim to legitimacy, not an uninterrupted continuation of Western Roman administration.","sources":["carolingianWest"],"x":264,"y":925},{"id":"roman-persian","from":["byzantium"],"to":["sasanian"],"type":"contact","label":"War, diplomacy & exchange","dates":"4th–7th centuries AD","summary":"The Roman and Sasanian states fought repeated wars and maintained diplomatic and cultural contacts.","note":"Neither state simply merged into the other; their frontier and relationship changed over centuries.","sources":["sasanian","byzantium"],"x":1100,"y":766,"horizontal":true,"bidirectional":true},{"id":"constantinople1453","from":["byzantium"],"to":["ottoman"],"type":"conquest","label":"1453 · Constantinople conquered","dates":"1453","summary":"Ottoman forces conquered Constantinople, ending its Byzantine imperial government.","note":"The Ottoman state had existed for well over a century. Byzantine successor territories and cultural traditions had separate and continuing histories.","sources":["ottoman","byzantium"],"x":994,"y":925},{"id":"verdun843","from":["carolingian"],"to":["cn-westfrancia","cn-middlefrancia","cn-eastfrancia"],"type":"division","label":"843 · Treaty of Verdun","dates":"843","summary":"The Carolingian realm was partitioned into West, Middle and East Francia.","note":"These were dynastic kingdoms, not the present borders or founding moments of modern France, Germany and Italy. Further partitions followed.","sources":["carolingian"],"x":525,"y":1170},{"id":"capetian987","from":["cn-westfrancia"],"to":["francekingdom"],"type":"continuation","label":"987 · Capetian accession","dates":"987","summary":"Hugh Capet’s accession marks a dynastic transition in the western Frankish kingdom.","note":"The French kingdom did not appear from nothing in 987; institutions and society developed across this transition.","sources":["capetian"],"x":159,"y":1385},{"id":"otto962","from":["cn-eastfrancia"],"to":["holyroman"],"type":"continuation","label":"962 · imperial coronation","dates":"962","summary":"Otto I’s imperial coronation anchors the conventional beginning used here for the Holy Roman Empire.","note":"This was an evolving imperial framework, not immediate unification of a modern German nation-state.","sources":["carolingian"],"x":889,"y":1385},{"id":"france-republic","from":["francekingdom"],"to":["francemodern"],"type":"continuation","label":"1792 · monarchy abolished","dates":"1792","summary":"The Revolution abolished monarchy and inaugurated a republic in France.","note":"The destination is a broad frame containing later empires, restored monarchies and republics. It does not imply uninterrupted republican government after 1792.","sources":["france1792"],"x":159,"y":1650},{"id":"german-reorganisation","from":["holyroman"],"to":["poster-europe-089"],"type":"continuation","label":"1806–15 · imperial end & new league","dates":"1806–1815","summary":"The Holy Roman Empire ended in 1806; after Napoleonic reorganisation, the Vienna settlement created a German Confederation in 1815.","note":"This was a new association of states after an intervening period, not the old empire renamed. Its membership and institutions differed.","sources":["german1815"],"x":764,"y":1650},{"id":"habsburg-imperial-frame","from":["holyroman"],"to":["poster-europe-099"],"type":"continuation","label":"1804–06 · Habsburg imperial change","dates":"1804–1806","summary":"The Habsburg ruler created an Austrian imperial title in 1804, before relinquishing the separate Holy Roman title in 1806.","note":"The Austrian Empire concerned the Habsburg monarchy, including lands outside the Holy Roman Empire. It did not inherit the whole former empire.","sources":["german1815","austria1867"],"x":1294,"y":1650},{"id":"northgerman1867","from":["poster-europe-089"],"to":["cn-northgerman"],"type":"continuation","label":"1866–67 · new northern federation","dates":"1866–1867","summary":"War dissolved the old German Confederation; Prussia and northern allies formed a new federal state.","note":"Austria and the southern states were outside this new federation. The two confederations were different political frameworks.","sources":["german1871"],"x":764,"y":1915},{"id":"german-empire1871","from":["cn-northgerman"],"to":["germanymodern"],"type":"union","label":"1871 · enlarged German federation","dates":"1871","summary":"Southern German states joined the Prussia-led federation, forming the German Empire.","note":"Austria was excluded. The destination groups later German regimes, division after 1945 and reunification in 1990; it is not one unchanged government.","sources":["german1871"],"x":764,"y":2175},{"id":"austriahungary1867","from":["poster-europe-099"],"to":["poster-europe-100"],"type":"continuation","label":"1867 · Dual Monarchy","dates":"1867","summary":"The compromise reorganised the Habsburg monarchy into Austrian and Hungarian halves with shared affairs.","note":"This was a constitutional reorganisation of a multinational monarchy, not the merger of two homogeneous peoples.","sources":["austria1867"],"x":1294,"y":1915},{"id":"austria-republic1918","from":["poster-europe-100"],"to":["austriamodern"],"type":"continuation","label":"1918 · one of several successor states","dates":"1918","summary":"The monarchy broke apart and a republic was proclaimed in Austria.","note":"Austria was only one successor. Hungary, Czechoslovakia and other successor or enlarged states followed separate paths. The destination also includes dictatorship, annexation in 1938 and the restored republic after 1945.","sources":["austria1918"],"x":1294,"y":2175},{"id":"turkey-republic1923","from":["ottoman"],"to":["turkiye"],"type":"continuation","label":"1922–23 · sultanate ends; republic","dates":"1922–1923","summary":"The sultanate was abolished in 1922 and the Republic of Turkey was proclaimed in 1923 after war and the Lausanne settlement.","note":"This is one selected outcome of Ottoman dissolution. Other former Ottoman territories had different state formations and colonial mandates; the entire empire did not become Turkey.","sources":["turkey1923"],"x":370,"y":2100,"fromSide":"left","via":[{"x":650,"y":1057},{"x":650,"y":1380},{"x":370,"y":1380}]}],"region":"europe","continuations":[{"map":"frankish-alpine-worlds","history":"cn-westrome","label":"Migration, Frankish kingdoms & Alpine Austria"},{"map":"italian-rule-unification","history":"byzantium","label":"Italian kingdoms, communes & unification"},{"map":"aegean-greek-worlds","history":"romanrepublic","label":"Aegean networks, Greek worlds & modern independence"}]},{"id":"west-asia","title":"Persian, Hellenistic & Islamic realms","width":1600,"height":2284,"nodes":[{"id":"persia","x":200,"y":220,"label":"Achaemenid Persia"},{"id":"cn-alexander","x":200,"y":460,"label":"Alexander’s empire"},{"id":"cn-seleucid","x":200,"y":720,"label":"Seleucid Empire"},{"id":"cn-ptolemaic","x":1000,"y":720,"label":"Ptolemaic Egypt"},{"id":"cn-parthian","x":200,"y":960,"label":"Parthian Empire"},{"id":"romanrepublic","x":1000,"y":960,"label":"Roman Republic"},{"id":"sasanian","x":200,"y":1200,"label":"Sasanian Empire"},{"id":"rashidun","x":790,"y":1200,"label":"Rashidun caliphate"},{"id":"umayyad","x":790,"y":1440,"label":"Umayyad caliphate"},{"id":"abbasid","x":790,"y":1680,"label":"Abbasid Baghdad"},{"id":"cn-ilkhanate","x":790,"y":1920,"label":"Ilkhanate"}],"connections":[{"id":"alexander-conquest","from":["persia"],"to":["cn-alexander"],"type":"conquest","label":"334–330 BC · conquest","dates":"334–330 BC","summary":"Alexander’s campaigns defeated Achaemenid royal power and occupied its principal territories.","note":"Local populations and administrative practices continued; this was not a replacement of all inhabitants or cultures.","sources":["iranAncient"],"x":314,"y":385},{"id":"diadochi","from":["cn-alexander"],"to":["cn-seleucid","cn-ptolemaic"],"type":"division","label":"After 323 BC · successor kingdoms","dates":"After 323 BC","summary":"Wars after Alexander’s death produced several kingdoms, including the Seleucid and Ptolemaic realms.","note":"Only two selected successors are shown. They emerged through prolonged struggles, not a neat agreed two-way split in 323 BC.","sources":["parthian","ptolemaic"],"x":650,"y":645},{"id":"parthian-expansion","from":["cn-seleucid"],"to":["cn-parthian"],"type":"conquest","label":"3rd–2nd c. BC · territorial expansion","dates":"3rd–2nd centuries BC","summary":"Parthian rulers expanded into territories previously controlled by the Seleucids.","note":"This was gradual and regional. Seleucid rule continued elsewhere after major eastern territories were lost.","sources":["parthian"],"x":314,"y":885},{"id":"egypt30","from":["cn-ptolemaic"],"to":["romanrepublic"],"type":"conquest","label":"30 BC · Egypt annexed","dates":"30 BC","summary":"Octavian’s forces defeated the Ptolemaic monarchy, and Egypt came under Roman rule.","note":"The conquest preceded the conventional 27 BC beginning of the principate. Egyptian society continued under different rulers.","sources":["ptolemaic"],"x":1114,"y":885},{"id":"sasanian224","from":["cn-parthian"],"to":["sasanian"],"type":"continuation","label":"224 · dynasty overthrown","dates":"224 AD","summary":"Ardashir defeated the last major Arsacid king and established Sasanian rule.","note":"A dynastic and political change did not erase the region’s peoples, religious communities or administrative traditions.","sources":["sasanian"],"x":314,"y":1125},{"id":"iran-conquest","from":["sasanian"],"to":["rashidun"],"type":"conquest","label":"633–651 · conquest of Iran","dates":"633–651 AD","summary":"Arab-Muslim armies defeated Sasanian forces, and the last Sasanian emperor died in 651.","note":"Conquest unfolded in stages. The caliphate already existed; Iranian institutions and cultural traditions continued in changing forms.","sources":["islamicIran","sasanian"],"x":610,"y":1246,"horizontal":true},{"id":"umayyad661","from":["rashidun"],"to":["umayyad"],"type":"continuation","label":"661 · Umayyad rule","dates":"661 AD","summary":"Mu‘awiya’s rule inaugurated the Umayyad caliphate after civil war.","note":"This is a change in political leadership, not a new beginning for Islam or a single instantaneous transformation of every province.","sources":["islamicEast"],"x":904,"y":1365},{"id":"abbasid750","from":["umayyad"],"to":["abbasid"],"type":"continuation","label":"750 · Abbasid revolution","dates":"750 AD","summary":"The Abbasid revolution replaced the Damascus-based Umayyad caliphate.","note":"An Umayyad line continued in Iberia. The diagram does not imply that all Umayyad institutions or communities disappeared.","sources":["islamicEast"],"x":904,"y":1605},{"id":"baghdad1258","from":["abbasid"],"to":["cn-ilkhanate"],"type":"conquest","label":"1258 · Baghdad conquered","dates":"1258","summary":"Hülegü’s Mongol forces captured Baghdad and ended its Abbasid caliphate.","note":"The Ilkhanate was already taking shape. Later Abbasid caliphs in Cairo and other Islamic states are not represented by this arrow.","sources":["ilkhanid"],"x":904,"y":1845}],"continuations":[{"map":"iran-modern","history":"cn-ilkhanate","label":"Continue: Ilkhanate → modern Iran"},{"map":"ancient-anatolia-levant","history":"persia","label":"Ancient Anatolia & Levant"},{"map":"seljuqs-anatolia","history":"abbasid","label":"Seljuqs, Anatolia & Iran"}],"region":"westasia"},{"id":"mongols-china","title":"Mongol khanates & China","width":1600,"height":2084,"nodes":[{"id":"mongol","x":650,"y":220,"label":"Mongol Empire","dates":"1206–c. 1260 · unified phase"},{"id":"cn-goldenhorde","x":40,"y":510,"label":"Golden Horde"},{"id":"cn-chagatai","x":420,"y":510,"label":"Chagatai Khanate"},{"id":"cn-ilkhanate","x":800,"y":510,"label":"Ilkhanate"},{"id":"yuan","x":1180,"y":510,"label":"Yuan dynasty"},{"id":"song","x":1180,"y":760,"label":"Song dynasties"},{"id":"ming","x":780,"y":1000,"label":"Ming dynasty"},{"id":"qing","x":780,"y":1250,"label":"Qing dynasty"},{"id":"republicchina","x":780,"y":1490,"label":"Republic of China"},{"id":"prchina","x":460,"y":1720,"label":"People’s Republic of China"},{"id":"taiwanroc","x":1110,"y":1720,"label":"ROC · Taiwan era"}],"connections":[{"id":"mongol-fragmentation","from":["mongol"],"to":["cn-goldenhorde","cn-chagatai","cn-ilkhanate","yuan"],"type":"division","label":"13th c. · regional khanates","dates":"13th century","summary":"The wider Mongol realm developed into several regional khanates, including these four major branches.","note":"Their origins predated the final fragmentation. This was not a single simultaneous partition in 1260, and competing claims to imperial authority continued.","sources":["mongols"],"x":764,"y":420},{"id":"song1279","from":["song"],"to":["yuan"],"type":"conquest","label":"1279 · Song conquest completed","dates":"1279","summary":"Kublai Khan’s forces completed the conquest of the Southern Song.","note":"The Yuan dynastic name had been proclaimed in 1271. The arrow records conquest of another state, not the first formation of Yuan rule.","sources":["yuan"],"x":1450,"y":680,"sideRoute":true},{"id":"ming1368","from":["yuan"],"to":["ming"],"type":"conquest","label":"1368 · Ming takes the capital","dates":"1368","summary":"Ming forces took the Yuan capital, and Yuan rulers withdrew north.","note":"Northern Yuan regimes continued after 1368. Dynastic replacement in China did not end Mongol societies or all Mongol states.","sources":["mingqing"],"x":1080,"y":920,"fromSide":"left","trunkX":1100},{"id":"qing1644","from":["ming"],"to":["qing"],"type":"conquest","label":"1644 · Qing enters Beijing","dates":"1644","summary":"The Qing entered Beijing during the collapse of the main Ming regime.","note":"The Qing dynasty was proclaimed in 1636. Southern Ming resistance and the consolidation of Qing rule continued after 1644.","sources":["mingqing"],"x":894,"y":1175},{"id":"republic1912","from":["qing"],"to":["republicchina"],"type":"continuation","label":"1911–12 · revolution & abdication","dates":"1911–1912","summary":"Revolution and the Qing emperor’s abdication ended the imperial system and established republican rule.","note":"Political fragmentation and competing governments continued; this is not a claim of immediate stable national control.","sources":["china1912"],"x":894,"y":1415},{"id":"china1949","from":["republicchina"],"to":["prchina","taiwanroc"],"type":"division","label":"1949 · civil war & rival governments","dates":"1949","summary":"The PRC was proclaimed on the mainland, while the ROC government relocated to Taiwan.","note":"ROC administration in Taiwan began in 1945. These are changes in governments and territorial control; the map does not resolve sovereignty or recognition claims.","sources":["china1949"],"x":894,"y":1650}],"continuations":[{"map":"iran-modern","history":"cn-ilkhanate","label":"Ilkhanate → modern Iran"},{"map":"iran-modern","history":"cn-chagatai","label":"Western Chagatai → Timurids & Mughal rule"},{"map":"steppe-russia","history":"cn-goldenhorde","label":"Golden Horde → Muscovy, USSR & modern states"}],"region":"eastasia"},{"id":"south-asia","title":"South Asia: empire, company & partition","width":1600,"height":1704,"nodes":[{"id":"mughal","x":160,"y":220,"label":"Mughal dynasty"},{"id":"maratha","x":1060,"y":220,"label":"Maratha polity"},{"id":"companyindia","x":610,"y":535,"label":"East India Company rule"},{"id":"britishraj","x":610,"y":800,"label":"British Raj"},{"id":"indiamodern","x":260,"y":1090,"label":"India"},{"id":"pakistan","x":960,"y":1090,"label":"Pakistan"},{"id":"bangladesh","x":960,"y":1340,"label":"Bangladesh"}],"connections":[{"id":"mughal-company","from":["mughal"],"to":["companyindia"],"type":"colonial","label":"1757–65 · Company gains in Bengal","dates":"1757–1765","summary":"Military victories and revenue rights expanded Company control in Bengal and adjoining regions.","note":"Mughal imperial titles survived until 1858. This was a regional expansion of colonial power, not a merger of the entire Mughal realm into the Company.","sources":["company"],"x":410,"y":440},{"id":"maratha1818","from":["maratha"],"to":["companyindia"],"type":"conquest","label":"1818 · Peshwa defeated","dates":"1818","summary":"The Company defeated the Peshwa in the Third Anglo-Maratha War.","note":"Several Maratha-ruled princely states continued afterward. The event did not annex or extinguish every Maratha institution.","sources":["company"],"x":1090,"y":440},{"id":"mughal-maratha","from":["mughal"],"to":["maratha"],"type":"contact","label":"Rivalry, war & negotiation","dates":"17th–18th centuries","summary":"Mughal and Maratha powers fought and negotiated over territory and authority.","note":"Their polities coexisted. An encounter does not imply that one people simply transformed into the other.","sources":["mughalMaratha"],"x":724,"y":266,"horizontal":true,"bidirectional":true},{"id":"crown1858","from":["companyindia"],"to":["britishraj"],"type":"continuation","label":"1858 · Crown replaces Company","dates":"1858","summary":"The British Crown took over the Company’s governing role in India.","note":"The new colonial framework included provinces under direct administration and princely states with different arrangements.","sources":["company"],"x":724,"y":720},{"id":"partition1947","from":["britishraj"],"to":["indiamodern","pakistan"],"type":"division","label":"1947 · independence & Partition","dates":"1947","summary":"British rule ended as India and Pakistan became independent, accompanied by Partition.","note":"Pakistan initially included geographically separated eastern and western wings. The division involved mass displacement and violence; it was not a simple peaceful branching.","sources":["partition"],"x":724,"y":1005},{"id":"bangladesh1971","from":["pakistan"],"to":["bangladesh"],"type":"independence","label":"1971 · Bangladesh independence","dates":"1971","summary":"East Pakistan became Bangladesh following the liberation war.","note":"West Pakistan continued as Pakistan. This marks a change in sovereignty, not the beginning of Bengali society or culture.","sources":["bangladesh"],"x":1074,"y":1265}],"continuations":[{"map":"iran-modern","history":"mughal","label":"Earlier: Babur & the Timurid connection"},{"map":"afghanistan-regional-powers","history":"companyindia","label":"Afghanistan & regional powers"},{"map":"south-asia-early-medieval","history":"mughal","label":"South Asia: early & medieval"}],"region":"southasia"},{"id":"west-africa","title":"West Africa: several kinds of connection","width":1600,"height":1414,"nodes":[{"id":"mali","x":100,"y":260,"label":"Mali Empire"},{"id":"songhai","x":700,"y":260,"label":"Songhai Empire"},{"id":"cn-saadi","x":1210,"y":260,"label":"Saadi Morocco"},{"id":"kanem","x":100,"y":660,"label":"Kanem"},{"id":"bornu","x":700,"y":660,"label":"Bornu"},{"id":"ife","x":100,"y":1050,"label":"Ife"},{"id":"benin","x":700,"y":1050,"label":"Kingdom of Benin"}],"connections":[{"id":"sahelian-shifts","from":["mali"],"to":["songhai"],"type":"contact","label":"Shared regions & changing power","dates":"14th–16th centuries","summary":"Mali and Songhai participated in overlapping Sahelian trade networks and successively controlled some of the same centres.","note":"Mali continued as Songhai expanded. Gao and Timbuktu had different intervening rulers; this is not a single direct transfer or merger.","sources":["sahel","songhai1591"],"x":520,"y":306,"horizontal":true,"bidirectional":true},{"id":"songhai1591","from":["cn-saadi"],"to":["songhai"],"type":"conquest","label":"1591 · Moroccan invasion","dates":"1591","summary":"Troops sent by the Moroccan sultan defeated Songhai’s army and seized major centres.","note":"Authority remained contested, and Songhai resistance and successor communities continued. Morocco did not simply become a new name for the entire Songhai realm.","sources":["songhai1591"],"x":1090,"y":306,"horizontal":true},{"id":"kanem-bornu","from":["kanem"],"to":["bornu"],"type":"continuation","label":"Late 1300s · ruling court relocates","dates":"Late 14th century","summary":"The Sayfuwa court moved from Kanem to Bornu west of Lake Chad.","note":"The move changed the centre of dynastic power. Kanem and Bornu had distinct regional histories, and the transfer did not erase their populations.","sources":["kanembornu"],"x":520,"y":706,"horizontal":true},{"id":"ife-benin","from":["ife"],"to":["benin"],"type":"contact","label":"Dynastic links in oral tradition","dates":"Medieval traditions","summary":"Benin oral traditions connect the foundation of a new royal line with Ife and Oranmiyan.","note":"This is a stated tradition, not proof that Benin was simply a province of Ife or that the account supplies a precisely dated political merger.","sources":["ifebenin"],"x":520,"y":1096,"horizontal":true,"certainty":"Tradition"}],"continuations":[{"map":"africa-modern","history":"mali","label":"Continue: later realms → Mali, Senegal & Nigeria"},{"map":"af-sahel-forest","history":"mali","label":"Sahel, Yoruba cities and the Gold Coast"}],"region":"africa"},{"id":"iberian-americas","title":"Iberian crowns & American successors","width":1600,"height":2834,"nodes":[{"id":"cn-castile","x":100,"y":220,"label":"Crown of Castile"},{"id":"cn-aragon","x":500,"y":220,"label":"Crown of Aragon"},{"id":"cn-portugal","x":1160,"y":220,"label":"Kingdom of Portugal"},{"id":"spainmodern","x":300,"y":490,"label":"Spanish monarchy"},{"id":"portuguesebrazil","x":1160,"y":600,"label":"Portuguese Brazil"},{"id":"spanishamerica","x":300,"y":800,"label":"Spanish America"},{"id":"brazilmodern","x":1160,"y":990,"label":"Brazil"},{"id":"mexicomodern","x":70,"y":1100,"label":"Mexico"},{"id":"cn-grancolombia","x":570,"y":1100,"label":"Gran Colombia"},{"id":"cn-newgranada","x":210,"y":1410,"label":"New Granada"},{"id":"cn-venezuela","x":620,"y":1410,"label":"Venezuela"},{"id":"cn-ecuador","x":1030,"y":1410,"label":"Ecuador"},{"id":"cn-granadine","x":210,"y":1690,"label":"Granadine Confederation"},{"id":"cn-uscolombia","x":210,"y":1950,"label":"United States of Colombia"},{"id":"cn-colombia","x":210,"y":2210,"label":"Colombia · later eras"},{"id":"cn-panama","x":780,"y":2470,"label":"Panama"},{"id":"portugalmodern","x":1190,"y":1690,"label":"Portugal · republican eras"}],"connections":[{"id":"iberian1479","from":["cn-castile","cn-aragon"],"to":["spainmodern"],"type":"union","label":"1479 · dynastic union","dates":"1479","summary":"The crowns of Castile and Aragon came under the joint rule of Isabella and Ferdinand.","note":"Their laws, institutions and territories remained distinct. This was not immediate administrative fusion into a modern centralised nation-state.","sources":["spainunion"],"x":414,"y":410},{"id":"spanish-colonies","from":["spainmodern"],"to":["spanishamerica"],"type":"colonial","label":"From 1493 · colonial expansion","dates":"From 1493","summary":"Spanish conquest and colonisation established changing jurisdictions in the Americas.","note":"The broad colonial node does not imply simultaneous conquest or uniform control, and Indigenous peoples and institutions persisted.","sources":["mexico"],"x":414,"y":720},{"id":"portuguese-colonies","from":["cn-portugal"],"to":["portuguesebrazil"],"type":"colonial","label":"From 1500 · arrival & colonisation","dates":"From 1500","summary":"Portuguese arrival was followed by settlement and colonial rule in parts of Brazil.","note":"Large-scale settlement developed later. Brazil’s elevation to a kingdom in 1815 preceded independence in 1822.","sources":["brazil"],"x":1274,"y":500},{"id":"brazil1822","from":["portuguesebrazil"],"to":["brazilmodern"],"type":"independence","label":"1822 · independence","dates":"1822","summary":"Brazil became independent under a monarchy before becoming a republic in 1889.","note":"Independence did not abolish slavery, which continued until 1888, or end all colonial social and economic relationships.","sources":["brazil"],"x":1274,"y":880},{"id":"mexico1821","from":["spanishamerica"],"to":["mexicomodern"],"type":"independence","label":"1821 · independence","dates":"1821","summary":"The independence struggle ended Spanish rule over what became independent Mexico.","note":"Mexico’s initial imperial and later republican forms are grouped in the destination node; its peoples and cultures predate 1821.","sources":["mexico"],"x":184,"y":1010},{"id":"gran-colombia","from":["spanishamerica"],"to":["cn-grancolombia"],"type":"independence","label":"1819–22 · republic & liberation","dates":"1819–1822","summary":"A new Colombian republic formed while independence forces liberated and incorporated territories.","note":"Present-day Ecuador joined after liberation in 1822. Other Spanish American independence movements had different trajectories.","sources":["ecuador","venezuela"],"x":684,"y":1010},{"id":"gran-colombia-split","from":["cn-grancolombia"],"to":["cn-newgranada","cn-venezuela","cn-ecuador"],"type":"division","label":"1830–31 · union dissolves","dates":"1830–1831","summary":"Venezuela and Ecuador separated, while the central provinces organised as New Granada.","note":"The map shows the principal successor states. Their borders and later constitutional forms continued to change.","sources":["ecuador","venezuela","newgranada"],"x":734,"y":1320},{"id":"granadine1858","from":["cn-newgranada"],"to":["cn-granadine"],"type":"continuation","label":"1858 · federal constitution","dates":"1858","summary":"New Granada adopted a federal constitution and the name Granadine Confederation.","note":"The population and territory did not become a new people; the event concerns constitutional arrangements.","sources":["colombiaFederal"],"x":324,"y":1615},{"id":"colombia1863","from":["cn-granadine"],"to":["cn-uscolombia"],"type":"continuation","label":"1863 · new federal constitution","dates":"1863","summary":"After civil war, the Rionegro constitution established the United States of Colombia.","note":"Transitional governments and names intervened. This map selects the lasting 1863 constitutional settlement.","sources":["colombiaConstitutions","colombiaFederal"],"x":324,"y":1875},{"id":"colombia1886","from":["cn-uscolombia"],"to":["cn-colombia"],"type":"continuation","label":"1886 · centralising constitution","dates":"1886","summary":"A new constitution replaced the federal framework and restored the name Republic of Colombia.","note":"Later constitutional changes followed, including the 1991 constitution. Panama remained within Colombia until 1903.","sources":["colombiaConstitutions"],"x":324,"y":2135},{"id":"panama-separation","from":["cn-colombia"],"to":["cn-panama"],"type":"independence","label":"1903 · Panama separates","dates":"1903","summary":"Panama separated from Colombia and established an independent republic.","note":"Colombia continued as a state. US intervention and canal negotiations were central to the circumstances of separation.","sources":["panama1903"],"x":894,"y":2395},{"id":"portugal-republic","from":["cn-portugal"],"to":["portugalmodern"],"type":"continuation","label":"1910 · monarchy overthrown","dates":"1910","summary":"The monarchy was replaced by a republic in Portugal.","note":"The later frame includes dictatorship and democratic government after 1974. The empire’s overseas territories had separate paths to independence.","sources":["portugal1910"],"x":1420,"y":1530,"fromSide":"right","trunkX":1520}],"region":"americas","continuations":[{"map":"mesoamerica-caribbean","history":"mexicomodern","label":"Mesoamerica & the Caribbean"},{"map":"north-american-communities","history":"mexicomodern","label":"North American communities & changing borders"},{"map":"medieval-iberian-realms","history":"cn-castile","label":"Iberian kingdoms, al-Andalus & Portugal"}]},{"id":"iran-modern","title":"From the Ilkhanate to modern Iran","width":1600,"height":3644,"nodes":[{"id":"cn-ilkhanate","x":200,"y":220,"label":"Ilkhanate"},{"id":"cn-chagatai","x":1060,"y":220,"label":"Chagatai · western realm"},{"id":"cn-jalayirid","x":50,"y":510,"label":"Jalayirids"},{"id":"cn-muzaffarid","x":420,"y":510,"label":"Muzaffarids"},{"id":"timurid","x":1060,"y":800,"label":"Timurid Empire"},{"id":"cn-qaraqoyunlu","x":200,"y":1100,"label":"Qara Qoyunlu"},{"id":"mughal","x":1060,"y":1100,"label":"Mughal dynasty"},{"id":"cn-aqqoyunlu","x":200,"y":1360,"label":"Aq Qoyunlu"},{"id":"safavid","x":200,"y":1620,"label":"Safavid Iran"},{"id":"cn-hotak-iran","x":200,"y":1880,"label":"Hotak occupation & rival claimants"},{"id":"afsharid","x":200,"y":2140,"label":"Afsharid Iran"},{"id":"cn-zand","x":50,"y":2440,"label":"Zand Iran"},{"id":"cn-afsharid-khorasan","x":700,"y":2440,"label":"Afsharid Khorasan"},{"id":"qajar","x":200,"y":2760,"label":"Qajar Iran"},{"id":"iran-pahlavi","x":200,"y":3020,"label":"Pahlavi Iran"},{"id":"iran-islamic-republic","x":200,"y":3280,"label":"Iran · Islamic Republic"}],"connections":[{"id":"ilkhanate1335","from":["cn-ilkhanate"],"to":["cn-jalayirid","cn-muzaffarid"],"type":"division","label":"After 1335 · regional powers","dates":"After 1335","summary":"The united Ilkhanate fragmented after Abu Sa‘id died. Jalayirids and Muzaffarids were among the regional powers that expanded.","note":"Only two examples are drawn. Chobanids, Sarbadars and others also ruled; no single dynasty inherited the whole realm. Some regional dynasties had earlier origins.","sources":["ilkhanid","iranRegional"],"x":430,"y":415},{"id":"timur1370","from":["cn-chagatai"],"to":["timurid"],"type":"continuation","label":"1370 · Timur takes Transoxiana","dates":"1370","summary":"Timur established power in Transoxiana within the western Chagatai political setting, founding the Timurid realm.","note":"This concerns the western region. Eastern Chagataid and Moghulistan histories continued separately; it is not a transfer of the entire Chagatai Khanate.","sources":["timurid"],"x":1390,"y":650,"fromSide":"right","trunkX":1470},{"id":"timur-iran","from":["cn-jalayirid","cn-muzaffarid"],"to":["timurid"],"type":"conquest","label":"1380s–90s · Timurid conquests","dates":"1380s–1390s","summary":"Timur’s armies invaded Iran and subordinated or defeated regional rulers. His conquests also extended well beyond former Ilkhanid lands.","note":"This was conquest after decades of regional rule. Jalayirid rulers sometimes returned; the drawing does not imply a peaceful, complete or permanent transfer.","sources":["timurid","iranRegional"],"x":800,"y":700},{"id":"qara-expansion","from":["timurid","cn-jalayirid"],"to":["cn-qaraqoyunlu"],"type":"conquest","label":"1400s · western territorial gains","dates":"1406–1460s","summary":"Qara Qoyunlu rulers gained Iraq and western Iranian territories claimed by Jalayirid and Timurid rulers.","note":"The connection selects western territories. Timurid courts continued in the east, and the expansion occurred in stages.","sources":["iran1400"],"x":430,"y":980},{"id":"babur1526","from":["timurid"],"to":["mughal"],"type":"contact","label":"1526 · Babur founds Mughal rule","dates":"1526","summary":"Babur, a Timurid prince, established Mughal rule in northern India after victory at Panipat.","note":"This marks a dynastic and cultural connection across regions, rather than the entire Timurid realm moving to or merging with India.","sources":["babur","timurid"],"x":1174,"y":1000},{"id":"aq1467","from":["cn-qaraqoyunlu"],"to":["cn-aqqoyunlu"],"type":"conquest","label":"1467–69 · Aq Qoyunlu victories","dates":"1467–1469","summary":"Uzun Hasan’s victories over rival confederate and Timurid forces established Aq Qoyunlu supremacy over much of Iran and Iraq.","note":"Both Turkoman confederations had earlier histories. This arrow selects their contest for territory, rather than the origins of their communities.","sources":["iran1400"],"x":314,"y":1285},{"id":"safavid1501","from":["cn-aqqoyunlu"],"to":["safavid"],"type":"conquest","label":"1501–03 · Safavid victories","dates":"1501–1503","summary":"Ismail and his Qizilbash supporters defeated Aq Qoyunlu forces and established Safavid rule at Tabriz in 1501.","note":"Consolidation across Iran took years, and Aq Qoyunlu resistance continued. This is not an instantaneous transfer of every territory.","sources":["iran1400"],"x":314,"y":1545},{"id":"isfahan1722","from":["safavid"],"to":["cn-hotak-iran"],"type":"conquest","label":"1722 · Isfahan falls","dates":"1722","summary":"Hotak forces captured Isfahan and broke the central Safavid government’s power.","note":"Safavid claimants continued. Hotak occupation, Ottoman and Russian interventions, and Nader’s subsequent recovery made this a period of contested rule.","sources":["iran1600","afsharids"],"x":314,"y":1805},{"id":"nader1736","from":["cn-hotak-iran"],"to":["afsharid"],"type":"continuation","label":"1736 · Nader takes the throne","dates":"1736","summary":"After expelling Hotak forces and ruling through Safavid claimants, Nader took the throne and founded Afsharid rule.","note":"The 1736 change followed military recovery and political conflict. Nader’s large empire then fragmented after his death in 1747.","sources":["afsharids","iran1600"],"x":314,"y":2065},{"id":"afsharid-fragmentation","from":["afsharid"],"to":["cn-zand","cn-afsharid-khorasan"],"type":"division","label":"After 1747 · competing realms","dates":"After 1747; Zand consolidation in the 1750s","summary":"Afsharid rulers retained Khorasan while Karim Khan Zand consolidated much of western and southern Iran.","note":"These are selected branches, not all territories. Zand and Afsharid rule overlapped; a separate Durrani state also emerged in Afghanistan.","sources":["afsharids","zand"],"x":580,"y":2340},{"id":"zand1794","from":["cn-zand"],"to":["qajar"],"type":"conquest","label":"1794 · Zand defeat","dates":"1794","summary":"Agha Mohammad Khan defeated the last Zand ruler, consolidating Qajar power after a prolonged struggle.","note":"Qajar starting dates vary with regional rule, conquest or coronation. The timeline uses 1789 as its conventional starting frame.","sources":["zandArchive","zand"],"x":164,"y":2660},{"id":"khorasan1796","from":["cn-afsharid-khorasan"],"to":["qajar"],"type":"conquest","label":"1796 · Khorasan conquered","dates":"1796","summary":"Qajar forces brought the surviving Afsharid realm in Khorasan under their control.","note":"A parallel conquest during Qajar consolidation, after Zand rule had already ended elsewhere.","sources":["afsharids"],"x":814,"y":2660},{"id":"pahlavi1925","from":["qajar"],"to":["iran-pahlavi"],"type":"continuation","label":"1925 · Pahlavi monarchy","dates":"1925","summary":"Parliament ended Qajar sovereignty and a constituent assembly established Reza Shah’s monarchy.","note":"The 1921 coup preceded the dynastic replacement by four years. Government, institutions and territorial control changed across these stages.","sources":["iranModern","qajar1925"],"x":314,"y":2945},{"id":"iran-revolution1979","from":["iran-pahlavi"],"to":["iran-islamic-republic"],"type":"continuation","label":"1979 · revolution & republic","dates":"1979","summary":"Revolution brought down the Pahlavi monarchy. The Islamic Republic was proclaimed on 1 April 1979 after a referendum.","note":"This was a major change of government within Iran. It does not imply a new people or an ethnically uniform successor society.","sources":["iran1979","iranModern"],"x":314,"y":3205}],"continuations":[{"map":"south-asia","history":"mughal","label":"Mughal rule → India, Pakistan & Bangladesh"},{"map":"west-asia","history":"cn-ilkhanate","label":"Earlier: Persia, caliphates & the Ilkhanate"},{"map":"seljuqs-anatolia","history":"cn-ilkhanate","label":"Seljuqs, Anatolia & Iran"}],"region":"westasia"},{"id":"africa-modern","title":"West Africa: later realms, colonial borders & independence","width":1600,"height":2070,"nodes":[{"id":"mali","x":40,"y":220,"label":"Mali Empire"},{"id":"songhai","x":410,"y":220,"label":"Songhai Empire"},{"id":"benin","x":820,"y":220,"label":"Kingdom of Benin"},{"id":"bornu","x":1240,"y":220,"label":"Bornu"},{"id":"cn-sahel-regional","x":200,"y":520,"label":"Later Niger-region states"},{"id":"cn-frenchsudan","x":200,"y":820,"label":"French Sudan"},{"id":"cn-nigeriasouth","x":820,"y":820,"label":"Southern colonial jurisdictions"},{"id":"cn-nigerianorth","x":1240,"y":820,"label":"Northern Nigeria"},{"id":"cn-mali-federation","x":200,"y":1140,"label":"Mali Federation"},{"id":"cn-colonial-nigeria","x":1030,"y":1140,"label":"Colonial Nigeria"},{"id":"cn-mali-modern","x":20,"y":1480,"label":"Republic of Mali"},{"id":"cn-senegal","x":410,"y":1480,"label":"Senegal"},{"id":"nigeria","x":1030,"y":1480,"label":"Independent Nigeria"}],"connections":[{"id":"sahel-later-realms","from":["mali","songhai"],"to":["cn-sahel-regional"],"type":"contact","label":"1600s–1800s · later regional histories","dates":"17th–19th centuries","summary":"Bamana, Massina and Toucouleur states later controlled parts of the upper and middle Niger regions.","note":"This indicates shared geography and changing centres of power over a long interval, not direct state succession or unchanged imperial borders.","sources":["maliProfile"],"x":314,"y":430},{"id":"french-sudan-conquest","from":["cn-sahel-regional"],"to":["cn-frenchsudan"],"type":"colonial","label":"Late 1800s · French conquest","dates":"Late 19th century","summary":"French forces conquered regional states and established changing colonial jurisdictions around the Niger.","note":"Resistance continued, and administrative borders shifted. Colonial rule was not a merger agreed by all the region’s peoples.","sources":["maliProfile"],"x":314,"y":730},{"id":"benin-colonial","from":["benin"],"to":["cn-nigeriasouth"],"type":"conquest","label":"1897 · invasion of Benin","dates":"1897","summary":"British forces invaded Benin City, deposed the Oba and looted the palace. Its territory was incorporated into colonial jurisdictions.","note":"Edo communities and the monarchy’s cultural history continued. The Southern Nigeria administration came later; the Benin kingdom is distinct from the modern Republic of Benin.","sources":["benin1897","nigeriaProfile"],"x":934,"y":600},{"id":"bornu-colonial","from":["bornu"],"to":["cn-nigerianorth"],"type":"colonial","label":"Around 1900 · colonial partition","dates":"Late 19th–early 20th centuries","summary":"Colonial expansion incorporated part of the former Bornu region into British Northern Nigeria.","note":"Intervening warfare and partition also placed other Lake Chad territories under French and German rule. This regional connection is not the entire Bornu state changing directly into Nigeria.","sources":["nigeriaProfile"],"x":1354,"y":600},{"id":"mali-federation-independence","from":["cn-frenchsudan"],"to":["cn-mali-federation"],"type":"independence","label":"1959–60 · federation & independence","dates":"1959–1960","summary":"The Sudanese Republic and Senegal formed the Mali Federation, which gained independence from France in June 1960.","note":"Senegal was a separate constituent with its own colonial history; it was not part of French Sudan. Only the Sudanese branch is shown above.","sources":["maliProfile","federation1960"],"x":314,"y":1045},{"id":"nigeria-amalgamation","from":["cn-nigeriasouth","cn-nigerianorth"],"to":["cn-colonial-nigeria"],"type":"union","label":"1914 · colonial amalgamation","dates":"1914","summary":"British administrators joined northern and southern jurisdictions in the Colony and Protectorate of Nigeria.","note":"This was colonial administrative unification of many societies, not the voluntary union of just Benin and Bornu.","sources":["nigeria1914"],"x":1144,"y":1045},{"id":"mali-federation-split","from":["cn-mali-federation"],"to":["cn-mali-modern","cn-senegal"],"type":"division","label":"1960 · federation dissolves","dates":"August–September 1960","summary":"Senegal withdrew in August; the Sudanese Republic adopted the name Republic of Mali in September.","note":"The two modern states followed distinct histories. Their shared federation was not a revival of the medieval Mali Empire.","sources":["mali1960"],"x":314,"y":1360},{"id":"nigeria-independence","from":["cn-colonial-nigeria"],"to":["nigeria"],"type":"independence","label":"1960 · independence","dates":"1 October 1960","summary":"Nigeria became independent of British rule.","note":"A republic followed in 1963. Later constitutional changes, military governments and the civil war belong within the modern history reader.","sources":["nigeria1960"],"x":1144,"y":1360}],"continuations":[{"map":"west-africa","history":"mali","label":"Earlier: Sahel, Kanem–Bornu, Ife & Benin"},{"map":"britain-atlantic","history":"britishempire","label":"Related: the British imperial system"},{"map":"af-sahel-forest","history":"mali","label":"Sahel, Yoruba cities and the Gold Coast"}],"region":"africa"},{"id":"steppe-russia","title":"Golden Horde, Muscovy & Soviet successor states","width":1600,"height":2520,"nodes":[{"id":"cn-goldenhorde","x":600,"y":220,"label":"Golden Horde"},{"id":"cn-kazan","x":200,"y":510,"label":"Khanate of Kazan"},{"id":"cn-greathorde","x":1000,"y":510,"label":"Great Horde"},{"id":"cn-muscovy","x":600,"y":800,"label":"Muscovy"},{"id":"cn-tsardom","x":600,"y":1100,"label":"Tsardom of Russia"},{"id":"russianempire","x":600,"y":1400,"label":"Russian Empire"},{"id":"sovietunion","x":600,"y":1700,"label":"Soviet Union"},{"id":"russiafederation","x":100,"y":2050,"label":"Russian Federation"},{"id":"cn-ukraine","x":650,"y":2050,"label":"Ukraine"},{"id":"cn-kazakhstan","x":1180,"y":2050,"label":"Kazakhstan"}],"connections":[{"id":"horde-fragmentation","from":["cn-goldenhorde"],"to":["cn-kazan","cn-greathorde"],"type":"division","label":"1400s · several successor khanates","dates":"15th century","summary":"The Horde fragmented into competing regional khanates; Kazan and the Great Horde are two examples.","note":"Crimea, Astrakhan, Nogai and other formations had separate paths. The selected branches do not exhaust the Horde’s political or cultural legacy.","sources":["hordeSuccessors"],"x":714,"y":420},{"id":"ugra1480","from":["cn-greathorde"],"to":["cn-muscovy"],"type":"contact","label":"1480 · Ugra standoff","dates":"1480","summary":"The standoff between Ivan III and the Great Horde is conventionally associated with the end of Muscovite tributary subordination.","note":"Muscovy already existed and was not a renamed Horde. The Great Horde continued until 1502 and other khanates survived separately.","sources":["ugra1480"],"x":1114,"y":700},{"id":"tsar1547","from":["cn-muscovy"],"to":["cn-tsardom"],"type":"continuation","label":"1547 · Ivan IV crowned tsar","dates":"1547","summary":"Ivan IV’s coronation as tsar marks the conventional beginning of the Russian tsardom.","note":"An evolving state and title, rather than the sudden creation of a new population or all its later territory.","sources":["russianTitles"],"x":714,"y":1000},{"id":"kazan-conquest","from":["cn-kazan"],"to":["cn-tsardom"],"type":"conquest","label":"1552 · Kazan conquered","dates":"1552","summary":"Ivan IV’s forces conquered Kazan, incorporating its territory into the expanding tsardom.","note":"Tatar communities and traditions continued. Other khanates were conquered at different times or followed other paths.","sources":["kazan1552"],"x":314,"y":1000,"toSide":"left"},{"id":"russian-empire1721","from":["cn-tsardom"],"to":["russianempire"],"type":"continuation","label":"1721 · imperial title","dates":"1721","summary":"Peter I adopted the title of emperor after the Great Northern War.","note":"The change of title followed long state expansion and reform; it does not date the beginning of Russian communities or every imperial territory.","sources":["russianTitles"],"x":714,"y":1300},{"id":"russian-revolutions","from":["russianempire"],"to":["sovietunion"],"type":"continuation","label":"1917–22 · revolutions, war & new union","dates":"1917–1922","summary":"The monarchy fell in 1917. Revolution, civil war and Bolshevik consolidation preceded the formation of the USSR in 1922.","note":"Several former imperial territories became independent. The Soviet Union was formed by constituent republics, not simply by renaming the whole Russian Empire.","sources":["russiaStudy"],"x":714,"y":1600},{"id":"soviet-successors1991","from":["sovietunion"],"to":["russiafederation","cn-ukraine","cn-kazakhstan"],"type":"division","label":"1991 · fifteen independent states","dates":"1991","summary":"The Soviet Union dissolved and its constituent republics became or re-established independent states.","note":"This preview shows three of fifteen states. All fifteen appear in the Soviet regional maps, accessible through Maps & coverage. Regional groupings are navigation aids, not intermediate successor states.","sources":["ussr1991"],"x":764,"y":1930}],"continuations":[{"map":"mongols-china","history":"cn-goldenhorde","label":"Earlier: the Mongol khanates"},{"map":"soviet-europe","history":"sovietunion","label":"Soviet dissolution · Russia and eastern Europe"},{"map":"rus-byzantium-steppe","history":"cn-goldenhorde","label":"Kyivan Rus’, Byzantium & regional principalities"}],"region":"europe"},{"id":"afsu-sudan-nile","title":"Sudan and South Sudan: kingdoms, conquest and independence","region":"africa","nodes":[{"id":"nubia","x":436.4,"y":220},{"id":"afsu-nobatia","x":251.39999999999998,"y":500},{"id":"afsu-makuria","x":308.4,"y":780},{"id":"afsu-alodia","x":629.4,"y":500},{"id":"afsu-funj","x":638.4,"y":780},{"id":"muhammad-ali","x":948.4000000000001,"y":780},{"id":"afsu-turcoegyptian","x":793.4,"y":1060},{"id":"afsu-mahdist","x":793.4,"y":1340},{"id":"britishempire","x":1088.4,"y":1340},{"id":"afsu-condominium","x":940.4000000000001,"y":1620},{"id":"afsu-sudan","x":940.4000000000001,"y":1900},{"id":"afsu-southsudan","x":940.4000000000001,"y":2180}],"connections":[{"id":"afsu-postmeroe","from":["nubia"],"to":["afsu-nobatia","afsu-makuria","afsu-alodia"],"type":"context","label":"Context: later Nubian kingdoms","dates":"4th–6th centuries AD","summary":"After Meroe’s decline, several kingdoms developed in the Nubian Nile region.","note":"Context link, not a documented division of one empire into three states or an assertion of unchanged institutions; Christianisation followed during the sixth century.","sources":["africa_sudan_afsu_medieval","africa_sudan_afsu_soba"],"certainty":"Context","selectedBranch":false,"x":550.4,"y":407},{"id":"afsu-nobatia-union","from":["afsu-nobatia"],"to":["afsu-makuria"],"type":"union","label":"Nobatia and Makuria united","dates":"By the early medieval period · precise date uncertain","summary":"Nobatia came under a ruler shared with Makuria, while retaining regional institutions.","note":"The date and circumstances are uncertain; this does not imply that Alodia joined them.","sources":["africa_sudan_afsu_medieval"],"selectedBranch":false,"x":366.4,"y":687},{"id":"afsu-alodia-funj","from":["afsu-alodia"],"to":["afsu-funj"],"type":"context","label":"Context: changing regional rule","dates":"Late medieval–early 16th century","summary":"The Funj sultanate rose in the central Nile region after the decline of Alodian authority.","note":"Context, not a secure direct succession: later chronicles associate Soba’s destruction with 1504, but the excavated city shows earlier decline, and the chronology and agents of the political transformation remain disputed.","sources":["africa_sudan_afsu_soba","africa_sudan_afsu_funj_origins"],"certainty":"Context","selectedBranch":false,"x":752.4,"y":687},{"id":"afsu-funj-conquest","from":["afsu-funj"],"to":["afsu-turcoegyptian"],"type":"conquest","label":"Egyptian conquest ends Funj rule","dates":"1820–1821 AD","summary":"Forces sent by Muhammad Ali conquered the Funj sultanate and established Egyptian administration.","note":"This was conquest and new colonial government, not a peaceful dynastic inheritance; control over other Sudanese territories expanded at different times.","sources":["africa_sudan_afsu_funj","africa_sudan_afsu_egyptsudan","africa_sudan_afsu_condominium"],"selectedBranch":false,"x":752.4,"y":967},{"id":"afsu-egyptian-expansion","from":["muhammad-ali"],"to":["afsu-turcoegyptian"],"type":"colonial","label":"Egyptian territorial expansion","dates":"From 1820 AD","summary":"Muhammad Ali’s Egyptian government sent armies south and imposed rule over Sudanese territories.","note":"The Egyptian dynasty operated within a changing Ottoman imperial framework; the term Turco-Egyptian does not imply all inhabitants were Turkish or Egyptian.","sources":["africa_sudan_afsu_egyptsudan","africa_sudan_afsu_condominium"],"selectedBranch":false,"x":1062.4,"y":967},{"id":"afsu-mahdist-revolution","from":["afsu-turcoegyptian"],"to":["afsu-mahdist"],"type":"conquest","label":"Mahdist revolt and capture of Khartoum","dates":"1881–1885 AD","summary":"The Mahdist movement defeated Egyptian government forces and captured Khartoum in January 1885.","note":"The revolt began before the capture; Egyptian and British forces retained some peripheral positions, and not every community supported the Mahdist government.","sources":["africa_sudan_afsu_egyptsudan"],"selectedBranch":false,"x":907.4,"y":1247},{"id":"afsu-angloegyptian-conquest","from":["afsu-mahdist"],"to":["afsu-condominium"],"type":"conquest","label":"Anglo-Egyptian conquest","dates":"1896–1899 AD","summary":"British-led Anglo-Egyptian armies defeated the Mahdist state, and the 1899 agreements established joint colonial rule.","note":"The decisive defeat at Omdurman occurred in 1898; fighting continued into 1899, so military conquest and the legal creation of the condominium are distinct stages.","sources":["africa_sudan_afsu_egyptsudan","africa_sudan_afsu_condominium"],"selectedBranch":false,"x":907.4,"y":1527},{"id":"afsu-british-rule","from":["britishempire"],"to":["afsu-condominium"],"type":"colonial","label":"British-led colonial administration","dates":"1899–1956 AD","summary":"Sudan was administered under a formal Anglo-Egyptian condominium in which British authority predominated.","note":"This was legally distinct from simply annexing Sudan as an ordinary British colony; Egyptian claims and participation persisted.","sources":["africa_sudan_afsu_condominium"],"selectedBranch":false,"x":1202.4,"y":1527},{"id":"afsu-sudan-independence","from":["afsu-condominium"],"to":["afsu-sudan"],"type":"independence","label":"Sudan becomes independent","dates":"1 January 1956 AD","summary":"Sudan became independent of the Anglo-Egyptian condominium.","note":"The independent state initially included the territory that later became South Sudan; independence did not resolve internal conflicts or guarantee one continuous constitutional order.","sources":["africa_sudan_afsu_independence","africa_sudan_afsu_southsudan"],"selectedBranch":false,"x":1054.4,"y":1807},{"id":"afsu-south-sudan-independence","from":["afsu-sudan"],"to":["afsu-southsudan"],"type":"independence","label":"South Sudan secedes after referendum","dates":"9 July 2011 AD","summary":"South Sudan became an independent state after the January 2011 referendum.","note":"Sudan continued as a state after the separation; this was not the replacement of Sudan by South Sudan, and it does not imply that all boundary questions were resolved.","sources":["africa_sudan_afsu_southsudan"],"selectedBranch":false,"x":1054.4,"y":2087}],"autoLayout":true,"continuations":[{"map":"af-nile-egypt","history":"nubia","label":"Nile Valley: Egypt, Nubia and changing rulers"},{"map":"af-kongo-south","history":"britishempire","label":"Kongo, Atlantic contacts and southern African states"}],"width":1600,"height":2604},{"id":"af-nile-egypt","title":"Nile Valley: Egypt, Nubia and changing rulers","region":"africa","nodes":[{"id":"nubia","x":561.75,"y":220},{"id":"egypt","x":561.75,"y":500},{"id":"persia","x":561.75,"y":780},{"id":"cn-alexander","x":561.75,"y":1060},{"id":"cn-ptolemaic","x":561.75,"y":1340},{"id":"rome","x":561.75,"y":1900},{"id":"byzantium","x":561.75,"y":2180},{"id":"rashidun","x":561.75,"y":2460},{"id":"umayyad","x":561.75,"y":2740},{"id":"abbasid","x":561.75,"y":3020},{"id":"af-egypt-regional","label":"Egypt: changing governments","x":561.75,"y":3300},{"id":"fatimid","x":561.75,"y":3580},{"id":"ayyubid","x":561.75,"y":3860},{"id":"mamluk","x":561.75,"y":4140},{"id":"ottoman","x":561.75,"y":4420},{"id":"muhammad-ali","x":650.75,"y":4700},{"id":"britishempire","x":889.75,"y":4420},{"id":"egyptmodern","x":796.75,"y":4980},{"id":"romanrepublic","x":561.75,"y":1620}],"connections":[{"id":"af-nile-exchange","from":["nubia"],"to":["egypt"],"type":"contact","label":"Trade, migration and conflict","dates":"3rd–1st millennia BC","summary":"Nubian societies and Egyptian kingdoms exchanged goods and people and fought over access and authority along the Nile.","note":"The relationship changed direction over time; neither region was permanently subordinate or culturally uniform.","sources":["africa_af_nubia"],"bidirectional":true,"selectedBranch":false,"x":535.75,"y":407},{"id":"af-kushite-egypt","from":["nubia"],"to":["egypt"],"type":"conquest","label":"Kushite pharaohs in Egypt","dates":"8th–7th centuries BC","summary":"Kushite kings extended their rule into Egypt and formed its Twenty-fifth Dynasty.","note":"This selected episode sits within both broad timeline frames; Kushite rule did not begin all Egyptian or Nubian history.","sources":["africa_af_nubia"],"selectedBranch":false,"x":815.75,"y":407},{"id":"af-egypt-persia","from":["egypt"],"to":["persia"],"type":"conquest","label":"Persian conquest of Egypt","dates":"525 BC","summary":"Cambyses defeated Egypt’s last Twenty-sixth-Dynasty ruler and brought Egypt into Achaemenid rule.","note":"Egypt later regained independence before a second Persian conquest; this was not uninterrupted Persian government until Alexander.","sources":["africa_af_egyptmuseum"],"selectedBranch":false,"x":675.75,"y":687},{"id":"af-egypt-alexander","from":["persia"],"to":["cn-alexander"],"type":"conquest","label":"Alexander enters Egypt","dates":"332 BC","summary":"Alexander took Egypt from Achaemenid control during his campaigns against the Persian Empire.","note":"The Persian Empire and Alexander’s campaigns extended far beyond Egypt. Egyptian communities and institutions continued.","sources":["africa_af_ptolemy"],"selectedBranch":false,"x":675.75,"y":967},{"id":"af-egypt-ptolemy","from":["cn-alexander"],"to":["cn-ptolemaic"],"type":"division","label":"Ptolemaic kingship","dates":"After 323 BC; kingship 305 BC","summary":"The struggles among Alexander’s successors produced Ptolemaic kingship in Egypt.","note":"Ptolemy governed Egypt before adopting the royal title; other successor kingdoms emerged elsewhere.","sources":["africa_af_ptolemy"],"selectedBranch":true,"x":675.75,"y":1247},{"id":"af-egypt-rome","from":["cn-ptolemaic"],"to":["romanrepublic"],"type":"conquest","label":"Egypt annexed by Rome","dates":"30 BC","summary":"Octavian’s conquest ended Ptolemaic royal government and placed Egypt under Roman administration.","note":"Annexation occurred before the conventional imperial starting date of 27 BC. Roman government did not end Egyptian culture.","sources":["africa_af_romanegypt"],"selectedBranch":false,"x":675.75,"y":1527},{"id":"af-egypt-byzantium","from":["rome"],"to":["byzantium"],"type":"continuation","label":"Eastern Roman government","dates":"4th century AD onward","summary":"Egypt remained within the Roman state as its eastern imperial administration centred on Constantinople.","note":"This is overlapping periodisation within a continuing empire, not an Egyptian state newly founded or a clean cultural break in 330 or 395.","sources":["africa_af_coptic","africa_af_romanegypt"],"selectedBranch":false,"x":675.75,"y":2087},{"id":"af-egypt-arab-conquest","from":["byzantium"],"to":["rashidun"],"type":"conquest","label":"Arab-Muslim conquest","dates":"640s AD","summary":"Arab-Muslim armies conquered Byzantine Egypt and established government based at Fustat.","note":"Military and administrative change did not cause immediate universal conversion; Coptic Christian communities continued.","sources":["africa_af_coptic"],"selectedBranch":false,"x":675.75,"y":2367},{"id":"af-egypt-umayyad","from":["rashidun"],"to":["umayyad"],"type":"continuation","label":"Egypt under Umayyad rule","dates":"661 AD","summary":"Egypt became a province of the Damascus-based Umayyad caliphate.","note":"This was a change of ruling authority within the early Islamic state, not the origin of Egypt’s population or all its traditions.","sources":["africa_af_umayyad"],"selectedBranch":false,"x":675.75,"y":2647},{"id":"af-egypt-abbasid","from":["umayyad"],"to":["abbasid"],"type":"continuation","label":"Abbasid provincial rule","dates":"750 AD","summary":"The Abbasid revolution brought Egypt under the new caliphal dynasty.","note":"Egypt’s provincial connection should not be read as uninterrupted direct Baghdad control throughout the Abbasid period.","sources":["africa_af_egypt500"],"selectedBranch":false,"x":675.75,"y":2927},{"id":"af-egypt-regional-rule","from":["abbasid"],"to":["af-egypt-regional"],"type":"continuation","label":"Autonomous and restored governments","dates":"868–969 AD","summary":"Egypt passed through Tulunid government, restored direct Abbasid rule and Ikhshidid government.","note":"These are three successive arrangements grouped in one explicitly labelled transition frame, with continuing Abbasid religious allegiance.","sources":["africa_af_egypt500"],"selectedBranch":false,"x":675.75,"y":3207},{"id":"af-fatimid-egypt","from":["af-egypt-regional"],"to":["fatimid"],"type":"conquest","label":"Fatimids conquer Egypt","dates":"969 AD","summary":"Fatimid forces took Egypt and established Cairo, later making it their capital.","note":"The Fatimid caliphate began in North Africa in 909; 969 dates its Egyptian expansion rather than the foundation of the dynasty.","sources":["africa_af_fatimid"],"selectedBranch":false,"x":675.75,"y":3487},{"id":"af-ayyubid-egypt","from":["fatimid"],"to":["ayyubid"],"type":"continuation","label":"Saladin ends Fatimid rule","dates":"1171 AD","summary":"Saladin ended the Fatimid caliphate and established Ayyubid government in Egypt.","note":"A political and religious reorientation did not replace all inhabitants or erase Fatimid institutions and artistic traditions.","sources":["africa_af_ayyubid"],"selectedBranch":false,"x":675.75,"y":3767},{"id":"af-mamluk-egypt","from":["ayyubid"],"to":["mamluk"],"type":"continuation","label":"Mamluks take power in Egypt","dates":"1250 AD","summary":"Mamluk leaders overthrew the last independent Ayyubid sultan in Egypt and established their own sultanate.","note":"Ayyubid branches continued in Syria and elsewhere; the Egyptian event does not end every Ayyubid polity in 1250.","sources":["africa_af_ayyubid","africa_af_mamluk"],"selectedBranch":false,"x":675.75,"y":4047},{"id":"af-ottoman-egypt","from":["mamluk"],"to":["ottoman"],"type":"conquest","label":"Ottoman conquest","dates":"1516–1517 AD","summary":"Ottoman campaigns defeated the Mamluk sultanate and incorporated Syria and Egypt into the Ottoman Empire.","note":"Mamluk elites and institutions persisted after the sultanate ended; Ottoman rule had regional variation.","sources":["africa_af_mamluk"],"selectedBranch":false,"x":675.75,"y":4327},{"id":"af-muhammadali","from":["ottoman"],"to":["muhammad-ali"],"type":"continuation","label":"Muhammad Ali appointed","dates":"1805 AD","summary":"Muhammad Ali became Ottoman governor of Egypt in 1805 and founded a dynasty whose hereditary rule was formally recognised in 1841.","note":"This followed French occupation and renewed Ottoman intervention; growing Egyptian autonomy did not immediately end Ottoman suzerainty.","sources":["africa_af_nmec","africa_af_egypt1841"],"selectedBranch":false,"x":675.75,"y":4607},{"id":"af-british-egypt","from":["britishempire"],"to":["muhammad-ali"],"type":"colonial","label":"British occupation","dates":"1882 AD","summary":"Britain occupied Egypt while the Muhammad Ali dynasty remained in office.","note":"Occupation, dynastic rule and Ottoman suzerainty overlapped; Britain declared a protectorate only in 1914.","sources":["africa_af_egyptsudan"],"selectedBranch":false,"x":902.75,"y":4607},{"id":"af-egypt-independence","from":["britishempire"],"to":["egyptmodern"],"type":"independence","label":"Limited independence recognised","dates":"1922 AD","summary":"Britain ended its formal protectorate and recognised Egypt as a sovereign state while reserving several matters for later agreement.","note":"British military presence and restrictions remained; this was not complete immediate withdrawal.","sources":["africa_af_egypt1922"],"selectedBranch":false,"x":1056.75,"y":4747},{"id":"af-egypt-republic","from":["muhammad-ali"],"to":["egyptmodern"],"type":"continuation","label":"Monarchy ends; republic declared","dates":"1952–1953 AD","summary":"The 1952 revolution was followed by abolition of the monarchy and proclamation of a republic in 1953.","note":"The destination frame begins with limited independence in 1922 and includes this later constitutional rupture; the two timeline blocks intentionally overlap.","sources":["africa_af_egypt1953"],"selectedBranch":false,"x":807.75,"y":4887},{"id":"af-republic-imperial-rule","from":["romanrepublic"],"to":["rome"],"type":"continuation","label":"Augustus and imperial government","dates":"27 BC","summary":"Octavian received the title Augustus as Roman government took the form conventionally called the Principate.","note":"The conventional start of the Roman Empire did not create a new Egyptian population or end every republican institution.","sources":["africa_af_romanegypt"],"selectedBranch":false,"x":675.75,"y":1807}],"autoLayout":true,"continuations":[{"map":"afsu-sudan-nile","history":"nubia","label":"Sudan and South Sudan: kingdoms, conquest and independence"},{"map":"af-horn-indian-ocean","history":"byzantium","label":"Horn of Africa and the Indian Ocean coast"},{"map":"af-kongo-south","history":"britishempire","label":"Kongo, Atlantic contacts and southern African states"}],"width":1600,"height":5404},{"id":"af-horn-indian-ocean","title":"Horn of Africa and the Indian Ocean coast","region":"africa","nodes":[{"id":"aksum","x":240.39999999999998,"y":220},{"id":"byzantium","x":87.39999999999998,"y":500},{"id":"af-zagwe","x":393.4,"y":500},{"id":"ethiopia","x":393.4,"y":780},{"id":"af-ethiopia-republican","x":393.4,"y":1060},{"id":"af-eritrea","x":393.4,"y":1340},{"id":"zimbabwe","x":841.4,"y":220},{"id":"kilwa","x":841.4,"y":500},{"id":"cn-portugal","x":691.4,"y":780},{"id":"af-zanzibar-coast","x":986.4000000000001,"y":780},{"id":"af-german-eastafrica","x":701.4,"y":1060},{"id":"af-tanganyika-territory","x":706.4,"y":1340},{"id":"af-tanganyika","x":843.4,"y":1680},{"id":"af-zanzibar-independent","x":1115.4,"y":1510},{"id":"af-tanzania","x":935.4000000000001,"y":1960},{"id":"af-kenya-colonial","x":986.4000000000001,"y":1060},{"id":"kenya","x":986.4000000000001,"y":1340}],"connections":[{"id":"af-aksum-byzantium","from":["aksum"],"to":["byzantium"],"type":"contact","label":"Trade and Christian networks","dates":"Late antiquity","summary":"Aksum and the eastern Roman world participated in commercial, religious and artistic networks across the Red Sea and eastern Mediterranean.","note":"Contact did not mean Aksum was a Byzantine province or that African Christianity had only one origin.","sources":["africa_af_ethiopiabyzantium"],"bidirectional":true,"selectedBranch":false,"x":201.39999999999998,"y":407},{"id":"af-aksum-zagwe","from":["aksum"],"to":["af-zagwe"],"type":"contact","label":"Later highland Christian kingdoms","dates":"After Aksum; c. 11th–13th centuries","summary":"Later highland kingdoms including the Zagwe preserved and developed Christian traditions after Aksumite political power declined.","note":"The intervening political sequence is incompletely known: this is a qualified cultural and regional connection, not proven unbroken dynastic succession.","sources":["africa_af_ethiopianchristian"],"selectedBranch":false,"x":507.4,"y":407},{"id":"af-zagwe-solomonic","from":["af-zagwe"],"to":["ethiopia"],"type":"continuation","label":"Solomonic dynasty takes power","dates":"1270 AD","summary":"Yekuno Amlak displaced Zagwe rule and established the dynasty conventionally called Solomonic.","note":"The dynasty’s claim to descend from biblical Solomon is a legitimising tradition, not an independently demonstrated genealogy.","sources":["africa_af_zagwe"],"selectedBranch":false,"x":507.4,"y":687},{"id":"af-ethiopia-revolution","from":["ethiopia"],"to":["af-ethiopia-republican"],"type":"continuation","label":"Monarchy overthrown","dates":"1974 AD","summary":"The Derg deposed Haile Selassie and replaced imperial government with military rule.","note":"This begins a broad post-monarchical frame containing later changes of regime, not a single uninterrupted republic.","sources":["africa_af_ethiopia1974"],"selectedBranch":false,"x":507.4,"y":967},{"id":"af-eritrea-independence","from":["af-ethiopia-republican"],"to":["af-eritrea"],"type":"independence","label":"Eritrean independence","dates":"1991–1993 AD","summary":"Eritrean military victory and a UN-supervised referendum led to recognised independence from Ethiopia.","note":"Ethiopia continued as a state; the modern Eritrean border and independence process are not a simple redivision of ancient Aksum.","sources":["africa_af_eritrea"],"selectedBranch":false,"x":507.4,"y":1247},{"id":"af-zimbabwe-kilwa","from":["zimbabwe"],"to":["kilwa"],"type":"contact","label":"Gold and Indian Ocean trade","dates":"Medieval period","summary":"Great Zimbabwe was connected through long-distance trade to the Indian Ocean coast, with Kilwa coins among its imported finds.","note":"Goods travelled through networks and intermediaries; an imported coin is not proof that Great Zimbabwe was ruled by Kilwa or that every shipment went directly between the two cities.","sources":["africa_af_zimbabwe"],"bidirectional":true,"selectedBranch":false,"x":955.4,"y":407},{"id":"af-kilwa-portugal","from":["kilwa"],"to":["cn-portugal"],"type":"conquest","label":"Portuguese fort and occupation","dates":"Early 16th century","summary":"Portuguese forces established a fort at Kilwa during their expansion along the East African coast.","note":"Their occupation was limited and contested; the Portuguese kingdom did not originate in Kilwa, and Swahili communities continued.","sources":["africa_af_kilwa"],"selectedBranch":false,"x":805.4,"y":687},{"id":"af-kilwa-zanzibar","from":["kilwa"],"to":["af-zanzibar-coast"],"type":"continuation","label":"Omani and Zanzibar authority","dates":"18th–19th centuries","summary":"Omani Busaidi rulers based in Zanzibar later exercised authority at Kilwa and adapted its buildings for their administration.","note":"This selected later episode follows intervening local histories; coastal authority varied and does not imply all Swahili cities formed one uninterrupted empire.","sources":["africa_af_kilwaoman"],"selectedBranch":false,"x":1100.4,"y":687},{"id":"af-zanzibar-german","from":["af-zanzibar-coast"],"to":["af-german-eastafrica"],"type":"colonial","label":"German mainland expansion","dates":"1880s–1890s AD","summary":"German colonial expansion displaced local authorities and acquired control of mainland coastal jurisdictions associated with Zanzibar.","note":"The mainland and island sultanate had different legal histories; Zanzibar itself did not become part of German East Africa.","sources":["africa_af_tanganyikareport"],"selectedBranch":false,"x":805.4,"y":967},{"id":"af-eastafrica-tanganyika","from":["af-german-eastafrica"],"to":["af-tanganyika-territory"],"type":"division","label":"Postwar partition and mandate","dates":"After 1918 AD","summary":"The postwar division of German East Africa placed the mainland territory later called Tanganyika under British administration.","note":"Rwanda and Burundi went to Belgian administration and the Kionga Triangle to Portugal; Tanganyika was only one successor jurisdiction.","sources":["africa_af_eastafricapartition"],"selectedBranch":true,"x":817.4,"y":1247},{"id":"af-tanganyika-independence","from":["af-tanganyika-territory"],"to":["af-tanganyika"],"type":"independence","label":"Tanganyika independent","dates":"1961 AD","summary":"Tanganyika became independent from British administration.","note":"It became a republic in 1962 before union with Zanzibar; the event does not date the beginning of its peoples or communities.","sources":["africa_af_unterritories"],"selectedBranch":false,"x":920.4,"y":1557},{"id":"af-tanzania-union","from":["af-tanganyika","af-zanzibar-independent"],"to":["af-tanzania"],"type":"union","label":"Tanganyika and Zanzibar unite","dates":"26 April 1964","summary":"Tanganyika and Zanzibar joined to form the union later named Tanzania.","note":"Zanzibar retained institutions within the union; its independence in 1963 and revolution in January 1964 preceded the agreement.","sources":["africa_af_tanzaniaunion"],"selectedBranch":false,"x":1049.4,"y":1867},{"id":"af-zanzibar-kenyacoast","from":["af-zanzibar-coast"],"to":["af-kenya-colonial"],"type":"colonial","label":"Coastal protectorate administered","dates":"1895–1963 AD","summary":"Britain administered the Sultan of Zanzibar’s mainland coastal protectorate together with colonial Kenya.","note":"The coastal protectorate had a legal status distinct from the inland colony until independence; the edge does not place all Zanzibar under Kenyan government.","sources":["africa_af_kenyacoast"],"selectedBranch":false,"x":1100.4,"y":967},{"id":"af-kenya-independence","from":["af-kenya-colonial"],"to":["kenya"],"type":"independence","label":"Kenya independent","dates":"12 December 1963","summary":"Kenya became independent of British rule and the separate coastal arrangement ended.","note":"A republic followed in 1964; the modern state joined regions with diverse earlier histories.","sources":["africa_af_kenya","africa_af_kenyacoast"],"selectedBranch":false,"x":1100.4,"y":1247},{"id":"af-zanzibar-independence-revolution","from":["af-zanzibar-coast"],"to":["af-zanzibar-independent"],"type":"continuation","label":"Independence and revolution","dates":"1963–1964 AD","summary":"Zanzibar became independent under a sultanate before the January 1964 revolution replaced the monarchy with a republic.","note":"This concerns the islands and their government, not all territories formerly influenced by Omani or Zanzibar rulers along the mainland coast.","sources":["africa_af_zanzibar1964"],"selectedBranch":false,"x":1402.4,"y":967}],"autoLayout":true,"continuations":[{"map":"af-kongo-south","history":"cn-portugal","label":"Kongo, Atlantic contacts and southern African states"},{"map":"af-nile-egypt","history":"byzantium","label":"Nile Valley: Egypt, Nubia and changing rulers"}],"width":1600,"height":2384},{"id":"af-sahel-forest","title":"Sahel, Yoruba cities and the Gold Coast","region":"africa","nodes":[{"id":"ghana","x":60.09999999999991,"y":220},{"id":"mali","x":195.0999999999999,"y":520},{"id":"jenne","x":470.0999999999999,"y":220},{"id":"songhai","x":604.0999999999999,"y":520},{"id":"ife","x":1015.0999999999999,"y":220},{"id":"oyo","x":939.0999999999999,"y":520},{"id":"asante","x":1389.1,"y":220},{"id":"af-goldcoast","label":"Gold Coast & neighbouring territories","x":1389.1,"y":520},{"id":"ghanamodern","x":1389.1,"y":800},{"id":"nok","x":1664.1,"y":220},{"id":"nigeria","x":1664.1,"y":520},{"id":"colonialafrica","x":1985.1,"y":220},{"id":"cn-colonial-nigeria","x":1985.1,"y":520}],"connections":[{"id":"af-ghana-mali","from":["ghana"],"to":["mali"],"type":"contact","label":"Changing Sahelian centres","dates":"13th century onward","summary":"Mali rose within western Sahelian trading and political networks that had earlier sustained Ghana/Wagadu.","note":"This is regional reconfiguration, not proof that Ghana uniformly merged into Mali on one date; Ghana’s decline and Mali’s expansion were uneven.","sources":["africa_af_sahel"],"selectedBranch":false,"x":174.0999999999999,"y":417},{"id":"af-jenne-mali","from":["jenne"],"to":["mali"],"type":"contact","label":"Inland Niger urban networks","dates":"13th–14th centuries","summary":"Jenne-jeno and the surrounding Inland Niger Delta formed part of the commercial and political landscape of the Mali era.","note":"The archaeological city and later Jenne are distinct settlements; urban communities had their own histories and were not created by imperial conquest.","sources":["africa_af_jenne","africa_af_sahel"],"selectedBranch":false,"x":446.0999999999999,"y":417},{"id":"af-jenne-songhai","from":["jenne"],"to":["songhai"],"type":"contact","label":"Later Jenne under Songhai","dates":"15th–16th centuries","summary":"Songhai expanded its authority over the Inland Niger Delta and later Jenne after the main occupation phase of Jenne-jeno.","note":"The plotted Jenne-jeno block ends around 1400; this link explicitly follows the neighbouring city and regional urban history rather than claiming the old settlement remained the same imperial capital.","sources":["africa_af_jenne"],"selectedBranch":false,"x":718.0999999999999,"y":417},{"id":"af-oyo-ife","from":["ife"],"to":["oyo"],"type":"contact","label":"Royal traditions connect Yoruba cities","dates":"Medieval traditions; later imperial phase","summary":"Ife and Oyo are linked in Yoruba royal traditions associated with Oranmiyan.","note":"Oral dynastic traditions are not proof that Oyo simply descended as a state from Ife; the Oyo timeline selects its much later imperial expansion.","sources":["africa_af_yorubatraditions"],"certainty":"Tradition","selectedBranch":false,"x":1031.1,"y":417},{"id":"af-oyo-ife-trade","from":["oyo"],"to":["ife"],"type":"contact","label":"Niger-to-Ife trade routes","dates":"Medieval centuries","summary":"Oyo channelled goods from Niger-region trading networks towards Ife and other Yoruba centres.","note":"This concerns the city’s earlier commercial history rather than dating the beginning of the imperial expansion block; no political merger is implied.","sources":["africa_af_ifetrade"],"bidirectional":true,"selectedBranch":false,"x":1201.1,"y":707},{"id":"af-asante-colonial","from":["asante"],"to":["af-goldcoast"],"type":"conquest","label":"Asante annexation","dates":"1901–1902 AD","summary":"Britain annexed Asante and established colonial government under an official responsible to the Gold Coast governor.","note":"Ashanti had a separate colonial legal status, and the Asante monarchy and communities continued; this was not annexation to the Gold Coast Colony itself.","sources":["africa_af_asante1902","africa_af_ghanaconstitution"],"selectedBranch":false,"x":1503.1,"y":417},{"id":"af-ghana-independence","from":["af-goldcoast"],"to":["ghanamodern"],"type":"independence","label":"Ghana independent","dates":"6 March 1957","summary":"The Gold Coast, Ashanti, Northern Territories and British Togoland became independent as Ghana.","note":"The four territories had different legal histories; modern Ghana is geographically and politically distinct from medieval Ghana/Wagadu.","sources":["africa_af_ghana1957","africa_af_ghanaconstitution"],"selectedBranch":false,"x":1503.1,"y":707},{"id":"af-nok-museum-heritage","from":["nok"],"to":["nigeria"],"type":"context","label":"Archaeological heritage, not succession","dates":"1928–present · rediscovery and museums","summary":"Nok terracottas discovered in central Nigeria became part of the archaeological and museum heritage of modern Nigeria.","note":"This is a heritage and geographical link only: there is no established direct dynastic succession from Nok culture to the Nigerian state or to a named later kingdom. The discovery began before independence.","sources":["africa_af_nok"],"basis":"heritage","selectedBranch":false,"x":1778.1,"y":417},{"id":"af-colonial-nigeria-context","from":["colonialafrica"],"to":["cn-colonial-nigeria"],"type":"context","label":"One jurisdiction within the wider era","dates":"1914–1960 AD","summary":"Colonial Nigeria is one specific British jurisdiction within the atlas’s broader African colonial-period overview.","note":"This is a period-to-example relationship, not a merger or a claim that all Africa had the same rulers or independence date.","sources":["africa_af_nigeriaarchives"],"basis":"period-example","selectedBranch":false,"x":2099.1,"y":417}],"autoLayout":true,"continuations":[{"map":"africa-modern","history":"mali","label":"West Africa: later realms, colonial borders & independence"},{"map":"west-africa","history":"mali","label":"West Africa: several kinds of connection"},{"map":"af-kongo-south","history":"ghanamodern","label":"Kongo, Atlantic contacts and southern African states"}],"width":2313,"height":1224},{"id":"af-kongo-south","title":"Kongo, Atlantic contacts and southern African states","region":"africa","nodes":[{"id":"kongo","x":421,"y":220},{"id":"cn-portugal","x":81,"y":500},{"id":"af-portuguese-angola","x":415,"y":500},{"id":"af-angola","x":665,"y":780},{"id":"britishempire","x":1261,"y":220},{"id":"af-cape","x":1261,"y":500},{"id":"af-natal","x":1536,"y":500},{"id":"af-transvaal-colony","x":1811,"y":500},{"id":"af-orange-colony","x":2086,"y":500},{"id":"southafricamodern","x":1673,"y":780},{"id":"af-southafrica-democratic","x":1673,"y":1060},{"id":"colonialafrica","x":986,"y":500},{"id":"ghanamodern","x":963,"y":780},{"id":"kenya","x":1238,"y":780}],"connections":[{"id":"af-kongo-portugal","from":["kongo"],"to":["cn-portugal"],"type":"contact","label":"Diplomacy and Christian exchange","dates":"From 1483 AD","summary":"Portuguese contact with Kongo led to diplomacy and religious and artistic exchanges between their rulers and communities.","note":"Early contact did not mean immediate Portuguese conquest or an equal relationship throughout later centuries; the slave trade and colonial warfare transformed the relationship.","sources":["africa_af_kongoportugal"],"bidirectional":true,"selectedBranch":false,"x":195,"y":407},{"id":"af-kongo-colonial","from":["kongo"],"to":["af-portuguese-angola"],"type":"colonial","label":"Colonial expansion in the Kongo region","dates":"19th–early 20th centuries","summary":"Portuguese colonial expansion absorbed the southern Kongo region into Angola as Kongo political authority weakened.","note":"This shows only the Angolan branch: Kongo communities also live in both modern Congos, and the colonial territory was not simply the old kingdom renamed. No claim is made that all Kongo lands passed to Portugal.","sources":["africa_af_kongocolonial","africa_af_kongoheritage"],"selectedBranch":false,"x":535,"y":407},{"id":"af-angola-independence","from":["af-portuguese-angola"],"to":["af-angola"],"type":"independence","label":"Angola independent","dates":"11 November 1975","summary":"Portuguese rule ended as Angola became independent amid fighting between rival nationalist movements.","note":"This was not a peaceful agreed merger or the restoration of Kongo; independence was followed by civil war.","sources":["africa_af_angola"],"selectedBranch":false,"x":526,"y":687},{"id":"af-kongo-modern-heritage","from":["kongo"],"to":["af-angola"],"type":"context","label":"Mbanza Kongo: living heritage","dates":"Present day","summary":"The former Kongo capital, Mbanza Kongo, survives as a cultural and spiritual heritage site in present-day Angola.","note":"A heritage link is not a claim that Angola alone inherits Kongo peoples, culture or territory.","sources":["africa_af_kongoheritage"],"basis":"heritage","selectedBranch":false,"x":779,"y":687},{"id":"af-cape-british","from":["britishempire"],"to":["af-cape"],"type":"colonial","label":"British occupation of the Cape","dates":"1795; again 1806 AD","summary":"Britain occupied the Cape during wars with European rivals and retained control after its second occupation.","note":"The Cape settlement began under Dutch rule in 1652, and colonial expansion involved African dispossession and resistance.","sources":["africa_af_southafrica"],"selectedBranch":false,"x":1375,"y":407},{"id":"af-southafrican-union","from":["af-cape","af-natal","af-transvaal-colony","af-orange-colony"],"to":["southafricamodern"],"type":"union","label":"Four colonies form the Union","dates":"31 May 1910","summary":"The Cape, Natal, Transvaal and Orange River colonies joined in the Union of South Africa.","note":"The Union was a self-governing British dominion dominated by white political power and excluded most South Africans; this was not universal democratic unification.","sources":["africa_af_southafricaunion"],"selectedBranch":false,"x":1787,"y":687},{"id":"af-southafrican-democracy","from":["southafricamodern"],"to":["af-southafrica-democratic"],"type":"continuation","label":"Transition to universal suffrage","dates":"1994 AD","summary":"South Africa held its first national democratic election based on universal adult suffrage under an interim constitution.","note":"This was a constitutional and political transformation within the state; earlier segregation and apartheid are not equivalent to the later democratic order.","sources":["africa_af_southafrica"],"selectedBranch":false,"x":1787,"y":967},{"id":"af-colonial-decolonization","from":["colonialafrica"],"to":["ghanamodern","kenya","af-angola"],"type":"context","label":"Different paths out of colonial rule","dates":"1957–1975 AD · selected examples","summary":"Ghana, Kenya and Angola illustrate separate decolonisation processes in different years and colonial systems.","note":"The starting box is a broad era, not a state that split into these three countries; these are examples, not an exhaustive list of African independence movements.","sources":["africa_af_decolonization","africa_af_unterritories"],"basis":"period-example","selectedBranch":false,"x":1100,"y":687}],"autoLayout":true,"continuations":[{"map":"af-horn-indian-ocean","history":"cn-portugal","label":"Horn of Africa and the Indian Ocean coast"},{"map":"af-sahel-forest","history":"colonialafrica","label":"Sahel, Yoruba cities and the Gold Coast"},{"map":"af-nile-egypt","history":"britishempire","label":"Nile Valley: Egypt, Nubia and changing rulers"}],"width":2374,"height":1484},{"id":"mesoamerica-caribbean","title":"Mesoamerica & the Caribbean","region":"americas","nodes":[{"id":"olmec","x":410.5,"y":220},{"id":"teotihuacan","x":686.5,"y":220},{"id":"maya","x":686.5,"y":500},{"id":"mexica","x":410.5,"y":500},{"id":"poster-newspain","x":410.5,"y":780},{"id":"mexicomodern","x":410.5,"y":1060},{"id":"ao-maya-peoples","x":686.5,"y":780},{"id":"francekingdom","x":961.5,"y":220},{"id":"ao-saint-domingue","x":961.5,"y":500},{"id":"haiti","x":961.5,"y":780}],"connections":[{"id":"ao-olmec-mexica","from":["olmec"],"to":["mexica"],"type":"contact","label":"Ancient objects reused","dates":"15th–early 16th centuries","summary":"Mexica offerings included an Olmec mask made roughly two millennia earlier.","note":"A documented reuse of ancient art, not evidence of a continuous Olmec–Aztec empire.","sources":["americas_oceania_ao_olmec"],"selectedBranch":false,"x":524.5,"y":407},{"id":"ao-teotihuacan-maya","from":["teotihuacan"],"to":["maya"],"type":"contact","label":"Exchange & artistic connections","dates":"4th–6th centuries AD","summary":"Teotihuacan interacted with Maya capitals including Tikal and Copán, with objects and artistic forms crossing regional boundaries.","note":"Different cities maintained different relationships; this is not a claim that all Maya lands belonged to Teotihuacan.","sources":["americas_oceania_ao_teotihuacan"],"selectedBranch":false,"x":800.5,"y":407},{"id":"ao-maya-persistence","from":["maya"],"to":["ao-maya-peoples"],"type":"contact","label":"Communities continue","dates":"After the Classic period–present","summary":"Maya communities continued long after the Classic-period transformation of their cities.","note":"A cultural continuation, not a new state founded in 900 AD.","sources":["americas_oceania_ao_mayaLiving"],"selectedBranch":false,"x":800.5,"y":687},{"id":"ao-tenochtitlan-conquest","from":["mexica"],"to":["poster-newspain"],"type":"conquest","label":"Conquest of Tenochtitlan","dates":"1521 · viceroyalty from 1535","summary":"Spanish forces and Indigenous allies conquered Tenochtitlan, followed by the development of New Spain.","note":"The colonial administration was established in stages; conquest did not end Nahua peoples or all Indigenous resistance.","sources":["americas_oceania_ao_mexicoConquest"],"selectedBranch":false,"x":524.5,"y":687},{"id":"ao-new-spain-independence","from":["poster-newspain"],"to":["mexicomodern"],"type":"independence","label":"Mexican independence","dates":"1821","summary":"Mexican independence ended Spanish rule in the core mainland territory represented by this New Spain entry.","note":"New Spain extended beyond modern Mexico; later empires, republics and territorial changes followed.","sources":["americas_oceania_ao_mexicoIndependence"],"selectedBranch":false,"x":524.5,"y":967},{"id":"ao-french-hispaniola","from":["francekingdom"],"to":["ao-saint-domingue"],"type":"colonial","label":"French colony","dates":"Late 17th century","summary":"French colonial rule developed in western Hispaniola as Saint-Domingue.","note":"This was not all of Hispaniola; the French monarchy later fell while colonial rule continued.","sources":["americas_oceania_ao_haitiColonial"],"selectedBranch":false,"x":1075.5,"y":407},{"id":"ao-haitian-revolution","from":["ao-saint-domingue"],"to":["haiti"],"type":"independence","label":"Revolution & independence","dates":"1791–1804","summary":"A revolution against enslavement and French colonial power culminated in Haitian independence in 1804.","note":"The conflict involved shifting alliances and foreign intervention; later occupations and political changes are not excluded.","sources":["americas_oceania_ao_haiti"],"selectedBranch":false,"x":1075.5,"y":687}],"description":"Artistic exchange, living Maya communities, conquest in central Mexico and Haiti’s anti-slavery revolution. Separate branches do not imply one regional empire.","autoLayout":true,"continuations":[{"map":"iberian-americas","history":"mexicomodern","label":"Iberian crowns & American successors"},{"map":"north-american-communities","history":"mexicomodern","label":"North American communities & changing borders"}],"width":1600,"height":1484},{"id":"andes-rio-plata","title":"Andes & Río de la Plata","region":"americas","nodes":[{"id":"caral","x":238.5,"y":220},{"id":"moche","x":513.5,"y":220},{"id":"nazca","x":788.5,"y":220},{"id":"wari","x":962.5,"y":500},{"id":"tiwanaku","x":1133.5,"y":220},{"id":"ao-chimor","x":576.5,"y":500},{"id":"inca","x":769.5,"y":780},{"id":"ao-colonial-peru","x":632.5,"y":1060},{"id":"ao-peru","x":495.5,"y":1340},{"id":"ao-quechua-communities","x":907.5,"y":1060},{"id":"poster-colonial-argentina","x":770.5,"y":1340},{"id":"argentinamodern","x":770.5,"y":1620}],"connections":[{"id":"ao-nazca-wari","from":["nazca"],"to":["wari"],"type":"contact","label":"Artistic interaction","dates":"c. 600–800 AD","summary":"Wari artists interacted with Nasca traditions and developed new artistic forms.","note":"Interaction and influence do not mean that every Nasca community was replaced by one Wari government.","sources":["americas_oceania_ao_wari"],"selectedBranch":false,"x":898.5,"y":407},{"id":"ao-tiwanaku-wari","from":["tiwanaku"],"to":["wari"],"type":"contact","label":"Shared visual traditions","dates":"c. 600–1000 AD","summary":"Wari art developed in dialogue with Tiwanaku religious imagery and visual traditions.","note":"These were distinct, contemporary powers; the arrow represents cultural interaction, not dynastic succession.","sources":["americas_oceania_ao_wari"],"selectedBranch":false,"x":1140.5,"y":407},{"id":"ao-moche-chimu","from":["moche"],"to":["ao-chimor"],"type":"contact","label":"North-coast artistic heritage","dates":"Later first–second millennium AD","summary":"Chimú artists inherited and reworked earlier Moche cultural and artistic traditions.","note":"This is a long artistic relationship across intervening regional developments, not an immediate political handover.","sources":["americas_oceania_ao_mocheChimu"],"selectedBranch":false,"x":634.5,"y":407},{"id":"ao-wari-tiwanaku-inka","from":["wari","tiwanaku"],"to":["inca"],"type":"contact","label":"Earlier roads & practices","dates":"Earlier traditions · adapted by the 15th century","summary":"Inca rulers adapted road-building and other practices developed by earlier Wari and Tiwanaku societies.","note":"Several centuries and many local histories separate these periods; this is inheritance of practices, not direct state succession.","sources":["americas_oceania_ao_inkaRoad"],"selectedBranch":false,"x":1076.5,"y":687},{"id":"ao-chimu-inka","from":["ao-chimor"],"to":["inca"],"type":"conquest","label":"Inca expansion","dates":"15th century","summary":"Inca expansion incorporated the Chimú kingdom into a much larger imperial system.","note":"Incorporation did not erase north-coast communities or their craft traditions.","sources":["americas_oceania_ao_chanChan"],"selectedBranch":false,"x":772.5,"y":687},{"id":"ao-inka-spanish","from":["inca"],"to":["ao-colonial-peru"],"type":"conquest","label":"Spanish invasion","dates":"From 1532","summary":"Spanish invaders exploited the Inca road system during conquest and imposed a new colonial order.","note":"The capture of Atahualpa did not instantly conquer the entire Andes; resistance and Indigenous communities continued.","sources":["americas_oceania_ao_inkaInvasion"],"selectedBranch":false,"x":770.5,"y":967},{"id":"ao-inka-living","from":["inca"],"to":["ao-quechua-communities"],"type":"contact","label":"Living Andean traditions","dates":"Colonial era–present","summary":"Quechua-speaking communities have maintained and transformed traditions associated with the Inca world.","note":"Cultural continuation is not continuous imperial sovereignty or a claim that all Quechua speakers share one identity.","sources":["americas_oceania_ao_inkaRoad"],"selectedBranch":false,"x":1009.5,"y":967},{"id":"ao-peru-independent","from":["ao-colonial-peru"],"to":["ao-peru"],"type":"independence","label":"Peruvian independence","dates":"1821 declaration · war continued","summary":"San Martín proclaimed Peruvian independence in Lima in July 1821.","note":"A declaration did not end the war immediately or settle every territory.","sources":["americas_oceania_ao_peruIndependence"],"selectedBranch":false,"x":640.5,"y":1247},{"id":"ao-rio-plata-division","from":["ao-colonial-peru"],"to":["poster-colonial-argentina"],"type":"division","label":"New viceroyalty","dates":"1776","summary":"The Río de la Plata viceroyalty was created from territories previously administered within the Viceroyalty of Peru.","note":"The plotted colonial Argentina frame begins earlier; this arrow specifically concerns the 1776 administrative reorganisation.","sources":["americas_oceania_ao_rioPlata"],"selectedBranch":true,"x":868.5,"y":1247},{"id":"ao-argentina-independent","from":["poster-colonial-argentina"],"to":["argentinamodern"],"type":"independence","label":"United Provinces declare independence","dates":"1816","summary":"The Congress of Tucumán declared the independence of the United Provinces in South America on 9 July 1816.","note":"Argentina later developed through conflicts and constitutional changes; the whole former viceroyalty did not become Argentina.","sources":["americas_oceania_ao_argentinaIndependence"],"selectedBranch":false,"x":884.5,"y":1527}],"description":"Andean cultural interactions, Spanish conquest, colonial reorganisation and selected independence histories. Caral is shown without an unsupported succession arrow.","autoLayout":true,"continuations":[],"width":1600,"height":1904},{"id":"north-american-communities","title":"North American communities & changing borders","region":"americas","nodes":[{"id":"cahokia","x":550.875,"y":780},{"id":"ao-caddo","x":550.875,"y":1060},{"id":"chaco","x":830.875,"y":220},{"id":"ao-puebloans","x":830.875,"y":500},{"id":"ao-colonial-new-mexico","x":830.875,"y":780},{"id":"mexicomodern","x":830.875,"y":1060},{"id":"unitedstates","x":690.875,"y":1340}],"connections":[{"id":"ao-cahokia-caddo","from":["cahokia"],"to":["ao-caddo"],"type":"contact","label":"Long-distance exchange","dates":"Mississippian-era networks","summary":"Caddo exchange routes linked their communities with distant centres including Cahokia.","note":"Trade connections do not imply shared political government or direct descent from Cahokia.","sources":["americas_oceania_ao_caddoTrade"],"selectedBranch":false,"x":664.875,"y":967},{"id":"ao-chaco-pueblo","from":["chaco"],"to":["ao-puebloans"],"type":"contact","label":"Migration & descendants","dates":"After c. 1200 · continuing","summary":"People leaving the Chaco region joined communities in several directions, contributing to multiple present-day Pueblo populations.","note":"Exact migration routes vary; this does not identify one exclusive heir to Chaco.","sources":["americas_oceania_ao_chacoDescendants"],"selectedBranch":false,"x":944.875,"y":407},{"id":"ao-pueblo-spanish","from":["ao-puebloans"],"to":["ao-colonial-new-mexico"],"type":"colonial","label":"Colonisation & resistance","dates":"From 1598 · revolt in 1680","summary":"Spanish colonisation imposed demands on Pueblo communities, which organised a major revolt in 1680.","note":"Pueblo peoples persisted; Spanish control was interrupted and reconquest was gradual and contested.","sources":["americas_oceania_ao_newMexico","americas_oceania_ao_puebloColonial"],"selectedBranch":false,"x":944.875,"y":687},{"id":"ao-new-mexico-mexico","from":["ao-colonial-new-mexico"],"to":["mexicomodern"],"type":"independence","label":"Mexico gains independence","dates":"1821","summary":"New Mexico became part of independent Mexico after Spanish colonial rule ended.","note":"A change in state jurisdiction did not end Pueblo communities or their own institutions.","sources":["americas_oceania_ao_puebloColonial"],"selectedBranch":false,"x":944.875,"y":967},{"id":"ao-mexican-cession","from":["mexicomodern"],"to":["unitedstates"],"type":"conquest","label":"War & territorial cession","dates":"1846–1848","summary":"The Treaty of Guadalupe Hidalgo ended the U.S.–Mexican War and transferred extensive northern territory to the United States.","note":"Mexico continued as an independent state; Indigenous nations were not extinguished by this interstate boundary change.","sources":["americas_oceania_ao_guadalupe"],"selectedBranch":false,"x":944.875,"y":1247},{"id":"ao-caddo-removal","from":["ao-caddo"],"to":["unitedstates"],"type":"colonial","label":"Land cession & forced removal","dates":"1835 and later removals","summary":"A Caddo removal treaty with the United States was followed by dispersal and repeated forced removals.","note":"This links communities to the state that dispossessed them, not a claim that they ceased to exist or became its predecessor.","sources":["americas_oceania_ao_caddoNation"],"selectedBranch":false,"x":664.875,"y":1247}],"description":"Caddo exchange networks, Chaco’s descendant communities and later colonial and interstate boundary changes. Indigenous histories continue.","autoLayout":true,"continuations":[{"map":"iberian-americas","history":"mexicomodern","label":"Iberian crowns & American successors"},{"map":"mesoamerica-caribbean","history":"mexicomodern","label":"Mesoamerica & the Caribbean"}],"width":1600,"height":1764},{"id":"pacific-networks","title":"Pacific voyaging, communities & modern states","region":"oceania","nodes":[{"id":"lapita","x":409.9,"y":220},{"id":"ao-east-polynesia","x":684.9,"y":500},{"id":"tonga","x":134.89999999999998,"y":500},{"id":"ao-tonga-modern","x":134.89999999999998,"y":780},{"id":"ao-fiji-societies","x":409.9,"y":500},{"id":"ao-colonial-fiji","x":409.9,"y":780},{"id":"fiji","x":409.9,"y":1060},{"id":"rapanui","x":684.9,"y":780},{"id":"ao-rapa-nui-people","x":684.9,"y":1060},{"id":"ao-chile","x":684.9,"y":1340},{"id":"maori","x":959.9000000000001,"y":780},{"id":"nanmadol","x":1234.9,"y":220},{"id":"ao-pohnpei","x":1234.9,"y":500},{"id":"ao-fsm","x":1234.9,"y":780}],"connections":[{"id":"ao-lapita-tonga","from":["lapita"],"to":["tonga"],"type":"contact","label":"Settlement before Tuʻi Tonga","dates":"Settlement c. 1100–800 BC · later chiefly societies","summary":"Lapita-associated voyagers settled Tonga long before the Tuʻi Tonga chiefly line developed.","note":"A settlement and cultural background link, not a claim that the Tuʻi Tonga polity existed in the Bronze Age.","sources":["americas_oceania_ao_pacificVoyaging"],"selectedBranch":false,"x":263.9,"y":407},{"id":"ao-lapita-fiji","from":["lapita"],"to":["ao-fiji-societies"],"type":"contact","label":"Lapita settlement","dates":"c. 1100–800 BC","summary":"Lapita-associated voyagers settled Fiji, forming part of its long and changing island histories.","note":"Material-culture associations do not make all Pacific peoples one ethnicity or state.","sources":["americas_oceania_ao_pacificVoyaging"],"selectedBranch":false,"x":523.9,"y":407},{"id":"ao-west-east-polynesia","from":["lapita"],"to":["ao-east-polynesia"],"type":"contact","label":"Polynesian cultural development","dates":"Over many centuries · eastward voyages c. 1000 AD","summary":"Polynesian cultures emerged among western island communities before voyages expanded into East Polynesia.","note":"This compresses multiple stages through Fiji, Tonga and Samoa; it does not draw a direct Lapita-era voyage to every eastern island.","sources":["americas_oceania_ao_lapitaPolynesia"],"selectedBranch":false,"x":789.9,"y":407},{"id":"ao-east-rapanui","from":["ao-east-polynesia"],"to":["rapanui"],"type":"contact","label":"Polynesian settlement","dates":"c. 1200–1300 AD · approximate","summary":"East Polynesian voyagers settled Rapa Nui, where distinctive monumental traditions developed.","note":"Dates remain approximate; this does not imply political rule from Tonga.","sources":["americas_oceania_ao_lapitaPolynesia","americas_oceania_ao_rapaNuiHeritage"],"selectedBranch":false,"x":798.9,"y":687},{"id":"ao-east-maori","from":["ao-east-polynesia"],"to":["maori"],"type":"contact","label":"Voyages to Aotearoa","dates":"c. 1250–1300 AD","summary":"Migrants from East Polynesian islands became the ancestors of Māori communities in Aotearoa.","note":"Many voyages and traditions are involved, rather than a single great fleet or an overseas empire.","sources":["americas_oceania_ao_pacificVoyaging"],"selectedBranch":false,"x":1049.9,"y":687},{"id":"ao-tonga-modernisation","from":["tonga"],"to":["ao-tonga-modern"],"type":"continuation","label":"Kingdom consolidation","dates":"1845 · constitution 1875","summary":"George Tupou I united the Tongan islands before the 1875 constitution established modern constitutional institutions.","note":"A transformation of chiefly and state authority, not an unchanged Tuʻi Tonga empire persisting to the present.","sources":["americas_oceania_ao_tongaModern"],"selectedBranch":false,"x":248.89999999999998,"y":687},{"id":"ao-fiji-cession","from":["ao-fiji-societies"],"to":["ao-colonial-fiji"],"type":"colonial","label":"Cession & British rule","dates":"1874","summary":"The 1874 cession established British colonial rule in Fiji.","note":"The islands already contained Indigenous societies; colonial administration did not originate or replace their culture.","sources":["americas_oceania_ao_fijiParliament"],"selectedBranch":false,"x":523.9,"y":687},{"id":"ao-fiji-independence","from":["ao-colonial-fiji"],"to":["fiji"],"type":"independence","label":"Fijian independence","dates":"10 October 1970","summary":"Fiji became independent from Britain in 1970.","note":"Later constitutional changes and coups are included in the broad modern-state entry.","sources":["americas_oceania_ao_fijiParliament"],"selectedBranch":false,"x":523.9,"y":967},{"id":"ao-nanmadol-living","from":["nanmadol"],"to":["ao-pohnpei"],"type":"contact","label":"Chiefly traditions continue","dates":"To the present","summary":"Nan Madol remains connected to Pohnpei ceremonial traditions and the authority of the Nahnmwarki.","note":"Continuing institutions and heritage are distinct from an uninterrupted Saudeleur state.","sources":["americas_oceania_ao_nanMadol"],"selectedBranch":false,"x":1348.9,"y":407},{"id":"ao-pohnpei-federation","from":["ao-pohnpei"],"to":["ao-fsm"],"type":"union","label":"State in a federation","dates":"1978–1979 · Compact 1986","summary":"Pohnpei joined the constitutional federation that became the Federated States of Micronesia.","note":"The modern federation also includes Chuuk, Kosrae and Yap; centuries of changing colonial administrations lie between Nan Madol and this constitutional transition.","sources":["americas_oceania_ao_fsm"],"selectedBranch":false,"x":1348.9,"y":687},{"id":"ao-rapanui-living","from":["rapanui"],"to":["ao-rapa-nui-people"],"type":"contact","label":"A living culture","dates":"Beyond the monumental phase–present","summary":"Rapa Nui people maintain a living relationship with their island and cultural heritage.","note":"The end of the selected monumental-phase bar is not the end of Rapa Nui society.","sources":["americas_oceania_ao_rapaNuiHeritage","americas_oceania_ao_rapaNuiChile"],"selectedBranch":false,"x":798.9,"y":967},{"id":"ao-rapanui-chile","from":["ao-rapa-nui-people"],"to":["ao-chile"],"type":"colonial","label":"1888 agreement with Chile","dates":"1888","summary":"The Agreement of Wills formalised Rapa Nui’s incorporation into the Republic of Chile.","note":"This state relationship did not end Rapa Nui identity or local titles and authority; its meanings and consequences remain contested.","sources":["americas_oceania_ao_rapaNuiChile"],"selectedBranch":false,"x":798.9,"y":1247}],"description":"Voyaging and cultural connections alongside selected modern constitutional transitions. These are not branches of a single Pacific empire.","autoLayout":true,"continuations":[{"map":"australia-aotearoa","history":"maori","label":"Australia & Aotearoa New Zealand"}],"width":1600,"height":1764},{"id":"australia-aotearoa","title":"Australia & Aotearoa New Zealand","region":"oceania","nodes":[{"id":"australia","x":258.75,"y":220},{"id":"britishempire","x":666.75,"y":220},{"id":"poster-colonial-australia","x":391.75,"y":500},{"id":"australiamodern","x":391.75,"y":780},{"id":"maori","x":1105.75,"y":220},{"id":"ao-colonial-nz","x":952.75,"y":500},{"id":"newzealand","x":952.75,"y":780}],"connections":[{"id":"ao-first-fleet","from":["britishempire"],"to":["poster-colonial-australia"],"type":"colonial","label":"First Fleet & colonies","dates":"From 1788","summary":"Britain established a convict settlement at Sydney Cove in 1788, followed by expanding and separate colonies.","note":"The continent already belonged to many Indigenous nations; British control developed unevenly.","sources":["americas_oceania_ao_australiaColonial"],"selectedBranch":false,"x":637.75,"y":407},{"id":"ao-aboriginal-colonisation","from":["australia"],"to":["poster-colonial-australia"],"type":"colonial","label":"Colonisation & dispossession","dates":"From 1788","summary":"British settlement disrupted and dispossessed Aboriginal communities while their cultures and resistance continued.","note":"The direction marks an encounter with an imposed colonial order, not cultural replacement or extinction.","sources":["americas_oceania_ao_australiaColonial"],"selectedBranch":false,"x":372.75,"y":407},{"id":"ao-federation-australia","from":["poster-colonial-australia"],"to":["australiamodern"],"type":"union","label":"Six colonies federate","dates":"1 January 1901","summary":"Six British colonies united in the Commonwealth of Australia in 1901.","note":"Federation did not itself complete constitutional independence or end Indigenous histories.","sources":["americas_oceania_ao_australiaFederation"],"selectedBranch":false,"x":505.75,"y":687},{"id":"ao-british-newzealand","from":["britishempire"],"to":["ao-colonial-nz"],"type":"colonial","label":"British colonial administration","dates":"1840–1841","summary":"The British Crown proclaimed sovereignty in 1840 and established New Zealand as a separate colony in 1841.","note":"A proclamation of sovereignty is not equivalent to universal Māori consent or immediate control of all territory.","sources":["americas_oceania_ao_nzColony"],"selectedBranch":false,"x":913.75,"y":407},{"id":"ao-treaty-maori","from":["maori"],"to":["ao-colonial-nz"],"type":"contact","label":"Te Tiriti / Treaty of Waitangi","dates":"1840","summary":"Māori rangatira and the Crown signed a treaty whose Māori and English texts differ in meaning.","note":"This is a treaty relationship with disputed sovereignty and obligations, not a merger that ended Māori peoples or authority.","sources":["americas_oceania_ao_nzTreaty"],"selectedBranch":false,"x":1219.75,"y":407},{"id":"ao-dominion-newzealand","from":["ao-colonial-nz"],"to":["newzealand"],"type":"continuation","label":"Dominion & later autonomy","dates":"1907 · 1947 · 1986","summary":"New Zealand gained Dominion status in 1907, adopted the Statute of Westminster in 1947 and removed remaining British legislative authority in 1986.","note":"These were different stages, not one complete independence event in 1907.","sources":["americas_oceania_ao_nzConstitution"],"selectedBranch":false,"x":1066.75,"y":687}],"description":"Continuing Indigenous histories, British colonisation, Australian federation and New Zealand’s treaty and constitutional transitions.","autoLayout":true,"continuations":[{"map":"pacific-networks","history":"maori","label":"Pacific voyaging, communities & modern states"}],"width":1600,"height":1204},{"id":"china-early","title":"China · early cultures and dynasties","region":"eastasia","nodes":[{"id":"liangzhu","x":548.5,"y":220},{"id":"xia","label":"Xia · unconfirmed","x":823.5,"y":220},{"id":"shang","x":685.5,"y":500},{"id":"zhou","x":685.5,"y":780},{"id":"qin","x":685.5,"y":1060},{"id":"han","x":685.5,"y":1340},{"id":"china-division","x":685.5,"y":1620},{"id":"sui","x":685.5,"y":1900},{"id":"tang","x":685.5,"y":2180},{"id":"five-dynasties","x":685.5,"y":2460},{"id":"song","x":685.5,"y":2740}],"connections":[{"id":"ea-liangzhu-shang","from":["liangzhu"],"to":["shang"],"type":"contact","label":"Jade traditions endure","dates":"Later 2nd millennium BC","summary":"Liangzhu jade traditions influenced later Bronze Age centres, including late Shang Anyang.","note":"This cultural legacy crosses a substantial chronological gap; it is not a claim of direct dynastic succession or a Liangzhu–Xia state lineage.","sources":["eastasia_ea_liangzhu"],"selectedBranch":false,"x":682.5,"y":407},{"id":"ea-xia-shang","from":["xia"],"to":["shang"],"type":"contact","label":"Traditional sequence","dates":"Later historical tradition","summary":"Later histories place Xia before Shang in a dynastic sequence.","note":"Xia remains unconfirmed in contemporary inscriptions; this dashed link records historiography, not a securely attested conquest or identification of Erlitou.","sources":["eastasia_ea_china_bronze"],"certainty":"Tradition","selectedBranch":false,"x":927.5,"y":407},{"id":"ea-shang-zhou","from":["shang"],"to":["zhou"],"type":"conquest","label":"Zhou conquest","dates":"c. 1046 BC","summary":"Zhou forces overthrew the Shang ruling house.","note":"The conventional date does not imply that Shang populations and cultural practices disappeared.","sources":["eastasia_ea_china_bronze"],"selectedBranch":false,"x":799.5,"y":687},{"id":"ea-zhou-qin","from":["zhou"],"to":["qin"],"type":"conquest","label":"Qin consolidation","dates":"256–221 BC","summary":"Qin ended the Zhou royal house and later conquered the other Warring States before proclaiming an empire.","note":"Zhou kingship ended in 256 BC; imperial unification followed in 221 BC, so the two plotted period boundaries do not mark a single instantaneous transfer.","sources":["eastasia_ea_qin_han"],"selectedBranch":false,"x":799.5,"y":967},{"id":"ea-qin-han","from":["qin"],"to":["han"],"type":"continuation","label":"Rebellion and Han rule","dates":"206–202 BC","summary":"After Qin collapse and civil war, Liu Bang established Han rule and took the imperial title in 202 BC.","note":"Han dates conventionally begin with Liu Bang’s kingdom in 206 BC; this is a change of regime, not uninterrupted Qin government.","sources":["eastasia_ea_han"],"selectedBranch":false,"x":799.5,"y":1247},{"id":"ea-han-division","from":["han"],"to":["china-division"],"type":"division","label":"Han breaks apart","dates":"220 AD onward","summary":"The end of Han rule gave way to competing kingdoms and subsequent northern and southern dynasties.","note":"The Age of Division is a period containing many governments, including a brief Western Jin reunification, rather than a successor state.","sources":["eastasia_ea_division"],"selectedBranch":true,"x":799.5,"y":1527},{"id":"ea-division-sui","from":["china-division"],"to":["sui"],"type":"union","label":"Sui reunification","dates":"581–589 AD","summary":"Sui replaced Northern Zhou in 581 and conquered the southern Chen in 589.","note":"Northern and southern political consolidation occurred in stages; the period and dynasty intentionally overlap.","sources":["eastasia_ea_sui_tang"],"selectedBranch":false,"x":799.5,"y":1807},{"id":"ea-sui-tang","from":["sui"],"to":["tang"],"type":"continuation","label":"Tang takes power","dates":"618 AD","summary":"Li Yuan established the Tang dynasty amid the collapse of Sui authority.","note":"Early Tang consolidation continued after the dynastic proclamation.","sources":["eastasia_ea_sui_tang"],"selectedBranch":false,"x":799.5,"y":2087},{"id":"ea-tang-five","from":["tang"],"to":["five-dynasties"],"type":"division","label":"Competing realms","dates":"907 AD onward","summary":"Tang collapse left successive northern dynasties and concurrent southern kingdoms.","note":"This umbrella period does not represent one united government or just five rulers of all China.","sources":["eastasia_ea_sui_tang"],"selectedBranch":true,"x":799.5,"y":2367},{"id":"ea-five-song","from":["five-dynasties"],"to":["song"],"type":"union","label":"Song consolidation","dates":"960–979 AD","summary":"The Song foundation in 960 was followed by campaigns against several remaining independent kingdoms.","note":"Other states including Liao continued outside Song rule; 960 did not reunify all territory in modern China.","sources":["eastasia_ea_sui_tang"],"selectedBranch":false,"x":799.5,"y":2647}],"note":"Archaeological influence, later tradition and political change are distinct links. Continue from Song in the existing Mongols and China map for Yuan, Ming, Qing, ROC, PRC and Taiwan-era histories.","autoLayout":true,"continuations":[{"map":"mongols-china","history":"song","label":"Later China: Mongol conquest and modern states"},{"map":"japan-transformations","history":"tang","label":"Japan · cultures, courts and shogunates"},{"map":"southeast-maritime","history":"tang","label":"Maritime Southeast Asia · encounters and independence"}],"width":1600,"height":3164},{"id":"japan-transformations","title":"Japan · cultures, courts and shogunates","region":"eastasia","nodes":[{"id":"jomon","x":475.75,"y":220},{"id":"yayoi","x":475.75,"y":500},{"id":"yamato","x":475.75,"y":780},{"id":"nara","x":612.75,"y":1060},{"id":"heian","x":612.75,"y":1340},{"id":"kamakura","x":749.75,"y":1620},{"id":"ea-kenmu","x":749.75,"y":1900},{"id":"muromachi","x":749.75,"y":2180},{"id":"ea-momoyama","x":749.75,"y":2460},{"id":"edo","x":749.75,"y":2740},{"id":"japanmodern","x":749.75,"y":3020},{"id":"tang","x":750.75,"y":780},{"id":"yuan","x":887.75,"y":1340}],"connections":[{"id":"ea-jomon-yayoi","from":["jomon"],"to":["yayoi"],"type":"contact","label":"Agriculture and migration","dates":"1st millennium BC–early AD","summary":"Wet-rice farming and continental exchanges transformed communities while some Jōmon practices continued.","note":"These are overlapping regional archaeological classifications, not two empires or the replacement of an entire people; the transition has no single nationwide date.","sources":["eastasia_ea_yayoi"],"selectedBranch":false,"x":589.75,"y":407},{"id":"ea-yayoi-yamato","from":["yayoi"],"to":["yamato"],"type":"continuation","label":"Regional state formation","dates":"c. 3rd–5th centuries AD","summary":"Growing regional powers and monumental tomb building accompanied the emergence of Yamato political dominance.","note":"This is a long social and political process; the Kofun-period boundary is not an exact founding date for Japan or one securely identified conquest.","sources":["eastasia_ea_yamato"],"selectedBranch":false,"x":589.75,"y":687},{"id":"ea-yamato-nara","from":["yamato"],"to":["nara"],"type":"continuation","label":"Court moves to Nara","dates":"710 AD","summary":"The court moved its capital from the Asuka region to Nara.","note":"A change of capital and historical period within developing court institutions, not a new people replacing the Yamato population.","sources":["eastasia_ea_nara"],"selectedBranch":false,"x":598.75,"y":967},{"id":"ea-nara-heian","from":["nara"],"to":["heian"],"type":"continuation","label":"Capital at Heian","dates":"794 AD","summary":"The imperial capital moved to Heian-kyō, present-day Kyoto.","note":"The court first moved through the Nagaoka capital, 784–794; the label condenses that transition.","sources":["eastasia_ea_nara"],"selectedBranch":false,"x":726.75,"y":1247},{"id":"ea-tang-nara","from":["tang"],"to":["nara"],"type":"contact","label":"Embassies and statecraft","dates":"8th century AD","summary":"Court missions and imported models connected Tang China with Japan’s Nara court.","note":"Japanese missions to Tang China began earlier, in 630; this edge selects exchanges during the Nara period (710–794). Diplomatic and cultural exchange did not make Japan a province of Tang China.","sources":["eastasia_ea_nara","eastasia_ea_nara_chronology"],"selectedBranch":false,"x":854.75,"y":967},{"id":"ea-heian-kamakura","from":["heian"],"to":["kamakura"],"type":"continuation","label":"Warrior government","dates":"1185–1192 AD","summary":"Minamoto victory in 1185 established a military regime at Kamakura, with Yoritomo named shogun in 1192.","note":"The imperial court continued; this marks a shift in political power rather than the end of the imperial institution.","sources":["eastasia_ea_kamakura"],"selectedBranch":false,"x":735.75,"y":1527},{"id":"ea-yuan-kamakura","from":["yuan"],"to":["kamakura"],"type":"contact","label":"Failed invasions · 1274 & 1281","dates":"1274 and 1281 AD","summary":"Mongol-led Yuan expeditions attacked Japan but failed to establish control.","note":"This is a conflict link, not successful conquest. Goryeo and other forces participated; Japan was not incorporated into Yuan rule.","sources":["eastasia_ea_kamakura","eastasia_ea_failed_invasions"],"selectedBranch":false,"x":996.75,"y":1527},{"id":"ea-kamakura-kenmu","from":["kamakura"],"to":["ea-kenmu"],"type":"continuation","label":"Shogunate overthrown","dates":"1333 AD","summary":"Go-Daigo and his supporters overthrew the Kamakura shogunate.","note":"The imperial revival was brief, while conflict over rival courts continued after it ended.","sources":["eastasia_ea_kamakura"],"selectedBranch":false,"x":863.75,"y":1807},{"id":"ea-kenmu-muromachi","from":["ea-kenmu"],"to":["muromachi"],"type":"continuation","label":"Ashikaga ascendancy","dates":"1336–1338 AD","summary":"Ashikaga Takauji displaced Go-Daigo in Kyoto and subsequently became shogun.","note":"Northern and Southern courts competed until 1392; this is not a peaceful complete transfer of national control.","sources":["eastasia_ea_kamakura"],"selectedBranch":false,"x":863.75,"y":2087},{"id":"ea-muromachi-unification","from":["muromachi"],"to":["ea-momoyama"],"type":"conquest","label":"Nobunaga takes Kyoto","dates":"1568–1573 AD","summary":"Nobunaga entered Kyoto and later removed the last Ashikaga shogun.","note":"Regional wars and Toyotomi consolidation followed; the Sengoku conflicts overlap these named periods.","sources":["eastasia_ea_muromachi"],"selectedBranch":false,"x":863.75,"y":2367},{"id":"ea-unification-edo","from":["ea-momoyama"],"to":["edo"],"type":"continuation","label":"Tokugawa government","dates":"1600–1603 AD","summary":"Tokugawa Ieyasu’s ascendancy led to a shogunate based in Edo.","note":"The imperial court and regional domains continued, and Toyotomi resistance was not eliminated until 1615.","sources":["eastasia_ea_edo"],"selectedBranch":false,"x":863.75,"y":2647},{"id":"ea-edo-meiji","from":["edo"],"to":["japanmodern"],"type":"continuation","label":"Meiji Restoration","dates":"1867–1868 AD","summary":"The Tokugawa shogunate fell and a new government claimed to restore imperial authority.","note":"Modern Japan includes later imperial, wartime, occupation and constitutional phases; 1868 is not Japan’s founding.","sources":["eastasia_ea_meiji"],"selectedBranch":false,"x":863.75,"y":2927}],"note":"Archaeological periods are not states, and courts and shogunates could coexist. Cross-map Japanese expansion and Korea appear in Korea’s map.","autoLayout":true,"continuations":[{"map":"korea-histories","history":"japanmodern","label":"Korea · dynasties, colonisation and division"},{"map":"southeast-maritime","history":"tang","label":"Maritime Southeast Asia · encounters and independence"},{"map":"china-early","history":"tang","label":"China · early cultures and dynasties"}],"width":1600,"height":3444},{"id":"korea-histories","title":"Korea · dynasties, colonisation and division","region":"eastasia","nodes":[{"id":"goryeo","x":685.5,"y":500},{"id":"joseon","x":823.5,"y":780},{"id":"ea-korean-empire","x":823.5,"y":1060},{"id":"ea-korea-colonial","x":685.5,"y":1340},{"id":"ea-korea-soviet","x":548.5,"y":1620},{"id":"ea-korea-us","x":823.5,"y":1620},{"id":"northkorea","x":566.5,"y":1900},{"id":"southkorea","x":691.5,"y":2180},{"id":"mongol","x":685.5,"y":220},{"id":"yuan","x":548.5,"y":780},{"id":"japanmodern","x":548.5,"y":1060}],"connections":[{"id":"ea-mongol-goryeo","from":["mongol"],"to":["goryeo"],"type":"conquest","label":"Mongol invasions","dates":"1231–1259 AD","summary":"Mongol invasions devastated Goryeo before negotiated submission and later close dynastic ties.","note":"Goryeo retained its royal house; invasion and subordinate relations did not simply turn it into a replacement Chinese dynasty.","sources":["eastasia_ea_goryeo"],"selectedBranch":false,"x":799.5,"y":407},{"id":"ea-goryeo-yuan","from":["goryeo"],"to":["yuan"],"type":"contact","label":"Court and marriage ties","dates":"1270s–mid-14th century","summary":"Goryeo and Yuan courts developed close political relations, including royal intermarriage.","note":"These unequal ties coexisted with Goryeo institutions; later Goryeo rulers contested Yuan influence.","sources":["eastasia_ea_goryeo"],"selectedBranch":false,"x":686.5,"y":687},{"id":"ea-goryeo-joseon","from":["goryeo"],"to":["joseon"],"type":"continuation","label":"New royal dynasty","dates":"1392 AD","summary":"Yi Seonggye deposed the last Goryeo ruler and founded Joseon.","note":"A change of ruling house and political institutions within Korean history, not the origin of Korean people.","sources":["eastasia_ea_goryeo"],"selectedBranch":false,"x":925.5,"y":687},{"id":"ea-joseon-empire","from":["joseon"],"to":["ea-korean-empire"],"type":"continuation","label":"Empire proclaimed","dates":"1897 AD","summary":"Gojong adopted the imperial title and renamed the state the Korean Empire.","note":"The timeline’s broad Joseon block extends to 1910 by dynastic convention; this node distinguishes the state-name change within that royal house.","sources":["eastasia_ea_korean_empire"],"selectedBranch":false,"x":937.5,"y":967},{"id":"ea-korean-annexation","from":["ea-korean-empire","japanmodern"],"to":["ea-korea-colonial"],"type":"colonial","label":"Japanese annexation","dates":"1910 AD","summary":"Japan annexed Korea after extending control through an imposed protectorate.","note":"Japan’s own government continued; the two source nodes identify the colonising state and the annexed Korean monarchy, not two equal partners in a union.","sources":["eastasia_ea_korean_empire","eastasia_ea_korea_modern"],"selectedBranch":false,"x":799.5,"y":1247},{"id":"ea-korea-liberation","from":["ea-korea-colonial"],"to":["ea-korea-soviet","ea-korea-us"],"type":"division","label":"Liberation and occupations","dates":"1945 AD","summary":"Japanese surrender ended colonial rule and Soviet and U.S. forces occupied zones divided at the 38th parallel.","note":"The military division was imposed amid liberation and did not immediately create the two states established in 1948.","sources":["eastasia_ea_korea_occupation"],"selectedBranch":false,"x":799.5,"y":1527},{"id":"ea-korea-south-state","from":["ea-korea-us"],"to":["southkorea"],"type":"continuation","label":"Republic established","dates":"August 1948 AD","summary":"The Republic of Korea was established in the southern zone.","note":"This followed a contested state-building process; the zone-to-state link does not imply unanimous consent or settled all-Korea sovereignty.","sources":["eastasia_ea_korea_occupation","eastasia_ea_korean_war"],"selectedBranch":false,"x":934.5,"y":1947},{"id":"ea-korea-north-state","from":["ea-korea-soviet"],"to":["northkorea"],"type":"continuation","label":"DPRK established","dates":"September 1948 AD","summary":"The Democratic People’s Republic of Korea was established in the northern zone.","note":"Both new governments claimed to represent Korea; this map describes administration without adjudicating those competing claims.","sources":["eastasia_ea_korea_occupation","eastasia_ea_korean_war"],"selectedBranch":false,"x":674.5,"y":1807},{"id":"ea-korean-war","from":["northkorea"],"to":["southkorea"],"type":"contact","label":"War and armistice","dates":"1950–1953 AD","summary":"North Korean invasion opened a war involving both Korean states and international forces, ending in an armistice.","note":"A conflict link, not state succession; the armistice suspended fighting and did not itself provide a final peace settlement.","sources":["eastasia_ea_korean_war"],"selectedBranch":false,"x":730.5,"y":2087}],"note":"This map follows the histories already in the atlas and does not claim to start Korean history with Goryeo. Division in 1945 and state establishment in 1948 are separate events.","autoLayout":true,"continuations":[{"map":"japan-transformations","history":"yuan","label":"Japan · cultures, courts and shogunates"},{"map":"mongols-china","history":"mongol","label":"Mongol khanates & China"},{"map":"southeast-maritime","history":"yuan","label":"Maritime Southeast Asia · encounters and independence"}],"width":1600,"height":2604},{"id":"southeast-maritime","title":"Maritime Southeast Asia · encounters and independence","region":"eastasia","nodes":[{"id":"srivijaya","x":373.4,"y":500},{"id":"tang","x":199.39999999999998,"y":220},{"id":"chola","x":474.4,"y":220},{"id":"yuan","x":648.4,"y":500},{"id":"majapahit","x":648.4,"y":780},{"id":"ea-voc","x":1054.4,"y":220},{"id":"ea-dutch-indies","x":1054.4,"y":500},{"id":"ea-japan-indies","x":923.4000000000001,"y":780},{"id":"indonesia","x":923.4000000000001,"y":1060}],"connections":[{"id":"ea-srivijaya-yijing","from":["tang"],"to":["srivijaya"],"type":"contact","label":"Buddhist journeys","dates":"671–695 AD","summary":"The Tang-era monk Yijing studied and translated Buddhist texts at Srivijaya while travelling between China and India.","note":"A scholarly and maritime connection, not Chinese annexation or a single route followed by every traveller.","sources":["eastasia_ea_yijing"],"selectedBranch":false,"x":350.4,"y":407},{"id":"ea-chola-srivijaya","from":["chola"],"to":["srivijaya"],"type":"conquest","label":"Chola naval raid","dates":"1025 AD","summary":"Chola forces raided Srivijaya’s maritime realm.","note":"A raid and episode of warfare, not proof that Chola permanently replaced Srivijaya across its trading network.","sources":["eastasia_ea_sea_medieval"],"selectedBranch":false,"x":570.4,"y":407},{"id":"ea-yuan-java","from":["yuan"],"to":["majapahit"],"type":"contact","label":"Mongol expedition repelled","dates":"1293 AD","summary":"A Yuan expedition into Java was defeated during the conflicts surrounding Majapahit’s foundation.","note":"The invaders did not establish lasting Yuan rule; the state’s foundation involved local struggles beyond this selected encounter.","sources":["eastasia_ea_sea_medieval","eastasia_ea_java_1293"],"selectedBranch":false,"x":762.4,"y":687},{"id":"ea-majapahit-motto","from":["majapahit"],"to":["indonesia"],"type":"contact","label":"Literary legacy","dates":"14th-century text · modern adoption","summary":"Modern Indonesia adopted its national motto from the Majapahit-era poem Kakawin Sutasoma.","note":"A documented modern reception of a literary phrase, not direct political succession, unchanged borders or descent of all Indonesians from one empire.","sources":["eastasia_ea_sutasoma"],"selectedBranch":false,"x":790.4,"y":967},{"id":"ea-voc-colony","from":["ea-voc"],"to":["ea-dutch-indies"],"type":"colonial","label":"Company to colonial state","dates":"1799–1800 AD","summary":"The Dutch government took over VOC possessions after the company’s dissolution.","note":"Expansion of colonial control continued over the nineteenth and early twentieth centuries; many local states had independent histories beyond the VOC’s reach.","sources":["eastasia_ea_voc","eastasia_ea_sea_colonial"],"selectedBranch":false,"x":1168.4,"y":407},{"id":"ea-indies-occupation","from":["ea-dutch-indies"],"to":["ea-japan-indies"],"type":"conquest","label":"Japanese occupation","dates":"1942 AD","summary":"Japanese conquest displaced Dutch colonial administration in the East Indies.","note":"This represents wartime military rule rather than a voluntary transfer or liberation into an independent state.","sources":["eastasia_ea_sukarno"],"selectedBranch":false,"x":1063.4,"y":687},{"id":"ea-indonesia-proclamation","from":["ea-japan-indies"],"to":["indonesia"],"type":"independence","label":"Independence proclaimed","dates":"17 August 1945 AD","summary":"Sukarno and Mohammad Hatta proclaimed Indonesian independence after Japan’s surrender.","note":"Dutch attempts to restore colonial control led to a further revolution and war; independence was not uncontested or fully recognised on proclamation day.","sources":["eastasia_ea_sukarno","eastasia_ea_independence"],"selectedBranch":false,"x":1037.4,"y":967},{"id":"ea-indonesia-transfer","from":["ea-dutch-indies"],"to":["indonesia"],"type":"independence","label":"Sovereignty transferred","dates":"1949–1950 AD","summary":"Dutch recognition and transfer of sovereignty in 1949 were followed by a unitary Indonesian republic in 1950.","note":"Territorial integration remained incomplete, notably in western New Guinea; this is not a claim that all present borders were settled in 1949.","sources":["eastasia_ea_independence","eastasia_ea_indonesia_unitary"],"selectedBranch":false,"x":1299.4,"y":827}],"note":"Separate precolonial encounters and cultural reception are shown alongside the colonial-to-independent state sequence. There is no asserted Srivijaya→Majapahit→Indonesia governmental lineage.","autoLayout":true,"continuations":[{"map":"japan-transformations","history":"tang","label":"Japan · cultures, courts and shogunates"},{"map":"china-early","history":"tang","label":"China · early cultures and dynasties"},{"map":"korea-histories","history":"yuan","label":"Korea · dynasties, colonisation and division"}],"width":1600,"height":1484},{"id":"southeast-mainland","title":"Cambodia and Vietnam · courts, colonies and modern states","region":"eastasia","nodes":[{"id":"angkor","x":491.5,"y":220},{"id":"ea-post-angkor","x":491.5,"y":500},{"id":"ea-french-cambodia","x":491.5,"y":780},{"id":"ea-cambodia-kingdom1","x":394.5,"y":1060},{"id":"ea-khmer-republic","x":394.5,"y":1340},{"id":"ea-democratic-kampuchea","x":394.5,"y":1620},{"id":"ea-prk-cambodia","x":394.5,"y":1900},{"id":"ea-cambodia-modern","x":394.5,"y":2180},{"id":"ea-nguyen","x":863.5,"y":780},{"id":"ea-french-indochina","x":798.5,"y":1060},{"id":"ea-vietnam-north","x":977.5,"y":1340},{"id":"ea-vietnam-south","x":702.5,"y":1340},{"id":"vietnammodern","x":734.5,"y":1620}],"connections":[{"id":"ea-angkor-later","from":["angkor"],"to":["ea-post-angkor"],"type":"continuation","label":"Courts move south","dates":"15th century AD","summary":"Cambodian royal centres shifted southward as Angkor’s imperial power contracted.","note":"1431 is a conventional political marker; Angkor was not wholly abandoned and Khmer people and culture continued.","sources":["eastasia_ea_sea_early_modern","eastasia_ea_cambodia_early"],"selectedBranch":false,"x":605.5,"y":407},{"id":"ea-cambodia-protectorate","from":["ea-post-angkor"],"to":["ea-french-cambodia"],"type":"colonial","label":"French protectorate","dates":"1863 AD","summary":"France established a protectorate over the Cambodian kingdom.","note":"The monarchy continued under colonial restriction; this is not a disappearance or replacement of Cambodian society.","sources":["eastasia_ea_cambodia_early"],"selectedBranch":false,"x":605.5,"y":687},{"id":"ea-cambodia-federation","from":["ea-french-cambodia"],"to":["ea-french-indochina"],"type":"colonial","label":"Colonial federation","dates":"1887 AD","summary":"Cambodia’s protectorate was incorporated into the French Indochinese federation.","note":"The protectorate and federation overlapped as different administrative levels, rather than one ending when the other began.","sources":["eastasia_ea_sea_colonial"],"selectedBranch":false,"x":735.5,"y":967},{"id":"ea-cambodia-independence","from":["ea-french-cambodia"],"to":["ea-cambodia-kingdom1"],"type":"independence","label":"Independence restored","dates":"9 November 1953 AD","summary":"Cambodia regained independence from France under the monarchy.","note":"The colonial federation’s final collapse in 1954 is a separate regional milestone.","sources":["eastasia_ea_cambodia_early"],"selectedBranch":false,"x":508.5,"y":967},{"id":"ea-cambodia-coup","from":["ea-cambodia-kingdom1"],"to":["ea-khmer-republic"],"type":"continuation","label":"Coup and republic","dates":"1970 AD","summary":"Sihanouk’s removal was followed by the proclamation of the Khmer Republic.","note":"This regime change unfolded within civil war and international intervention, not a consensual national union.","sources":["eastasia_ea_cambodia_coup"],"selectedBranch":false,"x":508.5,"y":1247},{"id":"ea-cambodia-kr","from":["ea-khmer-republic"],"to":["ea-democratic-kampuchea"],"type":"conquest","label":"Khmer Rouge victory","dates":"17 April 1975 AD","summary":"Khmer Rouge forces captured Phnom Penh and imposed a new revolutionary regime.","note":"The takeover began the mass coercion and killings of Khmer Rouge rule; Democratic Kampuchea’s formal state constitution followed in 1976.","sources":["eastasia_ea_cambodia_kr"],"selectedBranch":false,"x":508.5,"y":1527},{"id":"ea-cambodia-vietnam","from":["ea-democratic-kampuchea"],"to":["ea-prk-cambodia"],"type":"conquest","label":"Regime overthrown","dates":"1978–1979 AD","summary":"Vietnamese invasion and Cambodian allied forces overthrew the Khmer Rouge government in Phnom Penh.","note":"Khmer Rouge forces continued fighting, and diplomatic representation remained contested; January 1979 did not bring immediate peace.","sources":["eastasia_ea_cambodia_1979"],"selectedBranch":false,"x":508.5,"y":1807},{"id":"ea-cambodia-settlement","from":["ea-prk-cambodia"],"to":["ea-cambodia-modern"],"type":"continuation","label":"Peace process and monarchy","dates":"1991–1993 AD","summary":"The Paris peace process and UN transition led to elections and restoration of a constitutional monarchy in 1993.","note":"This condenses the 1989 State of Cambodia renaming and the multi-party transitional settlement; conflict did not cease instantly.","sources":["eastasia_ea_untac"],"selectedBranch":false,"x":508.5,"y":2087},{"id":"ea-nguyen-colonial","from":["ea-nguyen"],"to":["ea-french-indochina"],"type":"colonial","label":"French colonial expansion","dates":"1858–1887 AD","summary":"French conquest and protectorate arrangements subordinated Vietnamese territories before federation in Indochina.","note":"Nguyễn monarchs remained at Huế until 1945 under colonial constraint; this edge does not imply the dynasty ended in 1887.","sources":["eastasia_ea_vietnam_dynasty","eastasia_ea_sea_colonial"],"selectedBranch":false,"x":977.5,"y":967},{"id":"ea-vietnam-revolution","from":["ea-french-indochina"],"to":["ea-vietnam-north"],"type":"independence","label":"Republic proclaimed","dates":"1945 AD","summary":"The Democratic Republic of Vietnam declared independence after the collapse of wartime Japanese control.","note":"French efforts to restore colonial authority led to further war; the proclamation did not bring immediate agreed sovereignty.","sources":["eastasia_ea_vietnam_recognition","eastasia_ea_vietnam_reunion"],"selectedBranch":false,"x":1091.5,"y":1247},{"id":"ea-vietnam-zones","from":["ea-french-indochina"],"to":["ea-vietnam-north","ea-vietnam-south"],"type":"division","label":"Regroupment zones","dates":"1954–1955 AD","summary":"French defeat and the Geneva settlement left rival northern and southern administrations divided near the 17th parallel.","note":"These were provisional military regroupment zones, not an agreed permanent international frontier; DRV dated from 1945, State of Vietnam from 1949, and the southern Republic from 1955.","sources":["eastasia_ea_vietnam_recognition"],"selectedBranch":false,"x":879.5,"y":1247},{"id":"ea-vietnam-reunification","from":["ea-vietnam-north","ea-vietnam-south"],"to":["vietnammodern"],"type":"conquest","label":"Victory and reunification","dates":"1975–1976 AD","summary":"Northern victory in 1975 was followed by formal reunification as the Socialist Republic of Vietnam in July 1976.","note":"A separate provisional revolutionary government administered the South in 1975–1976; the 1976 state was not founded through a peaceful voluntary merger of the two wartime governments.","sources":["eastasia_ea_vietnam_reunion"],"selectedBranch":false,"x":848.5,"y":1527}],"note":"Two connected regional strands, with colonial and modern regime changes distinguished from enduring Khmer and Vietnamese communities. Ancient Vietnamese dynasties not already in the timeline are outside this selected expansion.","autoLayout":true,"continuations":[],"width":1600,"height":2464},{"id":"mongolia-post-yuan","title":"Mongolia · after the Yuan","region":"eastasia","nodes":[{"id":"yuan","x":548.5,"y":220},{"id":"ea-northern-yuan","x":548.5,"y":500},{"id":"ea-khalkha","x":548.5,"y":780},{"id":"qing","x":548.5,"y":1060},{"id":"ea-bogd","x":685.5,"y":1340},{"id":"ea-mongolian-republic","x":685.5,"y":1620},{"id":"ea-mongolia-modern","x":685.5,"y":1900},{"id":"republicchina","x":823.5,"y":1060}],"connections":[{"id":"ea-yuan-retreat","from":["yuan"],"to":["ea-northern-yuan"],"type":"continuation","label":"Yuan court retreats","dates":"1368 AD","summary":"Yuan rulers withdrew to Mongolia after losing their main Chinese realm.","note":"Ming replacement in China did not end the Yuan ruling line or Mongol political histories; this is a different branch from Ming succession.","sources":["eastasia_ea_mongolia_postyuan","eastasia_ea_mongolia_northern_yuan"],"selectedBranch":false,"x":662.5,"y":407},{"id":"ea-postyuan-regional","from":["ea-northern-yuan"],"to":["ea-khalkha"],"type":"division","label":"Regional Mongol powers","dates":"15th–17th centuries AD","summary":"Post-Yuan Mongol politics developed into competing confederations and principalities, including the Khalkha north of the Gobi.","note":"Khalkha were one regional grouping among Oirat, Chahar and others; this is not a single clean division in 1635 or a claim that Khalkha alone inherited the Yuan.","sources":["eastasia_ea_mongolia_postyuan"],"selectedBranch":true,"x":662.5,"y":687},{"id":"ea-khalkha-qing","from":["ea-khalkha"],"to":["qing"],"type":"continuation","label":"Khalkha submit to Qing","dates":"1691 AD","summary":"Khalkha princes entered Qing rule in 1691.","note":"Mongol groups entered Qing rule at different dates; 1691 applies to this Khalkha branch, not all Mongolia.","sources":["eastasia_ea_mongolia_qing"],"selectedBranch":false,"x":662.5,"y":967},{"id":"ea-qing-bogd","from":["qing"],"to":["ea-bogd"],"type":"independence","label":"Independence declared","dates":"1911 AD","summary":"Outer Mongolian leaders declared independence under the Bogd Khan as Qing authority collapsed.","note":"Recognition and autonomy remained contested, and Chinese forces reoccupied the territory in 1919.","sources":["eastasia_ea_mongolia_qing"],"selectedBranch":false,"x":684.5,"y":1247},{"id":"ea-roc-mongolia","from":["republicchina"],"to":["ea-bogd"],"type":"conquest","label":"Chinese reoccupation","dates":"1919–1921 AD","summary":"Chinese forces reimposed control before being expelled during the upheavals of 1921.","note":"This is a temporary occupation episode within the interrupted khanate frame, not permanent annexation or a direct line into today’s PRC.","sources":["eastasia_ea_mongolia_qing"],"selectedBranch":false,"x":926.5,"y":1247},{"id":"ea-bogd-republic","from":["ea-bogd"],"to":["ea-mongolian-republic"],"type":"continuation","label":"Republic proclaimed","dates":"1924 AD","summary":"After the 1921 revolution and the Bogd Khan’s death, a people’s republic was proclaimed.","note":"Soviet influence was strong, but Mongolia did not become one of the USSR’s constituent republics.","sources":["eastasia_ea_mongolia_republic","eastasia_ea_mongolia_qing"],"selectedBranch":false,"x":799.5,"y":1527},{"id":"ea-mongolia-democracy","from":["ea-mongolian-republic"],"to":["ea-mongolia-modern"],"type":"continuation","label":"Democratic transition","dates":"1990–1992 AD","summary":"A peaceful democratic movement led to multi-party change and a new constitutional era.","note":"1990 marks the political revolution and 1992 the new constitution; Mongolian state and social histories continued across that change.","sources":["eastasia_ea_mongolia_democracy"],"selectedBranch":false,"x":799.5,"y":1807}],"note":"A selected Outer Mongolian branch from the Yuan, distinct from the Chinese dynastic sequence and from other Mongol successor states. Present-day Mongolia was never a Soviet constituent republic.","autoLayout":true,"continuations":[{"map":"mongols-china","history":"yuan","label":"Mongol khanates & China"},{"map":"eastern-chagatai","history":"qing","label":"Eastern Chagatai · Moghulistan, Tarim and Qing conquest"},{"map":"japan-transformations","history":"yuan","label":"Japan · cultures, courts and shogunates"}],"width":1600,"height":2324},{"id":"aegean-greek-worlds","title":"Aegean networks, Greek worlds & modern independence","region":"europe","nodes":[{"id":"poster-europe-014","x":403.75,"y":220},{"id":"minoan","x":678.75,"y":220},{"id":"mycenaean","x":678.75,"y":500},{"id":"egypt","x":403.75,"y":500},{"id":"poster-europe-018","x":678.75,"y":780},{"id":"archaic","x":678.75,"y":1060},{"id":"greece","x":815.75,"y":1340},{"id":"persia","x":953.75,"y":1060},{"id":"cn-alexander","x":815.75,"y":1620},{"id":"hellenistic","x":815.75,"y":1900},{"id":"romanrepublic","x":815.75,"y":2180},{"id":"ottoman","x":954.75,"y":220},{"id":"greecemodern","x":954.75,"y":500}],"connections":[{"id":"eu-aegean-egypt","from":["poster-europe-014"],"to":["egypt"],"type":"contact","label":"Bronze Age trade networks","dates":"2nd millennium BC","summary":"Aegean communities exchanged objects, materials and diplomatic gifts with Egypt and West Asian courts.","note":"The Aegean entry is a regional cultural frame, not a united empire or the origin of Egyptian civilization.","sources":["europe_euAegean"],"selectedBranch":false,"x":517.75,"y":407},{"id":"eu-minoan-mycenaean","from":["minoan"],"to":["mycenaean"],"type":"contact","label":"Crete–mainland exchange","dates":"c. 1600–1400 BC","summary":"Minoan Cretan art and exchange strongly influenced emerging Mycenaean court cultures.","note":"Interaction did not mean that all Minoans became Mycenaeans or that either label describes one state.","sources":["europe_euMycenaean"],"selectedBranch":false,"x":792.75,"y":407},{"id":"eu-palaces-earlyiron","from":["mycenaean"],"to":["poster-europe-018"],"type":"period","label":"Palace collapse & local change","dates":"c. 1200–1050 BC","summary":"The disintegration of Mycenaean palace systems was followed by regional early Iron Age societies.","note":"A gradual and uneven archaeological transition; people and practices persisted and no single invasion is asserted as its cause.","sources":["europe_euMycenaean","europe_euGreekChronology"],"selectedBranch":false,"x":792.75,"y":687},{"id":"eu-earlyiron-archaic","from":["poster-europe-018"],"to":["archaic"],"type":"period","label":"Cities, writing & wider trade","dates":"c. 900–700 BC","summary":"City-states, alphabetic writing and wider overseas networks developed during the Geometric and early Archaic centuries.","note":"The period labels overlap in scholarly usage; this is cultural and institutional change, not a succession between two kingdoms.","sources":["europe_euGeometric"],"selectedBranch":false,"x":792.75,"y":967},{"id":"eu-archaic-classical","from":["archaic"],"to":["greece"],"type":"period","label":"Archaic → Classical convention","dates":"c. 480 BC","summary":"The Persian Wars mark the conventional transition from Archaic to Classical Greek periodisation.","note":"Greek city-states remained politically distinct and neither period boundary marks the origin or disappearance of Greek people.","sources":["europe_euClassical"],"selectedBranch":false,"x":801.75,"y":1247},{"id":"eu-persian-greek-wars","from":["persia"],"to":["greece"],"type":"contact","label":"Persian–Greek wars","dates":"490–479 BC","summary":"Achaemenid campaigns and Greek resistance reshaped relations among Persian rulers and Greek city-states.","note":"The node groups many city-states, which pursued different alliances; this was not a war between two modern nation-states.","sources":["europe_euClassical"],"selectedBranch":false,"x":1062.75,"y":1247},{"id":"eu-classical-macedonian","from":["greece"],"to":["cn-alexander"],"type":"contact","label":"Macedonian predominance","dates":"4th century BC","summary":"Macedonian royal power under Philip II provided the military and political base for Alexander’s conquests.","note":"Macedonia was one kingdom in the wider Greek world; the arrow does not turn every Greek city into a direct predecessor of his empire.","sources":["europe_euClassical"],"selectedBranch":false,"x":929.75,"y":1527},{"id":"eu-alexander-hellenistic","from":["cn-alexander"],"to":["hellenistic"],"type":"division","label":"Successor kingdoms emerge","dates":"After 323 BC","summary":"Wars among Alexander’s successors produced multiple Hellenistic kingdoms and leagues.","note":"Hellenistic kingdoms is an umbrella period; it includes several dynasties and independent city alliances, not a single successor empire.","sources":["europe_euHellenistic"],"selectedBranch":true,"x":929.75,"y":1807},{"id":"eu-hellenistic-roman","from":["hellenistic"],"to":["romanrepublic"],"type":"conquest","label":"Roman expansion in Greek East","dates":"2nd–1st centuries BC","summary":"Rome progressively defeated or annexed Hellenistic powers, with Ptolemaic Egypt annexed in 30 BC.","note":"Different states fell at different dates; Hellenistic cultures and artistic production continued under Roman government.","sources":["europe_euHellenistic","europe_euRepublic"],"selectedBranch":false,"x":929.75,"y":2087},{"id":"eu-greek-ottoman-liberation","from":["ottoman"],"to":["greecemodern"],"type":"independence","label":"War & independence recognition","dates":"1821–1832 AD","summary":"The Greek war of independence led to international recognition of an independent Greek state in 1830 and subsequent settlement in 1832.","note":"The initial state comprised only part of present-day Greece; earlier Byzantine and ancient Greek histories were not one continuous sovereign state.","sources":["europe_euGreekIndependence"],"selectedBranch":false,"x":1068.75,"y":407}],"autoLayout":true,"continuations":[{"map":"rome-francia","history":"romanrepublic","label":"Rome, Frankish realms & modern successors"},{"map":"iron-age-roman-encounters","history":"romanrepublic","label":"Iron Age communities, Rome & post-Roman Britain"},{"map":"af-nile-egypt","history":"egypt","label":"Nile Valley: Egypt, Nubia and changing rulers"}],"width":1600,"height":2604},{"id":"iron-age-roman-encounters","title":"Iron Age communities, Rome & post-Roman Britain","region":"europe","nodes":[{"id":"poster-europe-012","x":88.5,"y":500},{"id":"poster-europe-011","x":108.5,"y":780},{"id":"poster-europe-013","x":388.5,"y":780},{"id":"poster-europe-001","x":663.5,"y":780},{"id":"poster-europe-002","x":398.5,"y":500},{"id":"poster-europe-003","x":674.5,"y":500},{"id":"poster-europe-004","x":951.5,"y":500},{"id":"poster-europe-005","x":1226.5,"y":500},{"id":"poster-europe-006","x":1501.5,"y":220},{"id":"poster-europe-007","x":1501.5,"y":500},{"id":"romanrepublic","x":946.5,"y":780},{"id":"rome","x":529.5,"y":1060},{"id":"poster-europe-025","x":529.5,"y":1340},{"id":"cx-anglosaxon-realms","x":529.5,"y":1620},{"id":"england","x":529.5,"y":1900}],"connections":[{"id":"eu-hallstatt-networks","from":["poster-europe-012"],"to":["poster-europe-011"],"type":"context","label":"Central European material networks","dates":"c. 800–450 BC","summary":"Hallstatt-period communities participated in the changing Iron Age networks represented by the wider central European frame.","note":"Hallstatt is an archaeological label; it cannot be equated with every Celtic or Germanic-speaking population or with a single ethnic homeland.","sources":["europe_euHallstatt"],"selectedBranch":false,"x":202.5,"y":687},{"id":"eu-noricum-annexation","from":["poster-europe-013"],"to":["rome"],"type":"conquest","label":"Noricum enters Roman rule","dates":"c. 15 BC","summary":"The Norican kingdom was incorporated into Roman rule around 15 BC.","note":"The transition was largely peaceful in the museum account; formal provincial administration developed later, and this did not erase local communities.","sources":["europe_euNoricum"],"selectedBranch":false,"x":512.5,"y":967},{"id":"eu-central-europe-rome","from":["poster-europe-011"],"to":["rome"],"type":"contact","label":"Rhine–Danube frontier exchange","dates":"1st–4th centuries AD","summary":"Roman goods, diplomacy and military encounters connected imperial provinces with communities beyond the Rhine and Danube.","note":"Some regions were conquered and others remained outside Roman control; the arrow does not annex every society in the broad cultural frame.","sources":["europe_euRomanFrontiers"],"selectedBranch":false,"x":225.5,"y":967},{"id":"eu-britain-conquest","from":["poster-europe-001"],"to":["rome"],"type":"conquest","label":"Claudius invades Britain","dates":"43 AD onward","summary":"Roman armies invaded in 43 AD and progressively conquered much of present-day England and Wales.","note":"Conquest involved local allies and resistance and did not encompass the whole island; Iron Age communities did not disappear in 43.","sources":["europe_euBritainRoman"],"selectedBranch":false,"x":775.5,"y":967},{"id":"eu-lusitanian-rome","from":["poster-europe-002"],"to":["romanrepublic"],"type":"conquest","label":"Resistance & Roman expansion","dates":"2nd–1st centuries BC","summary":"Roman expansion into western Iberia met prolonged resistance before imperial control consolidated.","note":"The cultural block’s 139 BC endpoint follows Viriathus’ death, not the end of Lusitanian communities or the completion of conquest.","sources":["europe_euLusitania"],"selectedBranch":false,"x":512.5,"y":687},{"id":"eu-iberian-rome","from":["poster-europe-003"],"to":["romanrepublic"],"type":"conquest","label":"Long conquest of Hispania","dates":"218–19 BC","summary":"Roman expansion gradually incorporated Iberian and Celtiberian communities across many separate campaigns.","note":"The last campaigns occurred under Augustus after the Republic’s conventional endpoint; languages, settlements and identities did not abruptly vanish.","sources":["europe_euIberiaAncient"],"selectedBranch":false,"x":788.5,"y":687},{"id":"eu-carthaginian-rome","from":["poster-europe-004"],"to":["romanrepublic"],"type":"conquest","label":"Carthaginian possessions lost","dates":"218–201 BC","summary":"Rome displaced Carthaginian power in Iberia during the Second Punic War.","note":"The struggle did not immediately bring the entire peninsula under Roman control or end Indigenous resistance.","sources":["europe_euIberiaAncient"],"selectedBranch":false,"x":1068.5,"y":687},{"id":"eu-gaul-rome","from":["poster-europe-005"],"to":["romanrepublic"],"type":"conquest","label":"Alésia & Roman conquest","dates":"52 BC · selected turning point","summary":"Caesar’s victory over Vercingetorix and his allies at Alésia was a major stage in the conquest of Gaul.","note":"This is a selected campaign episode, not the disappearance of Gallic people or an instant conquest of every region.","sources":["europe_euGaul"],"selectedBranch":false,"x":1340.5,"y":687},{"id":"eu-italic-rome","from":["poster-europe-006"],"to":["poster-europe-007"],"type":"contact","label":"Rome among Italian communities","dates":"8th–6th centuries BC","summary":"Early Rome developed within the culturally and linguistically diverse Italian peninsula.","note":"Italic peoples is a collective label including Latins; it does not include every early Italian culture, and Rome was not their united kingdom.","sources":["europe_euItalyAncient","europe_euRepublic"],"selectedBranch":false,"x":1615.5,"y":407},{"id":"eu-kings-republic","from":["poster-europe-007"],"to":["romanrepublic"],"type":"continuation","label":"Monarchy → republic","dates":"509 BC · traditional chronology","summary":"Roman tradition dates the replacement of royal rule by republican government to 509 BC.","note":"Early Roman chronology combines archaeology and much later literary accounts; 753 BC is a traditional foundation date, not a securely documented founding event.","sources":["europe_euRepublic"],"selectedBranch":false,"x":1595.5,"y":687},{"id":"eu-republic-westimperial","from":["romanrepublic"],"to":["rome"],"type":"continuation","label":"Augustan principate","dates":"27 BC","summary":"Augustus’ settlement marks the conventional transition to imperial government within the Roman state.","note":"The western timeline entry overlaps the shared Roman Empire frame used in other maps; it is not a separate state founded alongside it in 27 BC.","sources":["europe_euRepublic"],"selectedBranch":false,"x":1036.5,"y":967},{"id":"eu-britain-roman-end","from":["rome"],"to":["poster-europe-025"],"type":"division","label":"Roman government ends in Britain","dates":"Early 5th century AD","summary":"Central Roman government in Britain ended and local authorities and kingdoms developed.","note":"The empire continued elsewhere; Sub-Roman Britain is a regional frame, not a new united British kingdom or a total population replacement.","sources":["europe_euBritainEarly"],"selectedBranch":true,"x":643.5,"y":1247},{"id":"eu-britain-settlement","from":["poster-europe-025"],"to":["cx-anglosaxon-realms"],"type":"contact","label":"Settlement, conflict & coexistence","dates":"5th–7th centuries AD","summary":"Migrants from continental northern Europe and existing British communities interacted as several Anglo-Saxon kingdoms formed.","note":"This overlaps the Sub-Roman frame, includes conflict and coexistence, and does not describe the whole island becoming Anglo-Saxon.","sources":["europe_euBritainEarly"],"selectedBranch":false,"x":643.5,"y":1527},{"id":"eu-anglosaxon-england","from":["cx-anglosaxon-realms"],"to":["england"],"type":"union","label":"English kingdom consolidates","dates":"10th century AD","summary":"Kings of Wessex and their successors consolidated territories into a kingdom of England during the tenth century.","note":"A protracted process involving Mercian, Northumbrian, Scandinavian and other territories, rather than a voluntary merger of all Britain; British kingdoms continued elsewhere.","sources":["europe_euBritainEarly"],"selectedBranch":false,"x":643.5,"y":1807}],"autoLayout":true,"continuations":[{"map":"aegean-greek-worlds","history":"romanrepublic","label":"Aegean networks, Greek worlds & modern independence"},{"map":"britain-atlantic","history":"england","label":"Britain & the Atlantic"},{"map":"medieval-iberian-realms","history":"rome","label":"Iberian kingdoms, al-Andalus & Portugal"}],"width":1803,"height":2324},{"id":"medieval-iberian-realms","title":"Iberian kingdoms, al-Andalus & Portugal","region":"europe","nodes":[{"id":"rome","x":763.125,"y":220},{"id":"poster-europe-045","x":763.125,"y":500},{"id":"poster-europe-046","x":763.125,"y":780},{"id":"poster-europe-047","x":763.125,"y":1060},{"id":"poster-europe-048","x":626.125,"y":1340},{"id":"poster-europe-049","x":473.125,"y":1620},{"id":"poster-europe-035","x":779.125,"y":1620},{"id":"poster-europe-036","x":779.125,"y":1900},{"id":"cn-portugal","x":779.125,"y":2180},{"id":"cn-castile","x":473.125,"y":1900},{"id":"spainmodern","x":901.125,"y":1340}],"connections":[{"id":"eu-suebi-in-hispania","from":["rome"],"to":["poster-europe-045"],"type":"continuation","label":"Suevic kingdom in former provinces","dates":"5th century AD","summary":"Suevic rulers established a kingdom in northwestern Iberian lands formerly under Roman authority.","note":"Changing rule over a selected region, not succession to the whole Roman Empire or disappearance of its provincial population.","sources":["europe_euSuebi","europe_euIberiaMedieval"],"selectedBranch":false,"x":877.125,"y":407},{"id":"eu-suebi-visigoth","from":["poster-europe-045"],"to":["poster-europe-046"],"type":"conquest","label":"Suevic realm incorporated","dates":"585 AD","summary":"Visigothic rule incorporated the Suevic kingdom in 585.","note":"This ended a separate government, not its population or all local religious institutions.","sources":["europe_euSuebi"],"selectedBranch":false,"x":877.125,"y":687},{"id":"eu-visigoth-andalus","from":["poster-europe-046"],"to":["poster-europe-047"],"type":"conquest","label":"Umayyad conquest","dates":"From 711 AD","summary":"Arab and Berber armies defeated Visigothic royal forces and conquered most of Iberia.","note":"Al-Andalus includes many later governments, while northern Christian realms and frontier zones followed different histories.","sources":["europe_euIberiaMedieval"],"selectedBranch":false,"x":877.125,"y":967},{"id":"eu-andalus-asturias","from":["poster-europe-047"],"to":["poster-europe-048"],"type":"contact","label":"Northern frontier kingdoms","dates":"8th–10th centuries AD","summary":"The Asturian monarchy developed in the north while Umayyad rulers governed much of Iberia.","note":"A frontier relationship with warfare, settlement and exchange; Asturias was not a complete successor to al-Andalus or all Visigothic territory.","sources":["europe_euIberiaMedieval"],"selectedBranch":false,"x":754.125,"y":1247},{"id":"eu-asturias-leon","from":["poster-europe-048"],"to":["poster-europe-049"],"type":"continuation","label":"Royal centre moves to León","dates":"910 AD onward","summary":"The royal centre shifted from Oviedo to León and the monarchy became known as the kingdom of León.","note":"Asturian and Leonese labels overlap; this was a change of political centre within a developing monarchy, not replacement of one people by another.","sources":["europe_euIberiaMedieval"],"selectedBranch":false,"x":587.125,"y":1527},{"id":"eu-asturias-portugalcounty","from":["poster-europe-048"],"to":["poster-europe-035"],"type":"contact","label":"Portucale within northern expansion","dates":"From 868 AD","summary":"The recovery of Porto formed the setting for the first Portucalense county under the northern Christian monarchy.","note":"A regional county within changing royal authority; its exact endpoints vary, and it was not an independent kingdom of Portugal.","sources":["europe_euPortugalCounties"],"selectedBranch":false,"x":893.125,"y":1527},{"id":"eu-portugal-county-regrant","from":["poster-europe-035"],"to":["poster-europe-036"],"type":"continuation","label":"County reconstituted","dates":"1096 AD","summary":"A new Portucalense county was assigned to Henry of Burgundy in 1096.","note":"Nuno Mendes’s defeat in 1071 ended the first comital line. Royal administration and later reorganisation preceded Henry’s county; these entries do not indicate an unbroken independent state.","sources":["europe_euPortugalCounties","europe_euPortucale1071"],"selectedBranch":false,"x":893.125,"y":1807},{"id":"eu-portugal-kingship","from":["poster-europe-036"],"to":["cn-portugal"],"type":"independence","label":"Afonso adopts kingship","dates":"1139–1179 AD","summary":"Afonso Henriques adopted royal status after 1139, followed by Leonese recognition in 1143 and papal recognition in 1179.","note":"Kingship, recognition and territorial consolidation were separate stages; the kingdom’s borders and institutions continued to change.","sources":["europe_euAfonso","europe_euPortugalCounties"],"selectedBranch":false,"x":893.125,"y":2087},{"id":"eu-leon-castile","from":["poster-europe-049"],"to":["cn-castile"],"type":"union","label":"Castile–León dynastic union","dates":"1230 AD","summary":"Ferdinand III united the crowns of Castile and León in 1230.","note":"León retained a recognised royal identity within the composite crown; dynastic union did not instantly homogenise its institutions or population.","sources":["europe_euCastile"],"selectedBranch":false,"x":587.125,"y":1807},{"id":"eu-granada-monarchy","from":["poster-europe-047"],"to":["spainmodern"],"type":"conquest","label":"Granada surrendered","dates":"1492 AD","summary":"Ferdinand and Isabella’s forces took Granada, the last Muslim-ruled Iberian kingdom, in 1492.","note":"This ended the Nasrid government, not Muslim people or culture; conversion, persecution, expulsions and continuing communities belong to later histories.","sources":["europe_euGranada"],"selectedBranch":false,"x":1007.125,"y":1247}],"autoLayout":true,"continuations":[{"map":"iron-age-roman-encounters","history":"rome","label":"Iron Age communities, Rome & post-Roman Britain"},{"map":"iberian-americas","history":"cn-portugal","label":"Iberian crowns & American successors"}],"width":1600,"height":2604},{"id":"frankish-alpine-worlds","title":"Migration, Frankish kingdoms & Alpine Austria","region":"europe","nodes":[{"id":"poster-europe-082","x":394,"y":780},{"id":"poster-europe-083","x":251,"y":1060},{"id":"cn-westrome","x":811,"y":220},{"id":"poster-europe-084","x":811,"y":500},{"id":"poster-europe-058","x":686,"y":1060},{"id":"poster-europe-085","x":811,"y":780},{"id":"carolingian","x":686,"y":1340},{"id":"holyroman","x":1120.95,"y":220},{"id":"poster-europe-096","x":1120.95,"y":500},{"id":"poster-europe-097","x":1120.95,"y":780},{"id":"poster-europe-098","x":1120.95,"y":1060},{"id":"poster-europe-099","x":1120.95,"y":1340}],"connections":[{"id":"eu-migration-context","from":["poster-europe-082"],"to":["poster-europe-083"],"type":"contact","label":"Movement into Roman territories","dates":"4th–6th centuries AD","summary":"Germanic-speaking groups were among the many populations that migrated, fought and settled within and beyond the Roman frontier.","note":"Migration Period is a broad historical frame, not a tribe or successor state; it also involves Huns, Slavs and others.","sources":["europe_euMigration"],"selectedBranch":false,"x":365,"y":967},{"id":"eu-frankish-consolidation","from":["poster-europe-082"],"to":["poster-europe-058"],"type":"contact","label":"Frankish kings consolidate Gaul","dates":"Late 5th–6th centuries AD","summary":"Clovis and later Frankish rulers consolidated kingdoms in former Roman Gaul.","note":"The Franks were one set of Germanic-speaking groups; the broad cultural label did not turn into a single Frankish nation.","sources":["europe_euFranks"],"selectedBranch":false,"x":675,"y":967},{"id":"eu-alpine-postroman","from":["cn-westrome"],"to":["poster-europe-084"],"type":"continuation","label":"Post-imperial Alpine authorities","dates":"Late 5th–6th centuries AD","summary":"The end of western imperial rule left changing authorities in the eastern Alpine provinces.","note":"The selected regional frame includes Ostrogothic influence and local continuity; it was never one kingdom called Alpine kingdoms.","sources":["europe_euItalyEarly","europe_euBavaria"],"selectedBranch":false,"x":925,"y":407},{"id":"eu-alpine-bavarian","from":["poster-europe-084"],"to":["poster-europe-085"],"type":"contact","label":"Bavarian dukes attested","dates":"By c. 555 AD","summary":"Agilolfing dukes are attested in the Bavarian region during the sixth century.","note":"Bavarian political formation was gradual; no secure single founding event or direct succession from every post-Roman Alpine authority is asserted.","sources":["europe_euBavaria"],"selectedBranch":false,"x":925,"y":687},{"id":"eu-bavaria-franks","from":["poster-europe-085"],"to":["poster-europe-058"],"type":"conquest","label":"Tassilo deposed","dates":"788 AD","summary":"Charlemagne deposed Duke Tassilo III and incorporated Bavaria under direct Carolingian authority.","note":"Bavaria remained a recognisable region and later duchy; the act did not end Bavarian communities.","sources":["europe_euBavaria788"],"selectedBranch":false,"x":925,"y":967},{"id":"eu-frankish-imperial-title","from":["poster-europe-058"],"to":["carolingian"],"type":"continuation","label":"Charlemagne crowned emperor","dates":"800 AD","summary":"Charlemagne received the imperial title in Rome in 800 while ruling the Frankish realm.","note":"The imperial-period block overlaps the broader Frankish entry; Carolingian kingship began earlier and the coronation did not absorb the Byzantine Empire.","sources":["europe_euCarolingian"],"selectedBranch":false,"x":800,"y":1247},{"id":"eu-austrian-march","from":["holyroman"],"to":["poster-europe-096"],"type":"continuation","label":"Babenberg frontier appointment","dates":"976 AD","summary":"The emperor assigned the eastern march to Liutpold of the Babenberg family in 976.","note":"The march was a subordinate frontier jurisdiction associated with Bavaria, not an independent state replacing the empire.","sources":["europe_euAustria"],"selectedBranch":false,"x":1234.95,"y":407},{"id":"eu-march-duchy","from":["poster-europe-096"],"to":["poster-europe-097"],"type":"continuation","label":"Austria raised to a duchy","dates":"1156 AD","summary":"The Privilegium minus raised Austria to a duchy and separated its ducal authority from Bavaria.","note":"It remained within the Holy Roman Empire; this was a legal and dynastic change rather than the birth of the modern republic.","sources":["europe_euAustria"],"selectedBranch":false,"x":1234.95,"y":687},{"id":"eu-duchy-archduchy","from":["poster-europe-097"],"to":["poster-europe-098"],"type":"continuation","label":"Archducal privileges confirmed","dates":"1453 AD","summary":"Emperor Frederick III confirmed privileges that recognised the Austrian archducal title.","note":"The claims originated in Rudolf IV’s fourteenth-century forgery; the Habsburg dynasty had already ruled Austria since the late thirteenth century.","sources":["europe_euArchduchy"],"selectedBranch":false,"x":1234.95,"y":967},{"id":"eu-habsburg-austrianempire","from":["poster-europe-098"],"to":["poster-europe-099"],"type":"continuation","label":"Austrian imperial title created","dates":"1804 AD","summary":"Francis adopted the hereditary title Emperor of Austria over the Habsburg lands in 1804.","note":"The new empire overlapped the Holy Roman Empire until the latter’s dissolution in 1806; its constituent lands were not all identical with the Austrian archduchy.","sources":["europe_euEmpire1804"],"selectedBranch":false,"x":1234.95,"y":1247}],"autoLayout":true,"continuations":[{"map":"rome-francia","history":"cn-westrome","label":"Rome, Frankish realms & modern successors"},{"map":"italian-rule-unification","history":"carolingian","label":"Italian kingdoms, communes & unification"}],"width":1600,"height":1764},{"id":"italian-rule-unification","title":"Italian kingdoms, communes & unification","region":"europe","nodes":[{"id":"poster-europe-072","x":531.25,"y":220},{"id":"byzantium","x":531.25,"y":500},{"id":"poster-europe-074","x":531.25,"y":780},{"id":"carolingian","x":531.25,"y":1060},{"id":"holyroman","x":818.25,"y":220},{"id":"poster-europe-075","x":818.25,"y":500},{"id":"poster-europe-076","x":818.25,"y":780},{"id":"poster-europe-078","x":818.25,"y":1060},{"id":"italymodern","x":818.25,"y":1340}],"connections":[{"id":"eu-gothic-war","from":["poster-europe-072"],"to":["byzantium"],"type":"conquest","label":"Eastern Roman reconquest","dates":"535–554 AD","summary":"Justinian’s armies defeated the Ostrogothic kingdom through a prolonged war in Italy.","note":"Campaign endpoints differ by definition; reconquest damaged the peninsula and did not produce lasting control of all Italy.","sources":["europe_euItalyEarly"],"selectedBranch":false,"x":645.25,"y":407},{"id":"eu-lombard-invasion","from":["byzantium"],"to":["poster-europe-074"],"type":"conquest","label":"Lombard invasion","dates":"568 AD onward","summary":"Lombards conquered substantial parts of Italy while the Eastern Romans retained other territories.","note":"Italy remained divided; this was not a complete transfer of Byzantine Italy or a conquest of the Byzantine Empire.","sources":["europe_euItalyEarly"],"selectedBranch":false,"x":645.25,"y":687},{"id":"eu-frankish-lombards","from":["poster-europe-074"],"to":["carolingian"],"type":"conquest","label":"Charlemagne takes Lombard crown","dates":"774 AD","summary":"Charlemagne conquered the northern Lombard kingdom and assumed its royal title.","note":"Southern Lombard principalities survived, and the imperial title represented by the Carolingian-period node followed in 800.","sources":["europe_euItalyEarly"],"selectedBranch":false,"x":645.25,"y":967},{"id":"eu-italian-communes","from":["holyroman"],"to":["poster-europe-075"],"type":"independence","label":"Communal autonomy expands","dates":"c. 1080–1183 AD","summary":"Northern and central Italian communes asserted autonomy against imperial authority, later recognised in the Peace of Constance.","note":"The Italian-states entry is a broader regional frame including varied governments; not all gained autonomy together or broke every legal tie with the empire.","sources":["europe_euItalyCommunes"],"selectedBranch":false,"x":932.25,"y":407},{"id":"eu-sicily-regionalcontext","from":["poster-europe-075"],"to":["poster-europe-076"],"type":"context","label":"Communes & southern monarchy coexist","dates":"12th–14th centuries AD","summary":"Independent communes, papal lands and the southern Sicilian monarchy formed contrasting centres of power in medieval Italy.","note":"This is a contemporary regional relationship, not a claim that northern communes merged to create the Sicilian kingdom or shared one ruler.","sources":["europe_euItalyCommunes"],"selectedBranch":false,"x":932.25,"y":687},{"id":"eu-sicily-twosicilies","from":["poster-europe-076"],"to":["poster-europe-078"],"type":"union","label":"Naples–Sicily legal union","dates":"1816 AD","summary":"The Bourbon ruler formally combined the kingdoms of Naples and Sicily as the Kingdom of the Two Sicilies.","note":"The Sicily timeline entry groups the crowns’ changing history after the 1282 division; their shared monarch did not make them one unchanged state before 1816.","sources":["europe_euSicily1816"],"selectedBranch":false,"x":932.25,"y":967},{"id":"eu-twosicilies-italy","from":["poster-europe-078"],"to":["italymodern"],"type":"conquest","label":"Southern annexation & Italian kingdom","dates":"1860–1861 AD","summary":"Garibaldi’s campaigns and Sardinian intervention brought the Two Sicilies into the new Kingdom of Italy.","note":"Unification also involved other states; Venetia joined in 1866 and Rome in 1870, and Italy became a republic in 1946.","sources":["europe_euSicily1816","europe_euItaly1861","europe_euItalyRecognition"],"selectedBranch":false,"x":932.25,"y":1247}],"autoLayout":true,"continuations":[{"map":"rome-francia","history":"byzantium","label":"Rome, Frankish realms & modern successors"},{"map":"frankish-alpine-worlds","history":"carolingian","label":"Migration, Frankish kingdoms & Alpine Austria"},{"map":"rus-byzantium-steppe","history":"byzantium","label":"Kyivan Rus’, Byzantium & regional principalities"}],"width":1600,"height":1764},{"id":"rus-byzantium-steppe","title":"Kyivan Rus’, Byzantium & regional principalities","region":"europe","nodes":[{"id":"byzantium","x":693.25,"y":220},{"id":"rus","x":693.25,"y":500},{"id":"cx-rus-principalities","x":693.25,"y":780},{"id":"cn-goldenhorde","x":361.25,"y":1060},{"id":"cn-muscovy","x":693.25,"y":1060},{"id":"cx-grandduchy-lithuania","x":1018.25,"y":1060}],"connections":[{"id":"eu-rus-christianity","from":["byzantium"],"to":["rus"],"type":"contact","label":"Christianisation & court connections","dates":"988 AD onward","summary":"Volodymyr’s adoption of Christianity strengthened ecclesiastical and artistic connections between Rus’ and Byzantium.","note":"A religious and diplomatic relationship, not incorporation into the Byzantine state or the beginning of all Rus’ settlement.","sources":["europe_euRusByzantium"],"selectedBranch":false,"x":807.25,"y":407},{"id":"eu-rus-regionalisation","from":["rus"],"to":["cx-rus-principalities"],"type":"division","label":"Regional principalities consolidate","dates":"12th–13th centuries AD","summary":"Political authority became increasingly dispersed among competing Rus’ principalities.","note":"A gradual and overlapping development, not one dated partition into the modern nations of Ukraine, Russia and Belarus.","sources":["europe_euRusHistory","europe_euRusPrincipalities"],"selectedBranch":true,"x":807.25,"y":687},{"id":"eu-rus-mongol-conquest","from":["cx-rus-principalities"],"to":["cn-goldenhorde"],"type":"conquest","label":"Mongol invasion & tributary power","dates":"1237–1242 AD","summary":"Mongol conquest, including the sack of Kyiv in 1240, subjected many Rus’ principalities to tribute under the Jochid realm.","note":"Rulers, cities and communities survived; not every Rus’ territory experienced identical control, and the Horde was not a renamed Rus’.","sources":["europe_euRusByzantium","europe_euRusHistory"],"selectedBranch":false,"x":475.25,"y":967},{"id":"eu-rus-muscovy","from":["cx-rus-principalities"],"to":["cn-muscovy"],"type":"contact","label":"Moscow expands among principalities","dates":"13th–15th centuries AD","summary":"Moscow developed within northeastern Rus’ and expanded amid competition with other principalities under Horde supremacy.","note":"One regional path only; Moscow did not inherit every Rus’ land, and the shared medieval history is not exclusive ancestry or a modern territorial entitlement.","sources":["europe_euRusHistory"],"selectedBranch":false,"x":807.25,"y":967},{"id":"eu-rus-lithuania","from":["cx-rus-principalities"],"to":["cx-grandduchy-lithuania"],"type":"conquest","label":"Western Rus’ lands incorporated","dates":"13th–14th centuries AD","summary":"Lithuanian expansion incorporated extensive western and southern Rus’ territories through changing military and dynastic relationships.","note":"Ruthenian legal and cultural traditions continued; these lands were not all incorporated at once, and Lithuania did not inherit the whole Kyivan realm.","sources":["europe_euRusLithuania"],"selectedBranch":false,"x":1132.25,"y":967}],"autoLayout":true,"continuations":[{"map":"steppe-russia","history":"cn-goldenhorde","label":"Golden Horde, Muscovy & Soviet successor states"},{"map":"italian-rule-unification","history":"byzantium","label":"Italian kingdoms, communes & unification"},{"map":"rome-francia","history":"byzantium","label":"Rome, Frankish realms & modern successors"}],"width":1600,"height":1484},{"id":"soviet-europe","title":"Soviet dissolution · Russia and eastern Europe","region":"europe","nodes":[{"id":"sovietunion","x":685.5,"y":220},{"id":"russiafederation","x":273.5,"y":500},{"id":"cn-ukraine","x":548.5,"y":500},{"id":"cn-belarus","x":823.5,"y":500},{"id":"cn-moldova","x":1098.5,"y":500}],"connections":[{"id":"mb-ussr-europe","from":["sovietunion"],"to":["russiafederation","cn-ukraine","cn-belarus","cn-moldova"],"type":"division","label":"1991 · four independent states","dates":"1991","summary":"The Soviet breakup left Russia, Ukraine, Belarus and Moldova as independent states.","note":"One geographic subset of the same union-wide breakup; the regional grouping is a viewing aid, not an intervening state. No present-day territorial claims are inferred.","sources":["modern_branches_mbSovietNato"],"selectedBranch":false,"x":799.5,"y":407}],"continuations":[{"map":"steppe-russia","history":"sovietunion","label":"Earlier: Russian and Soviet state histories"},{"map":"soviet-baltic","history":"sovietunion","label":"Baltic restoration of independence"},{"map":"soviet-caucasus","history":"sovietunion","label":"South Caucasus states"},{"map":"soviet-central-asia","history":"sovietunion","label":"Five Central Asian states"}],"autoLayout":true,"width":1600,"height":924},{"id":"soviet-baltic","title":"Soviet dissolution · Baltic independence restored","region":"europe","nodes":[{"id":"sovietunion","x":686,"y":220},{"id":"cn-estonia","x":411,"y":500},{"id":"cn-latvia","x":686,"y":500},{"id":"cn-lithuania","x":961,"y":500}],"connections":[{"id":"mb-ussr-baltic","from":["sovietunion"],"to":["cn-estonia","cn-latvia","cn-lithuania"],"type":"independence","label":"1990–91 · independence restored","dates":"1990–1991","summary":"Estonia, Latvia and Lithuania restored independence during the Soviet crisis.","note":"Soviet forces occupied and annexed these states in 1940. Lithuania proclaimed restoration in 1990; full independence and wider recognition followed in 1991. These are three of the fifteen final union republics.","sources":["modern_branches_mbBalticRestoration","modern_branches_mbBalticRecognition"],"selectedBranch":false,"x":800,"y":407}],"continuations":[{"map":"soviet-europe","history":"sovietunion","label":"Other Soviet successor states"},{"map":"steppe-russia","history":"sovietunion","label":"Golden Horde, Muscovy & Soviet successor states"}],"autoLayout":true,"width":1600,"height":924},{"id":"soviet-caucasus","title":"Soviet dissolution · South Caucasus","region":"westasia","nodes":[{"id":"sovietunion","x":686,"y":220},{"id":"cn-armenia","x":411,"y":500},{"id":"cn-azerbaijan","x":686,"y":500},{"id":"cn-georgia","x":961,"y":500}],"connections":[{"id":"mb-ussr-caucasus","from":["sovietunion"],"to":["cn-armenia","cn-azerbaijan","cn-georgia"],"type":"division","label":"1991 · three independent states","dates":"1991","summary":"Armenia, Azerbaijan and Georgia became independent as Soviet authority broke down.","note":"One geographic subset of the same union-wide breakup; the regional grouping is a viewing aid, not an intervening state. No present-day territorial claims are inferred.","sources":["modern_branches_mbSovietNato"],"selectedBranch":false,"x":800,"y":407}],"continuations":[{"map":"soviet-europe","history":"sovietunion","label":"Other Soviet successor states"},{"map":"central-asia-later","history":"sovietunion","label":"Central Asia · khanates, Russian expansion and Soviet rule"},{"map":"steppe-russia","history":"sovietunion","label":"Golden Horde, Muscovy & Soviet successor states"}],"autoLayout":true,"width":1600,"height":924},{"id":"soviet-central-asia","title":"Soviet dissolution · five Central Asian states","region":"eastasia","nodes":[{"id":"sovietunion","x":686,"y":220},{"id":"cn-kazakhstan","x":136,"y":500},{"id":"cn-kyrgyzstan","x":411,"y":500},{"id":"cn-tajikistan","x":686,"y":500},{"id":"cn-turkmenistan","x":961,"y":500},{"id":"cn-uzbekistan","x":1236,"y":500}],"connections":[{"id":"mb-ussr-central","from":["sovietunion"],"to":["cn-kazakhstan","cn-kyrgyzstan","cn-tajikistan","cn-turkmenistan","cn-uzbekistan"],"type":"division","label":"1991 · five independent states","dates":"1991","summary":"Kazakhstan, Kyrgyzstan, Tajikistan, Turkmenistan and Uzbekistan became independent in 1991.","note":"One geographic subset of the same union-wide breakup; the regional grouping is a viewing aid, not an intervening state. No present-day territorial claims are inferred.","sources":["modern_branches_mbSovietNato"],"selectedBranch":false,"x":800,"y":407}],"continuations":[{"map":"central-asia-later","history":"sovietunion","label":"Earlier: khanates, Russian expansion and Soviet rule"},{"map":"soviet-europe","history":"sovietunion","label":"Other Soviet successor states"},{"map":"steppe-russia","history":"sovietunion","label":"Golden Horde, Muscovy & Soviet successor states"}],"autoLayout":true,"width":1600,"height":924},{"id":"central-asia-later","title":"Central Asia · khanates, Russian expansion and Soviet rule","region":"eastasia","nodes":[{"id":"cn-goldenhorde","x":897.25,"y":220},{"id":"mb-abukhayr","x":897.25,"y":500},{"id":"mb-moghulistan","x":1346.2,"y":500},{"id":"mb-kazakh-khanate","x":1215.2,"y":780},{"id":"timurid","x":463.25,"y":500},{"id":"mb-bukhara-khanate","x":594.25,"y":780},{"id":"mb-bukhara-emirate","x":303.25,"y":1060},{"id":"mb-khiva","x":594.25,"y":1060},{"id":"mb-kokand","x":911.25,"y":1060},{"id":"mb-russian-central","x":632.25,"y":1340},{"id":"mb-early-soviet-central","label":"Early Soviet Central Asia","x":268.25,"y":1620},{"id":"sovietunion","x":268.25,"y":1900}],"connections":[{"id":"mb-eastern-horde","from":["cn-goldenhorde"],"to":["mb-abukhayr"],"type":"division","label":"1400s · eastern steppe powers","dates":"15th century","summary":"Abu’l-Khayr consolidated an Uzbek realm in the eastern Jochid steppe.","note":"One regional formation within post-Horde politics; other khanates and communities followed separate paths.","sources":["modern_branches_mbCentralEarly"],"selectedBranch":true,"x":1011.25,"y":407},{"id":"mb-kazakh-foundation","from":["mb-abukhayr"],"to":["mb-kazakh-khanate"],"type":"division","label":"1460s · Kazakh khanate emerges","dates":"c. 1465","summary":"Kerei and Janibek left Abu’l-Khayr’s political orbit and founded a separate khanate.","note":"The conventional 1465 date marks consolidation, not the beginning of Kazakh people or all later territory.","sources":["modern_branches_mbKazakhFoundation"],"selectedBranch":true,"x":1162.2,"y":687},{"id":"mb-kazakh-moghulistan","from":["mb-moghulistan"],"to":["mb-kazakh-khanate"],"type":"contact","label":"1460s · refuge in Moghulistan","dates":"1460s","summary":"Kerei, Janibek and their followers settled in Moghulistan before consolidating their khanate.","note":"A political refuge and regional relationship, not the entire Moghulistan realm becoming Kazakhstan.","sources":["modern_branches_mbKazakhFoundation"],"selectedBranch":false,"x":1460.2,"y":687},{"id":"mb-shaybanid-lineage","from":["mb-abukhayr"],"to":["mb-bukhara-khanate"],"type":"contact","label":"1500s · a Jochid dynastic link","dates":"Early 16th century","summary":"Abu’l-Khayr’s grandson Muhammad Shaybani led conquests in Transoxiana.","note":"Dynastic connection and military expansion, not a simple renaming or migration of an entire state.","sources":["modern_branches_mbCentralEarly"],"selectedBranch":false,"x":860.25,"y":687},{"id":"mb-transoxiana-conquest","from":["timurid"],"to":["mb-bukhara-khanate"],"type":"conquest","label":"1500–12 · Uzbek conquests","dates":"1500–1512","summary":"Shaybani and subsequent Uzbek rulers defeated Timurid claimants and consolidated Transoxiana.","note":"Different cities changed hands repeatedly; Timurid dynastic histories continued in the Mughal realm.","sources":["modern_branches_mbCentralEarly"],"selectedBranch":false,"x":577.25,"y":687},{"id":"mb-bukhara-emirs","from":["mb-bukhara-khanate"],"to":["mb-bukhara-emirate"],"type":"continuation","label":"1785 · Manghit emirate","dates":"1785","summary":"Shah Murad’s rule marks the conventional emirate frame after Manghit consolidation.","note":"A change in ruling arrangements within Bukhara, not the creation of a new population.","sources":["modern_branches_mbManghits"],"selectedBranch":false,"x":417.25,"y":967},{"id":"mb-khiva-neighbours","from":["mb-bukhara-khanate"],"to":["mb-khiva"],"type":"contact","label":"1500s–1800s · neighbours and rivals","dates":"16th–19th centuries","summary":"Bukhara and Khwarazm maintained separate ruling houses and competing regional interests.","note":"Contact does not imply that Khiva broke away from Bukhara or that either matches one modern nation.","sources":["modern_branches_mbKhiva"],"selectedBranch":false,"x":708.25,"y":967},{"id":"mb-kokand-formation","from":["mb-bukhara-khanate"],"to":["mb-kokand"],"type":"independence","label":"1700s · Fergana consolidation","dates":"Early 18th century","summary":"Fergana’s growing autonomy developed into the Kokand khanate.","note":"Separation and consolidation occurred in stages; the conventional 1709 foundation is not a sudden border-wide transfer.","sources":["modern_branches_mbCentralRussian"],"selectedBranch":false,"x":1025.25,"y":967},{"id":"mb-kazakh-russian","from":["mb-kazakh-khanate"],"to":["mb-russian-central"],"type":"colonial","label":"1700s–1800s · Russian encroachment","dates":"18th–19th centuries","summary":"Russian authority expanded through the Kazakh steppe by unequal agreements, administrative changes and conquest.","note":"Different zhuzes and regions were incorporated at different times, amid resistance.","sources":["modern_branches_mbKazakhRussian"],"selectedBranch":false,"x":1329.2,"y":1107},{"id":"mb-kokand-russian","from":["mb-kokand"],"to":["mb-russian-central"],"type":"conquest","label":"1860s–76 · conquest and annexation","dates":"1864–1876","summary":"Russian forces took Kokandian territories and abolished the remaining khanate in 1876.","note":"Kokand’s dissolution did not end Kyrgyz, Uzbek, Tajik or other regional communities.","sources":["modern_branches_mbCentralRussian"],"selectedBranch":false,"x":1048.25,"y":1247},{"id":"mb-protectorates","from":["mb-bukhara-emirate"],"to":["mb-russian-central"],"type":"colonial","label":"1868 · Russian domination","dates":"1868 and after","summary":"Bukhara came under Russian domination while retaining its emir’s government.","note":"This was unequal subordination and territorial loss, not immediate annexation of the whole emirate.","sources":["modern_branches_mbBukhara"],"selectedBranch":false,"x":478.25,"y":1247},{"id":"mb-khiva-protectorate","from":["mb-khiva"],"to":["mb-russian-central"],"type":"colonial","label":"1873 · Khivan protectorate","dates":"1873","summary":"Russian conquest reduced Khiva to a protectorate and annexed part of its territory.","note":"The khan’s restricted government survived until 1920.","sources":["modern_branches_mbKhiva"],"selectedBranch":false,"x":746.25,"y":1247},{"id":"mb-central-soviet-rule","from":["mb-khiva","mb-bukhara-emirate"],"to":["mb-early-soviet-central"],"type":"conquest","label":"1920 · khanate governments fall","dates":"1920","summary":"Red Army campaigns and local revolutionary movements overthrew the Khivan khan and Bukharan emir.","note":"New Khorezm and Bukharan republics preceded later Soviet territorial reorganisation; armed resistance continued.","sources":["modern_branches_mbCentralSoviet"],"selectedBranch":false,"x":191.25,"y":1247},{"id":"mb-central-republics","from":["mb-early-soviet-central"],"to":["sovietunion"],"type":"continuation","label":"1924–36 · five union republics","dates":"1924–1936","summary":"Soviet reorganisation established Uzbek and Turkmen republics, followed by Tajik, Kazakh and Kyrgyz union republics.","note":"Tajikistan had an earlier autonomous status within Uzbekistan; Kazakh and Kyrgyz republics attained union status in 1936. This did not invent the region’s peoples.","sources":["modern_branches_mbCentralSoviet"],"selectedBranch":false,"x":382.25,"y":1807},{"id":"mb-central-revolution","from":["mb-russian-central"],"to":["mb-early-soviet-central"],"type":"continuation","label":"1917 onward · revolution and war","dates":"From 1917","summary":"Revolution broke imperial authority, followed by competing autonomy projects, civil war and Soviet consolidation.","note":"A regional overview of contested transitions, not the entire empire becoming one Soviet administration at once.","sources":["modern_branches_mbCentralSoviet"],"selectedBranch":false,"x":659.25,"y":1527}],"continuations":[{"map":"soviet-central-asia","history":"sovietunion","label":"Continue: five independent states in 1991"},{"map":"eastern-chagatai","history":"mb-moghulistan","label":"Eastern Chagatai and Tarim branches"},{"map":"iran-modern","history":"timurid","label":"Timurid and Iranian branches"},{"map":"steppe-russia","history":"cn-goldenhorde","label":"Other Horde and Russian histories"}],"autoLayout":true,"width":1644,"height":2324},{"id":"eastern-chagatai","title":"Eastern Chagatai · Moghulistan, Tarim and Qing conquest","region":"eastasia","nodes":[{"id":"cn-chagatai","x":456.875,"y":220},{"id":"mb-moghulistan","x":456.875,"y":500},{"id":"mb-yarkent","x":594.875,"y":780},{"id":"mb-turpan","x":319.875,"y":780},{"id":"mb-khojas","x":719.875,"y":1060},{"id":"mb-dzungar","x":1019.875,"y":780},{"id":"qing","x":719.875,"y":1340}],"connections":[{"id":"mb-moghulistan-formation","from":["cn-chagatai"],"to":["mb-moghulistan"],"type":"division","label":"1340s · eastern khanate","dates":"Mid-14th century","summary":"Moghulistan emerged as the eastern Chagataid political realm while western power fragmented.","note":"Timur’s later western conquests did not eliminate the eastern Chagataid realm.","sources":["modern_branches_mbCentralMedieval"],"selectedBranch":true,"x":570.875,"y":407},{"id":"mb-eastern-regional-realms","from":["mb-moghulistan"],"to":["mb-yarkent","mb-turpan"],"type":"division","label":"1500s · regional Chagataid branches","dates":"Early 16th century","summary":"Chagataid rulers maintained distinct centres in the Tarim Basin and Turpan.","note":"Selected related branches after prolonged division and warfare; their territories did not comprise all former Moghulistan.","sources":["modern_branches_mbCentralMedieval"],"selectedBranch":false,"x":570.875,"y":687},{"id":"mb-khoja-change","from":["mb-yarkent"],"to":["mb-khojas"],"type":"continuation","label":"1670s · Khoja and Dzungar intervention","dates":"Late 1670s","summary":"Afaq Khoja gained power in Kashgaria with Dzungar support, displacing Chagataid authority.","note":"Dating varies around 1678–1680; rival lineages and nominal princes continued to complicate local rule.","sources":["modern_branches_mbKhojas"],"selectedBranch":false,"x":696.875,"y":967},{"id":"mb-dzungar-supremacy","from":["mb-dzungar"],"to":["mb-khojas"],"type":"conquest","label":"1670s–1750s · Dzungar supremacy","dates":"Late 17th–mid-18th centuries","summary":"Dzungar khans imposed tribute and hostages on the Tarim Khoja governments.","note":"Overlordship and intervention, not the formation of the Dzungar state from the Chagataid dynasty.","sources":["modern_branches_mbKhojas"],"selectedBranch":false,"x":1032.875,"y":967},{"id":"mb-turpan-qing","from":["mb-turpan"],"to":["qing"],"type":"contact","label":"1720s–50s · Qing alliance and rule","dates":"1720s–1750s","summary":"Turpan leaders sought Qing support against Dzungar power as Qing troops entered the oasis.","note":"Alliance, warfare, forced movement and later return unfolded over decades; Turpan was not simply annexed once in 1720.","sources":["modern_branches_mbTurpanQing"],"selectedBranch":false,"x":481.875,"y":1107},{"id":"mb-dzungar-qing","from":["mb-dzungar"],"to":["qing"],"type":"conquest","label":"1750s · Dzungar state destroyed","dates":"1755–1759","summary":"Qing campaigns destroyed the Dzungar state and incorporated its territories.","note":"The conquest brought catastrophic loss of life and displacement; surviving Oirat communities did not disappear.","sources":["modern_branches_mbDzungar","modern_branches_mbDzungarLoss"],"selectedBranch":false,"x":1148.875,"y":1247},{"id":"mb-tarim-qing","from":["mb-khojas"],"to":["qing"],"type":"conquest","label":"1759 · Kashgaria conquered","dates":"1759","summary":"Qing forces ended the Khojas’ government in Kashgaria.","note":"Resistance and Khoja political claims continued later; conquest did not end the region’s Muslim or Turkic communities.","sources":["modern_branches_mbKhojas"],"selectedBranch":false,"x":833.875,"y":1247}],"continuations":[{"map":"mongols-china","history":"qing","label":"Continue: Qing → republican and present-day Chinese frames"},{"map":"central-asia-later","history":"mb-moghulistan","label":"Kazakh and western Central Asian branches"},{"map":"iran-modern","history":"cn-chagatai","label":"Western Chagatai → Timurid and Iranian histories"}],"autoLayout":true,"width":1600,"height":1764},{"id":"mesopotamia-iran","title":"Mesopotamia & early Iran","region":"westasia","nodes":[{"id":"sumer","x":474.1,"y":220},{"id":"uruk","x":217.10000000000002,"y":500},{"id":"mesop","x":178.10000000000002,"y":780},{"id":"akkad","x":178.10000000000002,"y":1060},{"id":"oldbab","x":812.1,"y":500},{"id":"hittite","x":812.1,"y":220},{"id":"kassite","x":748.1,"y":780},{"id":"middle-assyrian","x":522.1,"y":500},{"id":"elam","x":1095.1,"y":500},{"id":"assyria","x":460.1,"y":780},{"id":"medes","x":1000.0999999999999,"y":1060},{"id":"neo-babylonian","x":725.1,"y":1060},{"id":"early-iranian-peoples","x":1023.0999999999999,"y":780},{"id":"persia","x":976.0999999999999,"y":1340}],"connections":[{"id":"ws-sumer-uruk","from":["sumer"],"to":["uruk"],"type":"context","label":"Urban culture","dates":"4th millennium BC","summary":"Uruk was a major center within the wider Sumerian urban landscape.","note":"This is cultural overlap, not one state succeeding another.","sources":["west_south_ws_mesoearly"],"selectedBranch":false,"x":413.1,"y":407},{"id":"ws-uruk-citystates","from":["uruk"],"to":["mesop"],"type":"period","label":"Later city-state period","dates":"c. 3000–2900 BC","summary":"The Uruk urban phase preceded the Early Dynastic landscape of competing cities.","note":"Archaeological periods overlap locally; Uruk itself continued to exist.","sources":["west_south_ws_mesoearly"],"selectedBranch":false,"x":292.1,"y":687},{"id":"ws-sargon-conquest","from":["mesop"],"to":["akkad"],"type":"conquest","label":"Sargon’s conquests","dates":"c. 24th century BC","summary":"Sargon brought numerous Mesopotamian city-states under Akkadian imperial rule.","note":"Conquest did not erase Sumerian cities or language.","sources":["west_south_ws_mesoearly"],"selectedBranch":false,"x":292.1,"y":967},{"id":"ws-sumer-babylon","from":["sumer"],"to":["oldbab"],"type":"contact","label":"Scribal inheritance","dates":"early 2nd millennium BC","summary":"Old Babylonian scribes copied and transmitted Sumerian literature.","note":"A cultural relationship spanning intervening dynasties, not immediate political succession.","sources":["west_south_ws_oldbab"],"selectedBranch":false,"x":684.1,"y":407},{"id":"ws-hittite-babylon","from":["hittite"],"to":["oldbab"],"type":"conquest","label":"Sack of Babylon","dates":"c. 1595 BC","summary":"A Hittite raid ended Babylon’s first dynasty.","note":"The attackers withdrew; this was not permanent Hittite rule of Babylonia.","sources":["west_south_ws_oldbab"],"selectedBranch":false,"x":926.1,"y":407},{"id":"ws-kassite-rise","from":["oldbab"],"to":["kassite"],"type":"continuation","label":"Kassite consolidation","dates":"after c. 1595 BC","summary":"Kassite rulers gradually consolidated Babylonia after the first dynasty’s collapse.","note":"The transition is obscure and included rival southern rulers.","sources":["west_south_ws_kassite"],"selectedBranch":false,"x":958.1,"y":687},{"id":"ws-assyria-kassites","from":["middle-assyrian"],"to":["kassite"],"type":"conquest","label":"Assyrian occupation","dates":"c. 1225 BC","summary":"Tukulti-Ninurta I conquered Babylon during Kassite rule.","note":"The Kassite dynasty survived this intervention.","sources":["west_south_ws_kassite"],"selectedBranch":false,"x":731.1,"y":687},{"id":"ws-elam-kassites","from":["elam"],"to":["kassite"],"type":"conquest","label":"Elamite campaigns","dates":"c. 1155 BC","summary":"Elamite attacks brought the Kassite dynasty to an end.","note":"Subsequent Babylonian dynasties, not lasting Elamite annexation, followed.","sources":["west_south_ws_kassite","west_south_ws_iranbronze"],"selectedBranch":false,"x":1178.1,"y":687},{"id":"ws-assyrian-periods","from":["middle-assyrian"],"to":["assyria"],"type":"continuation","label":"Renewed expansion","dates":"c. 911 BC onward","summary":"Later Assyrian kings renewed expansion after a period of contraction.","note":"Middle and Neo-Assyrian are modern period labels, not a single dated founding event.","sources":["west_south_ws_mesoiron"],"selectedBranch":false,"x":519.1,"y":687},{"id":"ws-assyria-babylonia","from":["assyria"],"to":["medes","neo-babylonian"],"type":"conquest","label":"Fall of Nineveh","dates":"612 BC","summary":"Babylonian and Median forces destroyed the Assyrian capital of Nineveh.","note":"Assyrian resistance continued after 612; neither the people nor their culture vanished.","sources":["west_south_ws_mesoiron"],"selectedBranch":false,"x":839.1,"y":967},{"id":"ws-iranian-medes","from":["early-iranian-peoples"],"to":["medes"],"type":"contact","label":"Iranian languages","dates":"9th–6th centuries BC","summary":"The Medes were among the Iranian-speaking groups recorded in western Iran.","note":"A linguistic category is not a unified ancestral empire.","sources":["west_south_ws_iraniron","west_south_ws_media"],"selectedBranch":false,"x":1125.1,"y":967},{"id":"ws-medes-persia","from":["medes"],"to":["persia"],"type":"conquest","label":"Cyrus defeats Astyages","dates":"c. 550 BC","summary":"Cyrus overthrew the Median ruler and incorporated Media into his growing empire.","note":"The extent and organization of an earlier Median empire remain debated.","sources":["west_south_ws_media","west_south_ws_mesoiron"],"selectedBranch":false,"x":1090.1,"y":1247},{"id":"ws-babylon-persia","from":["neo-babylonian"],"to":["persia"],"type":"conquest","label":"Capture of Babylon","dates":"539 BC","summary":"Cyrus captured Babylon and incorporated Babylonia into Achaemenid rule.","note":"Local institutions and traditions continued under new imperial government.","sources":["west_south_ws_mesoiron"],"selectedBranch":false,"x":851.1,"y":1247},{"id":"ws-elam-persia","from":["elam"],"to":["persia"],"type":"contact","label":"Susa & administration","dates":"6th century BC onward","summary":"Susa and Elamite administrative traditions became important within Achaemenid government.","note":"Elam’s diverse earlier kingdoms are not one dynasty directly replaced on a single date.","sources":["west_south_ws_achaemenidadmin"],"selectedBranch":false,"x":1328.1,"y":1247}],"autoLayout":true,"continuations":[{"map":"ancient-anatolia-levant","history":"hittite","label":"Ancient Anatolia & Levant"},{"map":"west-asia","history":"persia","label":"Persian, Hellenistic & Islamic realms"}],"width":1600,"height":1764},{"id":"ancient-anatolia-levant","title":"Ancient Anatolia & Levant","region":"westasia","nodes":[{"id":"hittite","x":60,"y":220},{"id":"neo-hittite","x":60,"y":500},{"id":"assyria","x":190,"y":780},{"id":"lydia","x":767,"y":220},{"id":"persia","x":689,"y":500},{"id":"phoenicia","x":414,"y":220},{"id":"israel-samaria","x":335,"y":500},{"id":"judah","x":1042,"y":220},{"id":"neo-babylonian","x":1042,"y":500},{"id":"cn-seleucid","x":1317,"y":220},{"id":"hasmonean-judea","x":1317,"y":500},{"id":"ws-herodian-judea","x":1454,"y":780},{"id":"romanrepublic","x":1592,"y":500}],"connections":[{"id":"ws-hittite-neohittite","from":["hittite"],"to":["neo-hittite"],"type":"division","label":"Regional successor states","dates":"after c. 1180 BC","summary":"Independent southeastern states preserved some Hittite dynastic and cultural traditions after the empire fell.","note":"These included Luwian and Aramaean polities, not a single restored Hittite empire.","sources":["west_south_ws_anatoliabronze","west_south_ws_neohittite"],"selectedBranch":true,"x":174,"y":407},{"id":"ws-neohittite-assyria","from":["neo-hittite"],"to":["assyria"],"type":"conquest","label":"Assyrian expansion","dates":"9th–8th centuries BC","summary":"Assyrian expansion progressively absorbed Syro-Hittite kingdoms.","note":"Different kingdoms were conquered at different times.","sources":["west_south_ws_neohittite","west_south_ws_anatoliairon"],"selectedBranch":false,"x":190,"y":687},{"id":"ws-lydia-persia","from":["lydia"],"to":["persia"],"type":"conquest","label":"Fall of Croesus","dates":"c. 547/546 BC","summary":"Cyrus defeated Lydia and brought western Anatolia under Persian rule.","note":"The conventional dating varies slightly across chronologies.","sources":["west_south_ws_anatoliairon"],"selectedBranch":false,"x":881,"y":407},{"id":"ws-phoenician-samaria","from":["phoenicia"],"to":["israel-samaria"],"type":"contact","label":"Artistic exchange","dates":"9th–8th centuries BC","summary":"Samaria’s ivories show exchanges with Phoenician and Syrian neighbors.","note":"Shared artistic forms do not prove a shared political identity.","sources":["west_south_ws_samaria"],"selectedBranch":false,"x":449,"y":407},{"id":"ws-samaria-assyria","from":["israel-samaria"],"to":["assyria"],"type":"conquest","label":"Capture of Samaria","dates":"722/721 BC","summary":"Assyrian conquest ended the northern kingdom and deported part of its population.","note":"People remained in the region; this was not the disappearance of all Israelites.","sources":["west_south_ws_mesoiron"],"selectedBranch":false,"x":418,"y":687},{"id":"ws-judah-babylon","from":["judah"],"to":["neo-babylonian"],"type":"conquest","label":"Jerusalem destroyed","dates":"587/586 BC","summary":"Babylonian forces destroyed Jerusalem’s temple and deported part of Judah’s population.","note":"The exiles were not all inhabitants, and Jewish history continued in several places.","sources":["west_south_ws_mesoiron"],"selectedBranch":false,"x":1156,"y":407},{"id":"ws-phoenician-empire","from":["phoenicia"],"to":["persia"],"type":"colonial","label":"Persian imperial rule","dates":"6th–4th centuries BC","summary":"Phoenician cities came under Achaemenid rule while maintaining important maritime roles.","note":"Their earlier city-state independence was already constrained by several empires.","sources":["west_south_ws_levantiron"],"selectedBranch":false,"x":669,"y":407},{"id":"ws-seleucid-hasmonean","from":["cn-seleucid"],"to":["hasmonean-judea"],"type":"independence","label":"Hasmonean autonomy","dates":"2nd century BC","summary":"Hasmonean rulers gained autonomy amid Seleucid conflict and declining control of Judea.","note":"The revolt and independence were processes involving competing local factions.","sources":["west_south_ws_hasmonean"],"selectedBranch":false,"x":1431,"y":407},{"id":"ws-hasmonean-herod","from":["hasmonean-judea"],"to":["ws-herodian-judea"],"type":"conquest","label":"Roman-backed Herod","dates":"37 BC","summary":"Herod captured Jerusalem with Roman support and displaced the last Hasmonean ruler.","note":"Roman involvement in Judea had begun earlier; Herod ruled as a client king.","sources":["west_south_ws_herod"],"selectedBranch":false,"x":1449,"y":687},{"id":"ws-rome-herod","from":["romanrepublic"],"to":["ws-herodian-judea"],"type":"contact","label":"Roman patronage","dates":"40–37 BC","summary":"Roman political and military support enabled Herod’s kingship.","note":"This relationship concerns Roman patronage, not an equal alliance.","sources":["west_south_ws_herod"],"selectedBranch":false,"x":1687,"y":687}],"autoLayout":true,"continuations":[{"map":"mesopotamia-iran","history":"hittite","label":"Mesopotamia & early Iran"},{"map":"west-asia","history":"persia","label":"Persian, Hellenistic & Islamic realms"},{"map":"aegean-greek-worlds","history":"persia","label":"Aegean networks, Greek worlds & modern independence"}],"width":1880,"height":1204},{"id":"seljuqs-anatolia","title":"Seljuqs, Anatolia & Iran","region":"westasia","nodes":[{"id":"abbasid","x":273.5,"y":220},{"id":"seljuq","x":273.5,"y":500},{"id":"byzantium","x":195.5,"y":780},{"id":"sultanate-rum","x":548.5,"y":780},{"id":"mongol","x":626.5,"y":500},{"id":"ws-anatolian-beyliks","x":548.5,"y":1060},{"id":"ottoman","x":548.5,"y":1340},{"id":"cn-ilkhanate","x":901.5,"y":220},{"id":"post-abbasid-dynasties","x":901.5,"y":500},{"id":"timurid","x":901.5,"y":780},{"id":"qajar","x":1176.5,"y":220},{"id":"iranmodern","x":1176.5,"y":500}],"connections":[{"id":"ws-seljuq-baghdad","from":["abbasid"],"to":["seljuq"],"type":"conquest","label":"Seljuqs take Baghdad","dates":"1055","summary":"Seljuq rulers took Baghdad and exercised military power alongside the Abbasid caliphate.","note":"The caliphate continued; the Seljuqs did not become a replacement caliphate.","sources":["west_south_ws_seljuq"],"selectedBranch":false,"x":387.5,"y":407},{"id":"ws-seljuq-byzantium","from":["seljuq"],"to":["byzantium"],"type":"conquest","label":"Battle of Manzikert","dates":"1071","summary":"Seljuq forces defeated the Byzantine army at Manzikert, accelerating changes across Anatolia.","note":"Byzantium survived; settlement and political transformation took decades.","sources":["west_south_ws_seljuq"],"selectedBranch":false,"x":309.5,"y":687},{"id":"ws-seljuq-rum","from":["seljuq"],"to":["sultanate-rum"],"type":"division","label":"Anatolian branch","dates":"late 11th century","summary":"A Seljuq branch established the Sultanate of Rûm in Anatolia.","note":"Related dynastic branches overlapped rather than splitting in a single treaty.","sources":["west_south_ws_seljuq"],"selectedBranch":true,"x":517.5,"y":687},{"id":"ws-mongol-rum","from":["mongol"],"to":["sultanate-rum"],"type":"conquest","label":"Köse Dağ & overlordship","dates":"1243 onward","summary":"Mongol victory at Köse Dağ reduced the Sultanate of Rûm to dependent status.","note":"The Ilkhanate was established later; the 1243 attackers were a Mongol imperial army.","sources":["west_south_ws_seljuq"],"selectedBranch":false,"x":740.5,"y":687},{"id":"ws-rum-beyliks","from":["sultanate-rum"],"to":["ws-anatolian-beyliks"],"type":"division","label":"Regional principalities","dates":"13th–14th centuries","summary":"Declining Seljuq authority accompanied the growth of rival Anatolian principalities.","note":"Not every beylik originated in the same way or at the same time.","sources":["west_south_ws_anatoliamedieval"],"selectedBranch":true,"x":662.5,"y":967},{"id":"ws-beylik-ottoman","from":["ws-anatolian-beyliks"],"to":["ottoman"],"type":"continuation","label":"Ottoman expansion","dates":"c. 1300–15th century","summary":"The Ottoman principality grew among these rivals and progressively absorbed many of them.","note":"The Ottomans were one beylik among several, not the automatic successor to all Seljuq lands.","sources":["west_south_ws_ottomanrise","west_south_ws_anatoliamedieval"],"selectedBranch":false,"x":662.5,"y":1247},{"id":"ws-regional-ilkhanate","from":["cn-ilkhanate"],"to":["post-abbasid-dynasties"],"type":"contact","label":"Regional dynastic context","dates":"1258–1501","summary":"The Ilkhanate and later regional dynasties form parts of this broad Iran–Iraq period.","note":"This umbrella entry is not a separate successor state.","sources":["west_south_ws_ilkhanid","west_south_ws_iraqmedieval"],"selectedBranch":false,"x":1015.5,"y":407},{"id":"ws-regional-timur","from":["post-abbasid-dynasties"],"to":["timurid"],"type":"conquest","label":"Timur’s campaigns","dates":"late 14th century","summary":"Timur conquered much of Iran and Iraq amid competing regional dynasties.","note":"The umbrella period includes multiple polities and overlapping zones of rule.","sources":["west_south_ws_timur"],"selectedBranch":false,"x":1015.5,"y":687},{"id":"ws-qajar-modern","from":["qajar"],"to":["iranmodern"],"type":"continuation","label":"Pahlavi dynasty","dates":"1925","summary":"The Pahlavi dynasty replaced Qajar rule in Iran.","note":"The endpoint groups Pahlavi and later republican eras; the dedicated Iran map distinguishes 1979.","sources":["west_south_ws_iranmodern"],"selectedBranch":false,"x":1290.5,"y":407}],"autoLayout":true,"continuations":[{"map":"iran-modern","history":"cn-ilkhanate","label":"From the Ilkhanate to modern Iran"},{"map":"west-asia","history":"abbasid","label":"Persian, Hellenistic & Islamic realms"},{"map":"modern-levant","history":"ottoman","label":"Mandates, Israel & Palestine"}],"width":1600,"height":1764},{"id":"ottoman-arab-states","title":"Ottoman lands & Arab states","region":"westasia","nodes":[{"id":"ottoman","x":788.5,"y":220},{"id":"ws-british-iraq","x":479.5,"y":500},{"id":"iraq-kingdom","x":273.5,"y":780},{"id":"iraqmodern","x":273.5,"y":1060},{"id":"ws-french-levant","x":788.5,"y":500},{"id":"ws-syria","x":548.5,"y":780},{"id":"ws-lebanon","x":823.5,"y":780},{"id":"ws-hejaz-nejd","x":1080.5,"y":500},{"id":"saudiarabia","x":1098.5,"y":780}],"connections":[{"id":"ws-ottoman-iraq","from":["ottoman"],"to":["ws-british-iraq"],"type":"colonial","label":"British wartime occupation","dates":"1914–1920s","summary":"British conquest of Ottoman Mesopotamia was followed by a mandate project and treaty arrangements.","note":"Postwar borders and institutions were contested, including during the Iraqi revolt of 1920.","sources":["west_south_ws_iraqmandate"],"selectedBranch":false,"x":642.5,"y":407},{"id":"ws-iraq-monarchy","from":["ws-british-iraq"],"to":["iraq-kingdom"],"type":"continuation","label":"Faisal’s monarchy","dates":"1921; independence 1932","summary":"Faisal became king in 1921 while British supervision continued until formal independence in 1932.","note":"The monarchy overlapped with British control rather than beginning after it ended.","sources":["west_south_ws_iraqrepublic"],"selectedBranch":false,"x":524.5,"y":687},{"id":"ws-iraq-coup","from":["iraq-kingdom"],"to":["iraqmodern"],"type":"continuation","label":"Republican coup","dates":"14 July 1958","summary":"Army officers overthrew the Hashemite monarchy and proclaimed a republican government.","note":"Later republican regimes are grouped by the timeline, not treated as one unchanged government.","sources":["west_south_ws_iraqcoup"],"selectedBranch":false,"x":387.5,"y":967},{"id":"ws-ottoman-french-levant","from":["ottoman"],"to":["ws-french-levant"],"type":"colonial","label":"French mandate rule","dates":"1918–1923","summary":"After Ottoman defeat and contested postwar settlement, Syria and Lebanon came under French mandate rule.","note":"This schematic omits the short-lived Arab Kingdom of Syria and several mandate subdivisions.","sources":["west_south_ws_syria","west_south_ws_lebanon"],"selectedBranch":false,"x":902.5,"y":407},{"id":"ws-levant-independence","from":["ws-french-levant"],"to":["ws-syria","ws-lebanon"],"type":"independence","label":"Independence & withdrawal","dates":"1943–1946","summary":"Syria and Lebanon achieved independence through separate processes, completed by French troop withdrawal.","note":"Lebanon commemorates 1943; Syria commemorates the 1946 evacuation.","sources":["west_south_ws_syria","west_south_ws_lebanon"],"selectedBranch":false,"x":902.5,"y":687},{"id":"ws-ottoman-saudi","from":["ottoman"],"to":["ws-hejaz-nejd"],"type":"conquest","label":"Territorial consolidation","dates":"1913–1920s","summary":"Ibn Saud’s expansion included taking al-Ahsa from Ottoman forces before later consolidating his dominions.","note":"Not all Saudi territories had been directly administered by the Ottomans.","sources":["west_south_ws_saudi"],"selectedBranch":false,"x":1160.5,"y":407},{"id":"ws-saudi-name","from":["ws-hejaz-nejd"],"to":["saudiarabia"],"type":"union","label":"Kingdom proclaimed","dates":"23 September 1932","summary":"The consolidated dominions were proclaimed the Kingdom of Saudi Arabia.","note":"The proclamation followed years of conquest and administration; it was not a union of all Arabian states.","sources":["west_south_ws_saudiname"],"selectedBranch":false,"x":1203.5,"y":687}],"autoLayout":true,"continuations":[{"map":"modern-levant","history":"ottoman","label":"Mandates, Israel & Palestine"},{"map":"seljuqs-anatolia","history":"ottoman","label":"Seljuqs, Anatolia & Iran"}],"width":1600,"height":1484},{"id":"modern-levant","title":"Mandates, Israel & Palestine","region":"westasia","nodes":[{"id":"ottoman","x":691.125,"y":220},{"id":"ws-mandate-palestine","x":691.125,"y":500},{"id":"ws-transjordan","x":416.125,"y":780},{"id":"ws-jordan","x":416.125,"y":1060},{"id":"israel","x":691.125,"y":780},{"id":"ws-plo","x":803.125,"y":1060},{"id":"palestine","x":803.125,"y":1340}],"connections":[{"id":"ws-ottoman-palestine","from":["ottoman"],"to":["ws-mandate-palestine"],"type":"colonial","label":"British administration","dates":"1917–1923","summary":"British military conquest was followed by League of Nations mandate administration in Palestine.","note":"The population’s political rights and future were contested; this was not a consensual union.","sources":["west_south_ws_mandates"],"selectedBranch":false,"x":805.125,"y":407},{"id":"ws-palestine-transjordan","from":["ws-mandate-palestine"],"to":["ws-transjordan"],"type":"contact","label":"Separate administrations","dates":"1921–1922","summary":"Transjordan developed under a separate Arab administration within the wider mandate framework.","note":"The map’s Palestine node denotes territory west of the Jordan, not a claim that the emirate was carved from an already independent state.","sources":["west_south_ws_jordan"],"selectedBranch":false,"x":552.125,"y":687},{"id":"ws-transjordan-independence","from":["ws-transjordan"],"to":["ws-jordan"],"type":"independence","label":"Independent kingdom","dates":"1946","summary":"British recognition of Transjordan’s independence ended the mandate relationship there.","note":"Recognition, treaty effect, and the kingdom’s proclamation had different dates within 1946.","sources":["west_south_ws_jordan"],"selectedBranch":false,"x":530.125,"y":967},{"id":"ws-israel-declaration","from":["ws-mandate-palestine"],"to":["israel"],"type":"independence","label":"Israel proclaimed","dates":"14 May 1948","summary":"Israel was proclaimed as British rule ended, amid war in the former mandate territory.","note":"The 1947 UN partition proposal did not produce two functioning states as envisaged.","sources":["west_south_ws_israeldeclaration","west_south_ws_palestinehistory"],"selectedBranch":false,"x":805.125,"y":687},{"id":"ws-palestinian-movement","from":["ws-mandate-palestine"],"to":["ws-plo"],"type":"contact","label":"Displacement & organizing","dates":"1948–1964","summary":"War, Palestinian displacement, and continuing national mobilization preceded the PLO’s establishment.","note":"A contextual political history link, not a transfer of British governmental authority to the PLO.","sources":["west_south_ws_palestinehistory","west_south_ws_ploformation"],"selectedBranch":false,"x":1075.125,"y":827},{"id":"ws-palestine-declaration","from":["ws-plo"],"to":["palestine"],"type":"continuation","label":"Palestine proclaimed","dates":"15 November 1988","summary":"The Palestine National Council proclaimed the State of Palestine, acknowledged by the UN General Assembly.","note":"Declaration and diplomatic recognition did not establish full territorial sovereignty or end occupation.","sources":["west_south_ws_palestinedeclaration"],"selectedBranch":false,"x":917.125,"y":1247},{"id":"ws-oslo-recognition","from":["israel"],"to":["ws-plo"],"type":"contact","label":"Mutual recognition & Oslo","dates":"1993","summary":"Israel and the PLO exchanged recognition and signed interim self-government arrangements.","note":"The accords did not settle final borders or create a sovereign Palestinian state.","sources":["west_south_ws_palestinehistory"],"selectedBranch":false,"x":827.125,"y":967}],"autoLayout":true,"continuations":[{"map":"ottoman-arab-states","history":"ottoman","label":"Ottoman lands & Arab states"},{"map":"seljuqs-anatolia","history":"ottoman","label":"Seljuqs, Anatolia & Iran"}],"width":1600,"height":1764},{"id":"south-asia-early-medieval","title":"South Asia: early & medieval","region":"southasia","nodes":[{"id":"indus","x":402.4,"y":220},{"id":"sumer","x":265.4,"y":500},{"id":"vedic","x":540.4,"y":500},{"id":"mahajanapadas","x":540.4,"y":780},{"id":"maurya","x":540.4,"y":1060},{"id":"cn-seleucid","x":403.4,"y":1340},{"id":"post-mauryan","x":678.4,"y":1340},{"id":"kushan","x":678.4,"y":1620},{"id":"gupta","x":678.4,"y":1900},{"id":"post-gupta","x":678.4,"y":2180},{"id":"harsha","x":678.4,"y":2460},{"id":"tang","x":541.4,"y":2740},{"id":"india-regional-kingdoms","x":816.4,"y":2740},{"id":"chola","x":677.4,"y":3020},{"id":"srivijaya","x":677.4,"y":3300},{"id":"delhi","x":952.4000000000001,"y":3020},{"id":"vijayanagara","x":952.4000000000001,"y":3300},{"id":"mughal","x":1051.4,"y":3860},{"id":"ws-deccan-sultanates","x":956.4000000000001,"y":3580}],"connections":[{"id":"ws-indus-sumer","from":["indus"],"to":["sumer"],"type":"contact","label":"Long-distance trade","dates":"3rd millennium BC","summary":"Indus and Mesopotamian societies participated in long-distance exchange networks.","note":"Trade links do not establish political union or population identity.","sources":["west_south_ws_mesoearly"],"selectedBranch":false,"x":391.4,"y":407},{"id":"ws-indus-vedic","from":["indus"],"to":["vedic"],"type":"contact","label":"Overlapping transformations","dates":"c. 1900–1300 BC","summary":"Late Harappan communities overlapped with changing Indo-Gangetic cultural landscapes.","note":"This is not a conquest or simple Harappan-to-Vedic state succession; language and identity remain research questions.","sources":["west_south_ws_vedic","west_south_ws_indusclimate"],"selectedBranch":false,"x":647.4,"y":407},{"id":"ws-vedic-states","from":["vedic"],"to":["mahajanapadas"],"type":"continuation","label":"Later regional states","dates":"1st millennium BC","summary":"Later Vedic textual traditions developed alongside the emergence of regional states in northern South Asia.","note":"Culture, texts, and states have different chronologies; there was no single Vedic empire.","sources":["west_south_ws_vedic","west_south_ws_maurya"],"selectedBranch":false,"x":654.4,"y":687},{"id":"ws-mahajanapadas-maurya","from":["mahajanapadas"],"to":["maurya"],"type":"conquest","label":"Magadhan consolidation","dates":"4th century BC","summary":"The Magadhan political core of the mahājanapadas was incorporated into the Mauryan imperial project.","note":"Not every mahājanapada survived until, or was conquered by, the Mauryas in the same way.","sources":["west_south_ws_maurya"],"selectedBranch":false,"x":654.4,"y":967},{"id":"ws-maurya-seleucid","from":["maurya"],"to":["cn-seleucid"],"type":"contact","label":"Treaty & frontier","dates":"c. 305–303 BC","summary":"Chandragupta Maurya and Seleucus established a negotiated frontier after conflict.","note":"A selected interstate encounter, not the descent of one empire from the other.","sources":["west_south_ws_maurya"],"selectedBranch":false,"x":550.4,"y":1247},{"id":"ws-maurya-regional","from":["maurya"],"to":["post-mauryan"],"type":"division","label":"Regional dynasties","dates":"after c. 185 BC","summary":"After Mauryan power ended, numerous regional dynasties governed different parts of South Asia.","note":"The endpoint is a modern grouping, not one successor kingdom.","sources":["west_south_ws_maurya","west_south_ws_kushan"],"selectedBranch":true,"x":775.4,"y":1247},{"id":"ws-postmaurya-kushan","from":["post-mauryan"],"to":["kushan"],"type":"contact","label":"Northwestern imperial setting","dates":"1st–3rd centuries AD","summary":"Kushan power formed one important part of the diverse post-Mauryan political landscape.","note":"An umbrella-to-member context link, not a single dynasty changing its name.","sources":["west_south_ws_kushan"],"selectedBranch":false,"x":792.4,"y":1527},{"id":"ws-kushan-gupta","from":["kushan"],"to":["gupta"],"type":"continuation","label":"Changing northern powers","dates":"3rd–4th centuries AD","summary":"As Kushan power contracted, Gupta rulers consolidated parts of northern India.","note":"Regional successors and intervening rulers existed; there was no wholesale handover of all Kushan lands.","sources":["west_south_ws_kushangupta"],"selectedBranch":false,"x":792.4,"y":1807},{"id":"ws-gupta-breakup","from":["gupta"],"to":["post-gupta"],"type":"division","label":"Regional rule expands","dates":"5th–6th centuries AD","summary":"Gupta power fragmented as invasions and regional autonomy reshaped northern India.","note":"The post-Gupta label groups different kingdoms rather than one political successor.","sources":["west_south_ws_postgupta"],"selectedBranch":true,"x":792.4,"y":2087},{"id":"ws-harsha-postgupta","from":["post-gupta"],"to":["harsha"],"type":"contact","label":"Harsha’s northern realm","dates":"606–647 AD","summary":"Harsha’s kingdom was one major polity within the wider post-Gupta landscape.","note":"It did not reunite all former Gupta territories or govern all South Asia.","sources":["west_south_ws_postgupta"],"selectedBranch":false,"x":792.4,"y":2367},{"id":"ws-harsha-tang","from":["harsha"],"to":["tang"],"type":"contact","label":"Diplomatic missions","dates":"7th century AD","summary":"Harsha exchanged diplomatic missions with Tang China.","note":"Diplomatic contact is not territorial continuity.","sources":["west_south_ws_postgupta"],"selectedBranch":false,"x":690.4,"y":2647},{"id":"ws-harsha-regional","from":["harsha"],"to":["india-regional-kingdoms"],"type":"division","label":"Regional courts","dates":"after 647 AD","summary":"Following Harsha’s death, northern power again rested with multiple regional courts.","note":"Many kingdoms already existed beyond his control; this umbrella spans the wider subcontinent.","sources":["west_south_ws_postgupta"],"selectedBranch":true,"x":912.4,"y":2647},{"id":"ws-regional-chola","from":["india-regional-kingdoms"],"to":["chola"],"type":"contact","label":"Southern imperial center","dates":"9th–13th centuries AD","summary":"The Cholas rose within a competitive southern landscape of regional dynasties.","note":"They were not the sole successors to northern post-Gupta kingdoms.","sources":["west_south_ws_southmedieval","west_south_ws_chola"],"selectedBranch":false,"x":796.4,"y":2927},{"id":"ws-chola-srivijaya","from":["chola"],"to":["srivijaya"],"type":"conquest","label":"Maritime raids","dates":"1025 AD","summary":"Chola naval forces attacked Srivijayan ports and centers in Southeast Asia.","note":"A campaign did not create permanent Chola rule over the whole Srivijayan maritime world.","sources":["west_south_ws_cholaregion"],"selectedBranch":false,"x":791.4,"y":3207},{"id":"ws-regional-delhi","from":["india-regional-kingdoms"],"to":["delhi"],"type":"conquest","label":"Northern sultanate expands","dates":"late 12th–13th centuries","summary":"Conquest and consolidation established Delhi sultanate rule across parts of northern India.","note":"Many regional kingdoms survived; this was not the end of all pre-existing South Asian states.","sources":["west_south_ws_northmedieval"],"selectedBranch":false,"x":1063.4,"y":2927},{"id":"ws-delhi-vijayanagara","from":["delhi"],"to":["vijayanagara"],"type":"contact","label":"Deccan political setting","dates":"14th century AD","summary":"Vijayanagara emerged amid Delhi’s southern campaigns and a changing Deccan political landscape.","note":"This is regional context, not a claim that Vijayanagara was simply a renamed Delhi province.","sources":["west_south_ws_chola"],"selectedBranch":false,"x":1066.4,"y":3207},{"id":"ws-delhi-mughal","from":["delhi"],"to":["mughal"],"type":"conquest","label":"Babur’s victory","dates":"1526","summary":"Babur defeated the Lodi ruler at Panipat and established Mughal rule in northern India.","note":"Mughal consolidation was prolonged and interrupted by Sur rule.","sources":["west_south_ws_mughal"],"selectedBranch":false,"x":1263.4,"y":3487},{"id":"ws-vijayanagara-talikota","from":["vijayanagara"],"to":["ws-deccan-sultanates"],"type":"conquest","label":"Battle of Talikota","dates":"1565","summary":"A coalition of Deccan sultanates defeated Vijayanagara and devastated its capital.","note":"The Vijayanagara dynasty continued from other capitals after 1565.","sources":["west_south_ws_vijayanagara"],"selectedBranch":false,"x":1062.4,"y":3487},{"id":"ws-deccan-mughal","from":["ws-deccan-sultanates"],"to":["mughal"],"type":"conquest","label":"Mughal annexations","dates":"17th century AD","summary":"Mughal campaigns absorbed major Deccan sultanates, culminating in the late 1680s.","note":"Different sultanates ended at different dates; this is a grouped regional account.","sources":["west_south_ws_vijayanagara"],"selectedBranch":false,"x":1088.4,"y":3767}],"autoLayout":true,"continuations":[{"map":"south-asia","history":"mughal","label":"South Asia: empire, company & partition"},{"map":"southeast-maritime","history":"tang","label":"Maritime Southeast Asia · encounters and independence"}],"width":1600,"height":4284},{"id":"afghanistan-regional-powers","title":"Afghanistan & regional powers","region":"southasia","nodes":[{"id":"afsharid","x":411,"y":220},{"id":"ws-durrani","x":411,"y":500},{"id":"ws-barakzai","x":686,"y":780},{"id":"companyindia","x":686,"y":500},{"id":"britishraj","x":961,"y":500},{"id":"ws-afghanistan-later","x":686,"y":1060}],"connections":[{"id":"ws-afsharid-durrani","from":["afsharid"],"to":["ws-durrani"],"type":"independence","label":"Durrani state emerges","dates":"1747","summary":"Ahmad Shah Durrani established a realm after Nader Shah’s death.","note":"Afsharid fragmentation produced several regional powers.","sources":["west_south_ws_afghancrs"],"selectedBranch":false,"x":525,"y":407},{"id":"ws-durrani-barakzai","from":["ws-durrani"],"to":["ws-barakzai"],"type":"continuation","label":"Dost Mohammad in Kabul","dates":"1826","summary":"Dost Mohammad consolidated Barakzai rule in Kabul after Durrani fragmentation.","note":"Regional rivals and later Durrani restoration complicate a simple dynasty-to-dynasty chain.","sources":["west_south_ws_afghancrs"],"selectedBranch":false,"x":542,"y":687},{"id":"ws-company-afghan","from":["companyindia"],"to":["ws-barakzai"],"type":"conquest","label":"First Anglo-Afghan War","dates":"1839–1842","summary":"British forces deposed Dost Mohammad and restored a Durrani ruler, then withdrew.","note":"Dost Mohammad subsequently returned to power.","sources":["west_south_ws_afghancrs"],"selectedBranch":false,"x":800,"y":687},{"id":"ws-raj-afghan-independence","from":["britishraj"],"to":["ws-barakzai"],"type":"independence","label":"Foreign-policy independence","dates":"1919","summary":"The Treaty of Rawalpindi recognized Afghanistan’s full foreign-policy independence after war.","note":"Afghanistan had not been an annexed province of British India.","sources":["west_south_ws_afghan1919"],"selectedBranch":false,"x":1068,"y":687},{"id":"ws-afghan-republic","from":["ws-barakzai"],"to":["ws-afghanistan-later"],"type":"continuation","label":"Monarchy overthrown","dates":"1973","summary":"Daoud overthrew the monarchy and proclaimed a republic.","note":"The endpoint groups subsequent governments; it is not one unchanged republican regime.","sources":["west_south_ws_afghancrs"],"selectedBranch":false,"x":800,"y":967}],"autoLayout":true,"continuations":[{"map":"south-asia","history":"companyindia","label":"South Asia: empire, company & partition"}],"width":1600,"height":1484}];
const CONNECTION_EXTRAS=[{"id":"cn-ireland","title":"Kingdom of Ireland","region":"europe","dates":"1541–1801 AD","wikiTitle":"Kingdom of Ireland","location":"Ireland","note":"A kingdom sharing a monarch with England and later Great Britain. The map’s union event concerns 1801, not the origin of Ireland.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_union1801","wikipedia_cn-ireland"],"graphOnly":true},{"id":"cn-irishfree","title":"Irish Free State","region":"europe","dates":"1922–1937 AD","wikiTitle":"Irish Free State","location":"Ireland","note":"Created as a dominion in 1922. Northern Ireland remained in the UK. A new constitution followed in 1937; the later Republic of Ireland is a further constitutional development.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_irish1922","wikipedia_cn-irishfree"],"graphOnly":true},{"id":"cn-britishnorth","title":"British northern colonies · pre-Confederation","region":"americas","dates":"1763–1867 AD · selected frame","wikiTitle":"British North America","location":"Northern North America","note":"This collective frame includes British Canada after 1763 and the colonies usually grouped as British North America after 1783. It was not one sovereign state. Confederation initially joined only some colonies; other territories entered Canada later.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_canadaHistory","connection_canada1867","wikipedia_cn-britishnorth"],"graphOnly":true},{"id":"cn-romanempire","title":"Roman Empire · shared imperial frame","region":"europe","dates":"27 BC–395 AD · selected frame","wikiTitle":"Roman Empire","location":"Mediterranean and adjoining regions","note":"This node provides a common imperial frame before the 395 division. Earlier partitions and reunifications occurred; the eastern state continued as Roman, rather than becoming a new people.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_roman","wikipedia_cn-romanempire"],"graphOnly":true},{"id":"cn-westrome","title":"Western Roman Empire · late phase","region":"europe","dates":"395–476 AD · selected phase","wikiTitle":"Western Roman Empire","location":"Western Mediterranean and Europe","note":"The selected late phase follows the 395 division of imperial courts. Roman institutions and communities did not disappear in 476.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_roman","wikipedia_cn-westrome"],"graphOnly":true},{"id":"cn-westfrancia","title":"West Francia","region":"europe","dates":"843–987 AD · selected frame","wikiTitle":"West Francia","location":"Western Europe","note":"A kingdom created by the partition of 843. The Capetian accession in 987 is a dynastic convention, not an instant creation of French society.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_carolingian","wikipedia_cn-westfrancia"],"graphOnly":true},{"id":"cn-middlefrancia","title":"Middle Francia","region":"europe","dates":"843–855 AD","wikiTitle":"Middle Francia","location":"Central strip of the former Carolingian realm","note":"Lothair I’s realm after Verdun included lands from the Low Countries to Italy. Further partitions followed in 855.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_carolingian","wikipedia_cn-middlefrancia"],"graphOnly":true},{"id":"cn-eastfrancia","title":"East Francia","region":"europe","dates":"843–962 AD · selected frame","wikiTitle":"East Francia","location":"Central Europe","note":"The map selects the kingdom before Otto I’s imperial coronation. The kingdom and later empire developed through successive changes.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_carolingian","wikipedia_cn-eastfrancia"],"graphOnly":true},{"id":"cn-alexander","title":"Alexander’s empire","region":"europe","dates":"334–323 BC · conquest phase","wikiTitle":"Empire of Alexander the Great","location":"Macedonia and conquered territories across West Asia","note":"This selects the period of expansion into the Achaemenid realm. Alexander became king in 336 BC; successor kingdoms emerged through prolonged wars after his death.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_iranAncient","wikipedia_cn-alexander"],"graphOnly":true},{"id":"cn-seleucid","title":"Seleucid Empire","region":"westasia","dates":"312–63 BC","wikiTitle":"Seleucid Empire","location":"West Asia and changing eastern territories","note":"One of several Hellenistic successor kingdoms. Its territory contracted over time, and it did not encompass all of Alexander’s former realm.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_parthian","wikipedia_cn-seleucid"],"graphOnly":true},{"id":"cn-ptolemaic","title":"Ptolemaic Kingdom","region":"africa","dates":"305–30 BC","wikiTitle":"Ptolemaic Kingdom","location":"Egypt and changing adjoining territories","note":"A Hellenistic kingdom based in Egypt. The royal title dates to 305 BC; Ptolemy had governed Egypt earlier.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_ptolemaic","wikipedia_cn-ptolemaic"],"graphOnly":true},{"id":"cn-parthian","title":"Parthian Empire","region":"westasia","dates":"247 BC–224 AD","wikiTitle":"Parthian Empire","location":"Iran and Mesopotamia","note":"Parthian rulers expanded gradually into Seleucid-held territories and were later overthrown by the Sasanians.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_parthian","wikipedia_cn-parthian"],"graphOnly":true},{"id":"cn-ilkhanate","title":"Ilkhanate","region":"westasia","dates":"1256–1335 AD · united dynasty","wikiTitle":"Ilkhanate","location":"Iran, Iraq and adjoining territories","note":"A regional Mongol khanate. The united dynasty fragmented in 1335; later claimants and successor states continued. Some art chronologies extend to 1353.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_ilkhanid","wikipedia_cn-ilkhanate"],"graphOnly":true},{"id":"cn-goldenhorde","title":"Golden Horde","region":"europe","dates":"13th century–1502 AD","wikiTitle":"Golden Horde","location":"Western Eurasian steppe","note":"A regional Mongol realm developing from the Jochid appanage. Its formation was gradual, and later successor khanates had separate histories.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_mongols","wikipedia_cn-goldenhorde"],"graphOnly":true},{"id":"cn-chagatai","title":"Chagatai Khanate","region":"eastasia","dates":"13th–14th centuries · early phase","wikiTitle":"Chagatai Khanate","location":"Central Asia","note":"The early khanate later divided into western and eastern political formations. This map does not date the end of all Chagataid lineages.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_mongols","wikipedia_cn-chagatai"],"graphOnly":true},{"id":"cn-saadi","title":"Saadi Morocco","region":"africa","dates":"16th–17th centuries AD","wikiTitle":"Saadi Sultanate","location":"Morocco","note":"A dynastic frame for the Moroccan force behind the 1591 invasion. It was not a successor state encompassing all Songhai territory.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_songhai1591","wikipedia_cn-saadi"],"graphOnly":true},{"id":"cn-castile","title":"Crown of Castile","region":"europe","dates":"1230–1715 AD","wikiTitle":"Crown of Castile","location":"Iberian Peninsula and overseas territories","note":"Its institutions remained distinct after the dynastic union with Aragon. Later centralisation occurred in stages.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_spainunion","wikipedia_cn-castile"],"graphOnly":true},{"id":"cn-aragon","title":"Crown of Aragon","region":"europe","dates":"1162–1716 AD","wikiTitle":"Crown of Aragon","location":"Eastern Iberia and Mediterranean territories","note":"A composite crown whose territories retained distinct laws and institutions after the union of rulers with Castile.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_spainunion","wikipedia_cn-aragon"],"graphOnly":true},{"id":"cn-portugal","title":"Kingdom of Portugal","region":"europe","dates":"1139–1910 AD","wikiTitle":"Kingdom of Portugal","location":"Portugal and overseas territories","note":"A long political frame with dynastic and constitutional changes, including the Iberian Union of 1580–1640. The colonial link shown here is a selected episode.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_brazil","wikipedia_cn-portugal"],"graphOnly":true},{"id":"cn-grancolombia","title":"Gran Colombia","region":"americas","dates":"1819–1831 AD","wikiTitle":"Gran Colombia","location":"Northern South America and Panama","note":"A republic formed during independence struggles. Territorial liberation and integration occurred in stages; the union dissolved in 1830–1831.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_ecuador","connection_venezuela","connection_newgranada","wikipedia_cn-grancolombia"],"graphOnly":true},{"id":"cn-newgranada","title":"Republic of New Granada","region":"americas","dates":"1831–1858 AD","wikiTitle":"Republic of New Granada","location":"Present-day Colombia and Panama","note":"One successor to Gran Colombia. Later constitutional forms and the separation of Panama in 1903 are distinct developments.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_newgranada","wikipedia_cn-newgranada"],"graphOnly":true},{"id":"cn-venezuela","title":"Venezuela · separate republic","region":"americas","dates":"From 1830 AD","wikiTitle":"Venezuela","location":"Northern South America","note":"The map anchors this political frame in separation from Gran Colombia. Earlier independence declarations, changing regimes and territory have their own histories.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_venezuela","wikipedia_cn-venezuela"],"graphOnly":true},{"id":"cn-ecuador","title":"Ecuador · separate republic","region":"americas","dates":"From 1830 AD","wikiTitle":"Ecuador","location":"Northwestern South America","note":"Ecuador withdrew from Gran Colombia in 1830. This does not date the region’s peoples or settle later border disputes.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_ecuador","wikipedia_cn-ecuador"],"graphOnly":true},{"id":"cn-jalayirid","title":"Jalayirid Sultanate","region":"westasia","dates":"1335–1432 AD","wikiTitle":"Jalayirid Sultanate","location":"Iraq and western Iran","note":"One of several powers following Ilkhanid fragmentation. Its territory changed and rulers returned after some conquests; it never inherited the whole Ilkhanate.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_ilkhanid","connection_iranRegional","connection_iran1400","wikipedia_cn-jalayirid"],"graphOnly":true},{"id":"cn-muzaffarid","title":"Muzaffarid dynasty","region":"westasia","dates":"1314–1393 AD","wikiTitle":"Muzaffarids (Iran)","location":"Southern and central Iran","note":"A regional dynasty whose origins predate 1335 and which expanded after Ilkhanid fragmentation. Timur ended its rule; this is only one of the regional powers shown.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_iranRegional","wikipedia_cn-muzaffarid"],"graphOnly":true},{"id":"cn-qaraqoyunlu","title":"Qara Qoyunlu","region":"westasia","dates":"c. 1374–1468 AD","wikiTitle":"Qara Qoyunlu","location":"Iraq, Azerbaijan and western Iran","note":"A Turkoman confederation with a history before and alongside Timurid rule. The map concerns expansion into selected Jalayirid and western Timurid territories.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_iran1400","wikipedia_cn-qaraqoyunlu"],"graphOnly":true},{"id":"cn-aqqoyunlu","title":"Aq Qoyunlu","region":"westasia","dates":"c. 1378–1508 AD","wikiTitle":"Aq Qoyunlu","location":"Eastern Anatolia, Iraq and Iran","note":"A Turkoman confederation whose major Iranian expansion followed victories in 1467–1469. Rival branches continued after the Safavids took Tabriz in 1501.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_iran1400","wikipedia_cn-aqqoyunlu"],"graphOnly":true},{"id":"cn-hotak-iran","title":"Hotak occupation & Safavid claimants","region":"westasia","dates":"1722–1736 AD · crisis frame","wikiTitle":"Siege of Isfahan","location":"Iran","note":"A selected crisis, not one unified dynasty: Hotak forces occupied Isfahan in 1722; Nader expelled them in 1729 and restored a Safavid claimant before taking the throne in 1736.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_iran1600","connection_afsharids","wikipedia_cn-hotak-iran"],"graphOnly":true},{"id":"cn-afsharid-khorasan","title":"Afsharid Khorasan","region":"westasia","dates":"1747–1796 AD · surviving realm","wikiTitle":"Afsharid dynasty","location":"Khorasan, northeastern Iran","note":"After Nader’s death, Afsharid rulers survived in Khorasan while other powers ruled elsewhere. This overlaps with Zand rule and Qajar expansion.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_afsharids","wikipedia_cn-afsharid-khorasan"],"graphOnly":true},{"id":"cn-zand","title":"Zand Iran","region":"westasia","dates":"1751–1794 AD","wikiTitle":"Zand dynasty","location":"Western and southern Iran","note":"Karim Khan and later Zand rulers controlled much of Iran, while Khorasan remained outside their rule. Qajars defeated the last Zand ruler in 1794.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_zand","connection_zandArchive","wikipedia_cn-zand"],"graphOnly":true},{"id":"cn-ireland-modern","title":"Ireland · constitutional state","region":"europe","dates":"1937 AD–present · selected frame","wikiTitle":"Republic of Ireland","location":"Ireland","note":"The 1937 constitution replaced the Free State constitution and named the state Ireland. The Republic of Ireland description took effect in 1949. Northern Ireland remained in the UK.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_ireland1937","connection_irish1922","wikipedia_cn-ireland-modern"],"graphOnly":true},{"id":"cn-northgerman","title":"North German Confederation","region":"europe","dates":"1867–1871 AD","wikiTitle":"North German Confederation","location":"Northern and central Europe","note":"A Prussia-led federal state established after the 1866 war and dissolution of the older German Confederation. Southern states joined the enlarged empire in 1871; Austria was excluded.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_german1871","wikipedia_cn-northgerman"],"graphOnly":true},{"id":"cn-granadine","title":"Granadine Confederation","region":"americas","dates":"1858–1863 AD","wikiTitle":"Granadine Confederation","location":"Present-day Colombia and Panama","note":"A federal constitutional framework after New Granada. Civil war and transitional names preceded the 1863 constitution.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_colombiaFederal","wikipedia_cn-granadine"],"graphOnly":true},{"id":"cn-uscolombia","title":"United States of Colombia","region":"americas","dates":"1863–1886 AD · constitutional frame","wikiTitle":"United States of Colombia","location":"Present-day Colombia and Panama","note":"The 1863 constitution established this federal framework after civil war. The name had been used earlier during the conflict. It was replaced by the centralising 1886 constitution.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_colombiaConstitutions","connection_colombiaFederal","wikipedia_cn-uscolombia"],"graphOnly":true},{"id":"cn-colombia","title":"Colombia · 1886 and later eras","region":"americas","dates":"1886 AD–present · selected frame","wikiTitle":"Colombia","location":"Northern South America","note":"The name Republic of Colombia was restored in the 1886 constitution. Modern Colombia has earlier state histories, later reforms including the 1991 constitution, and a changed border following Panama’s separation.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_colombiaConstitutions","connection_panama1903","wikipedia_cn-colombia"],"graphOnly":true},{"id":"cn-panama","title":"Panama · independent republic","region":"americas","dates":"1903 AD–present","wikiTitle":"Panama","location":"Central America","note":"Panama separated from Colombia in November 1903 amid US involvement and canal negotiations. This does not date the beginning of Panamanian communities or regional identities.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_panama1903","wikipedia_cn-panama"],"graphOnly":true},{"id":"cn-sahel-regional","title":"Bamana, Massina & Toucouleur realms","region":"africa","dates":"17th–19th centuries · selected regional frame","wikiTitle":"History of Mali","location":"Upper and middle Niger regions","note":"Several different states and communities occupied parts of regions formerly within Mali or Songhai. This collective frame does not imply one continuous state or identical boundaries.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_maliProfile","wikipedia_cn-sahel-regional"],"graphOnly":true},{"id":"cn-frenchsudan","title":"French Sudan / Sudanese Republic","region":"africa","dates":"c. 1890–1959 AD · changing colonial forms","wikiTitle":"French Sudan","location":"Present-day Mali and changing adjoining territories","note":"French conquest and colonial reorganisation occurred in stages and met resistance. This selected frame ends with the Mali Federation; colonial borders did not match medieval empires.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_maliProfile","wikipedia_cn-frenchsudan"],"graphOnly":true},{"id":"cn-mali-federation","title":"Mali Federation","region":"africa","dates":"1959–1960 AD","wikiTitle":"Mali Federation","location":"Senegal and the Sudanese Republic","note":"A short-lived federation of Senegal and the Sudanese Republic, independent from France on 20 June 1960. It broke apart later that year.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_federation1960","connection_mali1960","wikipedia_cn-mali-federation"],"graphOnly":true},{"id":"cn-mali-modern","title":"Mali · independent state","region":"africa","dates":"1960 AD–present","wikiTitle":"Mali","location":"West Africa","note":"The Sudanese Republic adopted the name Republic of Mali in September 1960 after the federation dissolved. It is not the medieval Mali Empire restored or the whole former Songhai realm.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_mali1960","wikipedia_cn-mali-modern"],"graphOnly":true},{"id":"cn-senegal","title":"Senegal · independent state","region":"africa","dates":"1960 AD–present","wikiTitle":"Senegal","location":"West Africa","note":"Senegal left the Mali Federation in August 1960. Its earlier histories and colonial borders differ from those of medieval Sahelian empires.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_mali1960","wikipedia_cn-senegal"],"graphOnly":true},{"id":"cn-nigeriasouth","title":"Southern Nigerian colonial jurisdictions","region":"africa","dates":"1897–1914 AD · selected frame","wikiTitle":"Southern Nigeria Protectorate","location":"Southern parts of present-day Nigeria","note":"This selected frame begins with the invasion of Benin in 1897, before the Southern Nigeria Protectorate was established in 1900. Niger Coast, Lagos and Southern Nigeria administrations changed before 1914.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_benin1897","connection_nigeriaProfile","wikipedia_cn-nigeriasouth"],"graphOnly":true},{"id":"cn-nigerianorth","title":"Northern Nigeria Protectorate","region":"africa","dates":"1900–1914 AD","wikiTitle":"Northern Nigeria Protectorate","location":"Northern parts of present-day Nigeria","note":"British rule expanded through conquest and agreements. The protectorate included only part of the wider Lake Chad region; Kanuri communities and institutions continued across colonial borders.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_nigeriaProfile","wikipedia_cn-nigerianorth"],"graphOnly":true},{"id":"cn-colonial-nigeria","title":"Colonial Nigeria","region":"africa","dates":"1914–1960 AD","wikiTitle":"Colonial Nigeria","location":"Present-day Nigeria and changing adjoining territories","note":"British administrators amalgamated northern and southern jurisdictions in 1914. This joined many peoples and political traditions, rather than being a merger only of Benin and Bornu.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_nigeria1914","connection_nigeria1960","wikipedia_cn-colonial-nigeria"],"graphOnly":true},{"id":"cn-kazan","title":"Khanate of Kazan","region":"europe","dates":"c. 1438–1552 AD","wikiTitle":"Khanate of Kazan","location":"Volga region","note":"One of several khanates formed in the fragmentation of the Golden Horde. Muscovite conquest in 1552 ended its government; Tatar communities and traditions continued.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_hordeSuccessors","connection_kazan1552","wikipedia_cn-kazan"],"graphOnly":true},{"id":"cn-greathorde","title":"Great Horde","region":"europe","dates":"15th century–1502 AD","wikiTitle":"Great Horde","location":"Lower Volga and Eurasian steppe","note":"A later Jochid political formation claiming the central Horde inheritance. It coexisted and competed with other khanates; it did not represent all post-Horde societies.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_hordeSuccessors","connection_ugra1480","wikipedia_cn-greathorde"],"graphOnly":true},{"id":"cn-muscovy","title":"Grand Principality of Moscow","region":"europe","dates":"c. 1263–1547 AD","wikiTitle":"Grand Principality of Moscow","location":"Northeastern Europe","note":"A separate principality that developed under Horde tributary supremacy and expanded over neighbouring principalities. Ending tribute did not mean the Golden Horde was renamed Russia.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_ugra1480","connection_russiaStudy","wikipedia_cn-muscovy"],"graphOnly":true},{"id":"cn-tsardom","title":"Tsardom of Russia","region":"europe","dates":"1547–1721 AD","wikiTitle":"Tsardom of Russia","location":"Changing territories across northeastern Europe and northern Asia","note":"Ivan IV adopted the tsar’s title in 1547. Territorial conquest and state expansion continued; Peter’s imperial title in 1721 marks the next frame.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_russianTitles","wikipedia_cn-tsardom"],"graphOnly":true},{"id":"cn-ukraine","title":"Ukraine · independent state","region":"europe","dates":"1991 AD–present","wikiTitle":"Ukraine","location":"Eastern Europe","note":"Ukraine declared independence in August 1991, confirmed by a December referendum. Its peoples and political histories predate Soviet rule; this node does not make contemporary territorial claims.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_ussr1991","wikipedia_cn-ukraine"],"graphOnly":true},{"id":"cn-kazakhstan","title":"Kazakhstan · independent state","region":"eastasia","dates":"1991 AD–present","wikiTitle":"Kazakhstan","location":"Central Asia","note":"Kazakhstan became independent in December 1991. Earlier Kazakh polities and societies are not represented as beginning with Soviet dissolution.","summary":"","status":"Selected frame","type":"Connection-map node","sources":["connection_ussr1991","wikipedia_cn-kazakhstan"],"graphOnly":true},{"id":"afsu-nobatia","title":"Nobatia","region":"africa","dates":"c. 4th–8th centuries AD · independent kingdom","wikiTitle":"Nobatia","location":"Lower Nubia; southern Egypt and northern Sudan","note":"Christianised in the sixth century; later governed with Makuria while retaining a distinctive regional administration. Exact dates and circumstances of union are uncertain.","sources":["connection_africa_sudan_afsu_medieval","wikipedia_afsu-nobatia"],"graphOnly":true},{"id":"afsu-makuria","title":"Makuria","region":"africa","dates":"c. 5th–15th centuries AD · changing authority","wikiTitle":"Makuria","location":"Middle Nile; capital at Old Dongola","note":"Christian Nubian kingdom with changing territorial reach and late fragmentation; its chronology is not the lifetime of all Nubian communities.","sources":["connection_africa_sudan_afsu_medieval","wikipedia_afsu-makuria"],"graphOnly":true},{"id":"afsu-alodia","title":"Alodia / Alwa","region":"africa","dates":"c. 6th century–c. 1500 AD · ending disputed","wikiTitle":"Alodia","location":"Blue and White Nile region; capital at Soba","note":"Christian Nubian kingdom distinct from Makuria. Late chronicles associate Soba’s destruction with 1504, while archaeology indicates much earlier decline in excavated areas; a precise end date is uncertain.","sources":["connection_africa_sudan_afsu_soba","wikipedia_afsu-alodia"],"graphOnly":true},{"id":"afsu-funj","title":"Funj Sultanate of Sennar","region":"africa","dates":"c. 1500–1821 AD","wikiTitle":"Funj Sultanate","location":"Middle Nile and Blue Nile; changing dominions","note":"A regional sultanate conventionally dated from 1504. It incorporated diverse communities and territories and was not a restored, unchanged Alodian monarchy or all of modern Sudan.","sources":["connection_africa_sudan_afsu_funj","connection_africa_sudan_afsu_funj_origins","wikipedia_afsu-funj"],"graphOnly":true},{"id":"afsu-turcoegyptian","title":"Turco-Egyptian Sudan","region":"africa","dates":"1820/1821–1885 AD · expanding colonial control","wikiTitle":"Turco-Egyptian Sudan","location":"Sudanese territories ruled from Egypt; frontiers changed","note":"Muhammad Ali’s conquest began in 1820, ending Funj rule in 1821. Egyptian government expanded unevenly into other regions; this did not constitute simultaneous control of every part of today’s Sudan and South Sudan.","sources":["connection_africa_sudan_afsu_funj","connection_africa_sudan_afsu_egyptsudan","connection_africa_sudan_afsu_condominium","wikipedia_afsu-turcoegyptian"],"graphOnly":true},{"id":"afsu-mahdist","title":"Mahdist State","region":"africa","dates":"1881–1899 AD · movement and state","wikiTitle":"Mahdist State","location":"Sudan; capital at Omdurman","note":"The movement began in 1881 and captured Khartoum in 1885. Omdurman fell in 1898; the Khalifa was defeated and killed in 1899. The stages should not be collapsed into a single founding or ending day.","sources":["connection_africa_sudan_afsu_egyptsudan","wikipedia_afsu-mahdist"],"graphOnly":true},{"id":"afsu-condominium","title":"Anglo-Egyptian Sudan","region":"africa","dates":"1899–1956 AD","wikiTitle":"Anglo-Egyptian Sudan","location":"Territories of present-day Sudan and South Sudan, with changing boundaries","note":"The 1899 agreements established nominal joint British and Egyptian authority, with British officials dominant in administration. Colonial borders and institutions differed from those of preceding kingdoms.","sources":["connection_africa_sudan_afsu_condominium","connection_africa_sudan_afsu_independence","wikipedia_afsu-condominium"],"graphOnly":true},{"id":"afsu-sudan","title":"Sudan: independent eras","region":"africa","dates":"1956 AD–present","wikiTitle":"Sudan","location":"Northeastern Africa; territorial separation in 2011","note":"An overview of successive governments and conflicts following independence, not one unchanged regime. South Sudan became independent in 2011; Sudan continued as a state. Ancient Nubian kingdoms were not coterminous with this modern country.","sources":["connection_africa_sudan_afsu_independence","connection_africa_sudan_afsu_southsudan","wikipedia_afsu-sudan"],"graphOnly":true},{"id":"afsu-southsudan","title":"South Sudan: independent state","region":"africa","dates":"2011 AD–present","wikiTitle":"South Sudan","location":"East-Central Africa","note":"Independence on 9 July 2011 followed a January referendum under the 2005 peace settlement. This date marks a modern state, not the beginning of the histories of its many peoples.","sources":["connection_africa_sudan_afsu_southsudan","wikipedia_afsu-southsudan"],"graphOnly":true},{"id":"af-egypt-regional","title":"Egypt: Tulunid, Abbasid and Ikhshidid governments","region":"africa","dates":"868–969 AD · changing governments","wikiTitle":"Egypt in the Middle Ages","location":"Egypt and, at times, neighbouring lands","note":"An explicitly grouped transition frame: Tulunids 868–905, restored direct Abbasid government 905–935, and Ikhshidids 935–969; this is not one dynasty.","sources":["connection_africa_af_egypt500","wikipedia_af-egypt-regional"],"graphOnly":true},{"id":"af-zagwe","title":"Zagwe dynasty","region":"africa","dates":"c. 11th century–1270 AD","wikiTitle":"Zagwe dynasty","location":"Ethiopian highlands","note":"The dynasty’s origins and exact founding date remain uncertain. Christian traditions connect this period with Aksumite and later Ethiopian histories, without establishing an uninterrupted royal genealogy.","sources":["connection_africa_af_ethiopianchristian","connection_africa_af_zagwe","wikipedia_af-zagwe"],"graphOnly":true},{"id":"af-ethiopia-republican","title":"Ethiopia: post-monarchical eras","region":"africa","dates":"1974 AD–present","wikiTitle":"History of Ethiopia","location":"Horn of Africa","note":"This groups the Derg, subsequent transitional government and later federal republic. These are different regimes and constitutional orders, not one government lasting from 1974.","sources":["connection_africa_af_ethiopia1974","wikipedia_af-ethiopia-republican"],"graphOnly":true},{"id":"af-eritrea","title":"Eritrea: independent state","region":"africa","dates":"1993 AD–present","wikiTitle":"Eritrea","location":"Horn of Africa","note":"Independence followed a long war, military victory in 1991 and the 1993 referendum. The modern border is not a boundary inherited unchanged from Aksum.","sources":["connection_africa_af_eritrea","wikipedia_af-eritrea"],"graphOnly":true},{"id":"af-zanzibar-coast","title":"Omani and Zanzibar coastal rule","region":"africa","dates":"18th–20th centuries · changing coastal authority","wikiTitle":"Sultanate of Zanzibar","location":"Western Indian Ocean and selected East African coastal ports","note":"A regional frame for changing Omani and Zanzibar authority, not a single state covering every Swahili settlement. The independent Zanzibar sultanate dates from the nineteenth century.","sources":["connection_africa_af_kilwaoman","connection_africa_af_kenyacoast","wikipedia_af-zanzibar-coast"],"graphOnly":true},{"id":"af-german-eastafrica","title":"German East Africa","region":"africa","dates":"1885–1918 AD","wikiTitle":"German East Africa","location":"Mainland Tanzania, Rwanda and Burundi, with changing frontiers","note":"German claims began in 1885, and conquest and administrative control developed later. The territory was divided after World War I.","sources":["connection_africa_af_tanganyikareport","connection_africa_af_eastafricapartition","wikipedia_af-german-eastafrica"],"graphOnly":true},{"id":"af-tanganyika-territory","title":"Tanganyika under British administration","region":"africa","dates":"1919–1961 AD","wikiTitle":"Tanganyika Territory","location":"Mainland Tanzania","note":"British occupation was followed by a League of Nations mandate and UN trust territory; 1919 is a transition anchor rather than the date of all legal arrangements.","sources":["connection_africa_af_eastafricapartition","connection_africa_af_unterritories","wikipedia_af-tanganyika-territory"],"graphOnly":true},{"id":"af-tanganyika","title":"Tanganyika: independent state","region":"africa","dates":"1961–1964 AD","wikiTitle":"Tanganyika (1961–1964)","location":"Mainland Tanzania","note":"Independence in 1961 was followed by a republic in 1962 and union with Zanzibar in 1964.","sources":["connection_africa_af_unterritories","connection_africa_af_tanzaniaunion","wikipedia_af-tanganyika"],"graphOnly":true},{"id":"af-zanzibar-independent","title":"Zanzibar: independence and revolution","region":"africa","dates":"1963–1964 AD","wikiTitle":"People's Republic of Zanzibar","location":"Zanzibar and Pemba","note":"Independence under the sultanate in December 1963 was followed by revolution in January 1964 and union in April; these were distinct political stages.","sources":["connection_africa_af_zanzibar1964","wikipedia_af-zanzibar-independent"],"graphOnly":true},{"id":"af-tanzania","title":"United Republic of Tanzania","region":"africa","dates":"1964 AD–present","wikiTitle":"Tanzania","location":"East Africa","note":"Tanganyika and Zanzibar united on 26 April 1964; Zanzibar retained separate institutions within the union.","sources":["connection_africa_af_tanzaniaunion","wikipedia_af-tanzania"],"graphOnly":true},{"id":"af-kenya-colonial","title":"British East Africa and colonial Kenya","region":"africa","dates":"1895–1963 AD","wikiTitle":"British Kenya","location":"Present-day Kenya","note":"A changing colonial frame: protectorate, colony and a legally distinct coastal protectorate; it did not cover every area of British East Africa at all times.","sources":["connection_africa_af_kenya","connection_africa_af_kenyacoast","wikipedia_af-kenya-colonial"],"graphOnly":true},{"id":"af-goldcoast","title":"Gold Coast, Ashanti, Northern Territories and British Togoland","region":"africa","dates":"1902–1957 AD · selected combined frame","wikiTitle":"Gold Coast (British colony)","location":"Present-day Ghana","note":"Four different legal territories were administered in relation to the Gold Coast and were joined at independence. Ashanti was not simply annexed to the Gold Coast Colony in 1902.","sources":["connection_africa_af_ghanaconstitution","connection_africa_af_asante1902","wikipedia_af-goldcoast"],"graphOnly":true},{"id":"af-portuguese-angola","title":"Portuguese Angola","region":"africa","dates":"16th century–1975 AD · changing colonial control","wikiTitle":"Portuguese Angola","location":"Present-day Angola","note":"Portuguese settlement and claims began centuries before effective conquest of many inland regions. The colonial territory was not identical to the former Kingdom of Kongo.","sources":["connection_africa_af_kongocolonial","connection_africa_af_angola","wikipedia_af-portuguese-angola"],"graphOnly":true},{"id":"af-angola","title":"Angola: independent state","region":"africa","dates":"1975 AD–present","wikiTitle":"Angola","location":"Southwestern Africa","note":"Independence on 11 November 1975 came amid conflict among nationalist movements and was followed by civil war. This node does not imply the restoration of the Kingdom of Kongo.","sources":["connection_africa_af_angola","wikipedia_af-angola"],"graphOnly":true},{"id":"af-cape","title":"Cape Colony","region":"africa","dates":"1652–1910 AD · Dutch and British stages","wikiTitle":"Cape Colony","location":"Southern Africa","note":"Dutch settlement began in 1652; British occupation occurred in 1795 and again in 1806. The colony expanded through dispossession, warfare and changing agreements.","sources":["connection_africa_af_southafrica","wikipedia_af-cape"],"graphOnly":true},{"id":"af-natal","title":"Colony of Natal","region":"africa","dates":"1843–1910 AD","wikiTitle":"Colony of Natal","location":"Southern Africa","note":"A British colony preceding the 1910 Union; its borders and political institutions did not represent all communities of the region.","sources":["connection_africa_af_southafricaunion","wikipedia_af-natal"],"graphOnly":true},{"id":"af-transvaal-colony","title":"Transvaal Colony","region":"africa","dates":"1902–1910 AD","wikiTitle":"Transvaal Colony","location":"Southern Africa","note":"British colonial government after conquest of the South African Republic; this node does not date the beginning of societies in the region.","sources":["connection_africa_af_southafricaunion","wikipedia_af-transvaal-colony"],"graphOnly":true},{"id":"af-orange-colony","title":"Orange River Colony","region":"africa","dates":"1902–1910 AD","wikiTitle":"Orange River Colony","location":"Southern Africa","note":"British colonial government following the South African War, before the 1910 Union.","sources":["connection_africa_af_southafricaunion","wikipedia_af-orange-colony"],"graphOnly":true},{"id":"af-southafrica-democratic","title":"South Africa: democratic constitutional era","region":"africa","dates":"1994 AD–present","wikiTitle":"History of South Africa (1994–present)","location":"Southern Africa","note":"The first national election based on universal adult suffrage was held in April 1994. This is a transition within South African state history, not a new population replacing an earlier one.","sources":["connection_africa_af_southafrica","wikipedia_af-southafrica-democratic"],"graphOnly":true},{"id":"ao-maya-peoples","title":"Maya peoples · living communities","region":"americas","dates":"Ancient roots–present","wikiTitle":"Maya peoples","location":"Mesoamerica and diaspora","note":"Many distinct Maya peoples, languages and communities persist; this is not a single successor state or a civilisation that ended in 900 AD.","sources":["connection_americas_oceania_ao_mayaLiving","wikipedia_ao-maya-peoples"],"graphOnly":true},{"id":"ao-saint-domingue","title":"Saint-Domingue · French colonial rule","region":"americas","dates":"Late 17th century–1804","wikiTitle":"Saint-Domingue","location":"Western Hispaniola · present-day Haiti","note":"French colonial society depended on the enslavement of Africans; its overthrow followed a complex revolution, not a routine administrative transfer.","sources":["connection_americas_oceania_ao_haiti","connection_americas_oceania_ao_haitiColonial","wikipedia_ao-saint-domingue"],"graphOnly":true},{"id":"ao-chimor","title":"Chimú kingdom / Chimor","region":"americas","dates":"c. 11th–15th centuries","wikiTitle":"Chimor","location":"Northern coast of present-day Peru","note":"A regional kingdom centred on Chan Chan, with artistic traditions drawing on earlier north-coast cultures.","sources":["connection_americas_oceania_ao_mocheChimu","connection_americas_oceania_ao_inkaRoad","wikipedia_ao-chimor"],"graphOnly":true},{"id":"ao-colonial-peru","title":"Spanish colonial Peru","region":"americas","dates":"1530s–1820s · viceroyalty from 1542","wikiTitle":"Viceroyalty of Peru","location":"Changing parts of South America","note":"Spanish rule developed through conquest and changing jurisdictions; large Indigenous communities and resistance continued.","sources":["connection_americas_oceania_ao_inkaInvasion","wikipedia_ao-colonial-peru"],"graphOnly":true},{"id":"ao-peru","title":"Peru · independent eras","region":"americas","dates":"1821 declaration–present","wikiTitle":"Peru","location":"Western South America","note":"Independence was proclaimed in 1821; warfare and royalist resistance continued, including the decisive 1824 campaigns.","sources":["connection_americas_oceania_ao_peruIndependence","wikipedia_ao-peru"],"graphOnly":true},{"id":"ao-quechua-communities","title":"Quechua-speaking communities","region":"americas","dates":"Historical roots–present","wikiTitle":"Quechua people","location":"Andean region and diaspora","note":"Diverse living communities, not an unchanged Inca state; language, identity and local histories are not interchangeable.","sources":["connection_americas_oceania_ao_inkaRoad","wikipedia_ao-quechua-communities"],"graphOnly":true},{"id":"ao-caddo","title":"Caddo communities","region":"americas","dates":"Ancestral roots–present","wikiTitle":"Caddo","location":"Southeastern North America · later Oklahoma","note":"Distinct confederacies and communities persisted through dispossession and forced removal; historical trade partners are not automatically ancestors.","sources":["connection_americas_oceania_ao_caddoTrade","connection_americas_oceania_ao_caddoNation","wikipedia_ao-caddo"],"graphOnly":true},{"id":"ao-puebloans","title":"Pueblo peoples · continuing communities","region":"americas","dates":"Ancestral roots–present","wikiTitle":"Puebloans","location":"Southwestern North America","note":"Many distinct Pueblo nations share connections to Chaco; no single present-day Pueblo is its sole direct successor.","sources":["connection_americas_oceania_ao_chacoDescendants","wikipedia_ao-puebloans"],"graphOnly":true},{"id":"ao-colonial-new-mexico","title":"Spanish colonial New Mexico","region":"americas","dates":"1598–1821 · rule interrupted 1680–1690s","wikiTitle":"Santa Fe de Nuevo México","location":"Northern New Spain · Southwestern North America","note":"Spanish colonisation was contested; the Pueblo Revolt expelled colonists in 1680, followed by reconquest in the 1690s.","sources":["connection_americas_oceania_ao_newMexico","connection_americas_oceania_ao_puebloColonial","wikipedia_ao-colonial-new-mexico"],"graphOnly":true},{"id":"ao-east-polynesia","title":"East Polynesian voyaging networks","region":"oceania","dates":"Late first millennium AD onward","wikiTitle":"Polynesians","location":"Central and eastern Pacific","note":"Multiple migrations and connected island societies, not one empire or a single founding voyage.","sources":["connection_americas_oceania_ao_pacificVoyaging","wikipedia_ao-east-polynesia"],"graphOnly":true},{"id":"ao-tonga-modern","title":"Kingdom of Tonga · modern eras","region":"oceania","dates":"United in 1845 · constitutional monarchy from 1875–present","wikiTitle":"Tonga","location":"Western Polynesia","note":"Modern consolidation and constitutional government differed from earlier chiefly arrangements; British protection 1900–1970 limited external affairs without annexation.","sources":["connection_americas_oceania_ao_tongaModern","wikipedia_ao-tonga-modern"],"graphOnly":true},{"id":"ao-fiji-societies","title":"Fijian societies","region":"oceania","dates":"Settlement c. 1100–800 BC–present","wikiTitle":"History of Fiji","location":"Fiji Islands","note":"Long histories of distinct island communities precede the modern state and continued through colonial rule.","sources":["connection_americas_oceania_ao_pacificVoyaging","wikipedia_ao-fiji-societies"],"graphOnly":true},{"id":"ao-colonial-fiji","title":"British colonial Fiji","region":"oceania","dates":"1874–1970","wikiTitle":"Colony of Fiji","location":"Fiji Islands","note":"The 1874 cession and colonial administration did not end Indigenous Fijian communities; later migration also shaped society.","sources":["connection_americas_oceania_ao_fijiParliament","wikipedia_ao-colonial-fiji"],"graphOnly":true},{"id":"ao-pohnpei","title":"Pohnpei · continuing communities","region":"oceania","dates":"Island traditions continue · state in FSM since 1979","wikiTitle":"Pohnpei","location":"Eastern Caroline Islands","note":"Nan Madol is associated with living chiefly traditions; modern constitutional statehood is distinct from Saudeleur rule.","sources":["connection_americas_oceania_ao_nanMadol","connection_americas_oceania_ao_fsm","wikipedia_ao-pohnpei"],"graphOnly":true},{"id":"ao-fsm","title":"Federated States of Micronesia","region":"oceania","dates":"Constitution 1979 · Compact 1986–present","wikiTitle":"Federated States of Micronesia","location":"Western Pacific","note":"A federation of four island states with distinct earlier histories; independence developed through constitutional government and the Compact of Free Association.","sources":["connection_americas_oceania_ao_fsm","wikipedia_ao-fsm"],"graphOnly":true},{"id":"ao-rapa-nui-people","title":"Rapa Nui people · continuing community","region":"oceania","dates":"Historical roots–present","wikiTitle":"Rapa Nui people","location":"Rapa Nui / Easter Island and diaspora","note":"Rapa Nui people and culture continue beyond the monumental phase; modern administration and Indigenous rights have their own contested history.","sources":["connection_americas_oceania_ao_rapaNuiHeritage","connection_americas_oceania_ao_rapaNuiChile","wikipedia_ao-rapa-nui-people"],"graphOnly":true},{"id":"ao-chile","title":"Chile · independent state","region":"americas","dates":"Independent eras–present","wikiTitle":"Chile","location":"South America and Rapa Nui","note":"The 1888 agreement concerns Rapa Nui and Chile; it is not the founding of Chile or the disappearance of Rapa Nui authority.","sources":["connection_americas_oceania_ao_rapaNuiChile","wikipedia_ao-chile"],"graphOnly":true},{"id":"ao-colonial-nz","title":"New Zealand · British colonial era","region":"oceania","dates":"1840–1907 · separate colony from 1841","wikiTitle":"Colony of New Zealand","location":"Aotearoa New Zealand","note":"British sovereignty was proclaimed in 1840; the separate colony followed in 1841, and Māori authority and treaty rights remained contested.","sources":["connection_americas_oceania_ao_nzColony","connection_americas_oceania_ao_nzTreaty","wikipedia_ao-colonial-nz"],"graphOnly":true},{"id":"ea-kenmu","title":"Kenmu Restoration","region":"eastasia","dates":"1333–1336 AD","wikiTitle":"Kenmu Restoration","location":"Japan","note":"A brief attempt by Emperor Go-Daigo to restore direct imperial rule; the later Southern Court continued after the Ashikaga seized Kyoto.","sources":["connection_eastasia_ea_kamakura","wikipedia_ea-kenmu"],"graphOnly":true},{"id":"ea-momoyama","title":"Azuchi–Momoyama · unification","region":"eastasia","dates":"1568/1573–1603 AD","wikiTitle":"Azuchi–Momoyama period","location":"Japan","note":"Selected political frame for Nobunaga, Hideyoshi and Tokugawa consolidation. Art histories often extend the Momoyama period to 1615; it is not a single hereditary dynasty.","sources":["connection_eastasia_ea_muromachi","connection_eastasia_ea_edo","wikipedia_ea-momoyama"],"graphOnly":true},{"id":"ea-korean-empire","title":"Korean Empire","region":"eastasia","dates":"1897–1910 AD","wikiTitle":"Korean Empire","location":"Korean peninsula","note":"Gojong proclaimed an empire in 1897 within the continuing Yi royal house. Japan imposed a protectorate in 1905 before annexation in 1910.","sources":["connection_eastasia_ea_korean_empire","wikipedia_ea-korean-empire"],"graphOnly":true},{"id":"ea-korea-colonial","title":"Korea under Japanese rule","region":"eastasia","dates":"1910–1945 AD","wikiTitle":"Korea under Japanese rule","location":"Korean peninsula","note":"Japanese colonial administration over Korea; Korean resistance, culture and independence movements continued. Colonial government did not represent voluntary political union.","sources":["connection_eastasia_ea_korea_modern","wikipedia_ea-korea-colonial"],"graphOnly":true},{"id":"ea-korea-soviet","title":"Northern Korea · Soviet occupation","region":"eastasia","dates":"1945–1948 AD","wikiTitle":"Soviet Civil Administration","location":"Northern Korean peninsula","note":"The northern occupation zone after Japanese surrender; local politics and competing projects developed within a Soviet military framework. This was not yet the DPRK at its creation in 1945.","sources":["connection_eastasia_ea_korea_occupation","wikipedia_ea-korea-soviet"],"graphOnly":true},{"id":"ea-korea-us","title":"Southern Korea · U.S. military government","region":"eastasia","dates":"1945–1948 AD","wikiTitle":"United States Army Military Government in Korea","location":"Southern Korean peninsula","note":"The southern occupation zone after Japanese surrender, preceding the Republic of Korea. Local political struggles and violence are not captured by a simple line of institutional succession.","sources":["connection_eastasia_ea_korea_occupation","wikipedia_ea-korea-us"],"graphOnly":true},{"id":"ea-voc","title":"Dutch East India Company · island Southeast Asia","region":"eastasia","dates":"1602–1799 AD","wikiTitle":"Dutch East India Company","location":"Island Southeast Asia","note":"Selected VOC activity in the Indonesian archipelago, not the company’s full Asian reach or uniform control of every island. Local states remained independent or negotiated and fought with the company.","sources":["connection_eastasia_ea_voc","wikipedia_ea-voc"],"graphOnly":true},{"id":"ea-dutch-indies","title":"Dutch East Indies","region":"eastasia","dates":"1800–1942 / 1945–1949 AD","wikiTitle":"Dutch East Indies","location":"Indonesian archipelago","note":"Colonial administration succeeded VOC rule in stages, with British interregnum and later Japanese occupation. Dutch territorial claims were resisted and did not imply uniform control from 1800.","sources":["connection_eastasia_ea_sea_colonial","connection_eastasia_ea_independence","wikipedia_ea-dutch-indies"],"graphOnly":true},{"id":"ea-japan-indies","title":"Japanese occupation · East Indies","region":"eastasia","dates":"1942–1945 AD","wikiTitle":"Japanese occupation of the Dutch East Indies","location":"Indonesian archipelago","note":"Japanese military occupation displaced Dutch colonial government during the Second World War; it was not Indonesian independence.","sources":["connection_eastasia_ea_sukarno","wikipedia_ea-japan-indies"],"graphOnly":true},{"id":"ea-post-angkor","title":"Cambodian kingdoms after Angkor","region":"eastasia","dates":"15th century–1863 AD","wikiTitle":"Post-Angkor period","location":"Cambodia","note":"Cambodian courts and capitals continued after Angkor’s political decline amid changing relations with Siam and Vietnam; neither Khmer society nor Angkor’s religious significance ended in 1431.","sources":["connection_eastasia_ea_sea_early_modern","connection_eastasia_ea_cambodia_early","wikipedia_ea-post-angkor"],"graphOnly":true},{"id":"ea-french-cambodia","title":"French protectorate of Cambodia","region":"eastasia","dates":"1863–1953 AD","wikiTitle":"French protectorate of Cambodia","location":"Cambodia","note":"French colonial control coexisted with a Cambodian monarchy; Japanese wartime intervention and the brief 1945 independence episode interrupted the wider protectorate frame.","sources":["connection_eastasia_ea_cambodia_early","wikipedia_ea-french-cambodia"],"graphOnly":true},{"id":"ea-cambodia-kingdom1","title":"Cambodia · independent kingdom","region":"eastasia","dates":"1953–1970 AD","wikiTitle":"Kingdom of Cambodia (1953–1970)","location":"Cambodia","note":"Independent monarchy and Sihanouk-led political order before the 1970 coup; Sihanouk abdicated the throne in 1955 but remained a dominant political leader.","sources":["connection_eastasia_ea_cambodia_early","connection_eastasia_ea_cambodia_coup","wikipedia_ea-cambodia-kingdom1"],"graphOnly":true},{"id":"ea-khmer-republic","title":"Khmer Republic","region":"eastasia","dates":"1970–1975 AD","wikiTitle":"Khmer Republic","location":"Cambodia","note":"Lon Nol’s republican regime emerged after Sihanouk’s removal amid widening regional warfare and civil war.","sources":["connection_eastasia_ea_cambodia_coup","wikipedia_ea-khmer-republic"],"graphOnly":true},{"id":"ea-democratic-kampuchea","title":"Khmer Rouge · Democratic Kampuchea","region":"eastasia","dates":"1975–1979 AD","wikiTitle":"Democratic Kampuchea","location":"Cambodia","note":"Khmer Rouge rule began with the capture of Phnom Penh in April 1975; the formal Democratic Kampuchea constitution followed in 1976. Forced labour, persecution, mass deaths and genocide marked this regime.","sources":["connection_eastasia_ea_cambodia_kr","wikipedia_ea-democratic-kampuchea"],"graphOnly":true},{"id":"ea-prk-cambodia","title":"People’s Republic / State of Cambodia","region":"eastasia","dates":"1979–1993 AD","wikiTitle":"People's Republic of Kampuchea","location":"Cambodia","note":"Vietnamese-backed government controlled most of Cambodia while war and international recognition disputes continued; renamed State of Cambodia in 1989, before the 1991 settlement and 1992–1993 UN transition.","sources":["connection_eastasia_ea_cambodia_1979","connection_eastasia_ea_untac","wikipedia_ea-prk-cambodia"],"graphOnly":true},{"id":"ea-cambodia-modern","title":"Cambodia · restored kingdom","region":"eastasia","dates":"1993–present","wikiTitle":"Cambodia","location":"Cambodia","note":"Constitutional monarchy restored after the Paris peace process, UN-sponsored elections and 1993 constitution. Restoration of the royal institution did not erase the preceding republics, wars or their effects.","sources":["connection_eastasia_ea_untac","wikipedia_ea-cambodia-modern"],"graphOnly":true},{"id":"ea-nguyen","title":"Nguyễn dynasty","region":"eastasia","dates":"1802–1945 AD","wikiTitle":"Nguyễn dynasty","location":"Vietnam","note":"The last Vietnamese royal dynasty continued at Huế after France imposed colonial rule. Its dynastic lifespan must not be equated with uninterrupted sovereignty over modern Vietnam.","sources":["connection_eastasia_ea_vietnam_dynasty","wikipedia_ea-nguyen"],"graphOnly":true},{"id":"ea-french-indochina","title":"French Indochina","region":"eastasia","dates":"1887–1954 AD","wikiTitle":"French Indochina","location":"Mainland Southeast Asia","note":"A colonial federation developed through conquests and protectorates over different territories, including Vietnam, Cambodia and later Laos; Japanese wartime control and independence movements interrupted the frame.","sources":["connection_eastasia_ea_sea_colonial","wikipedia_ea-french-indochina"],"graphOnly":true},{"id":"ea-vietnam-north","title":"Democratic Republic of Vietnam","region":"eastasia","dates":"1945–1976 AD","wikiTitle":"North Vietnam","location":"Vietnam","note":"Independence proclaimed in 1945; the government controlled the northern regroupment zone after the 1954 agreements and later won the war. This was not a state first founded in 1954.","sources":["connection_eastasia_ea_vietnam_recognition","connection_eastasia_ea_vietnam_reunion","wikipedia_ea-vietnam-north"],"graphOnly":true},{"id":"ea-vietnam-south","title":"Southern Vietnam · State and Republic","region":"eastasia","dates":"1949–1975 AD","wikiTitle":"South Vietnam","location":"Southern Vietnam","note":"Selected umbrella for the State of Vietnam from 1949 and the Republic proclaimed in 1955; administrative control and borders were contested throughout the wars.","sources":["connection_eastasia_ea_vietnam_recognition","wikipedia_ea-vietnam-south"],"graphOnly":true},{"id":"ea-northern-yuan","title":"Northern Yuan and post-Yuan Mongol courts","region":"eastasia","dates":"1368–1635 AD","wikiTitle":"Northern Yuan","location":"Mongolian plateau","note":"After losing the main Chinese realm, Yuan rulers retreated to Mongolia; successor courts and confederations competed with Oirat powers. Later regional Mongol histories extended beyond the Northern Yuan dynastic endpoint.","sources":["connection_eastasia_ea_mongolia_postyuan","connection_eastasia_ea_mongolia_northern_yuan","wikipedia_ea-northern-yuan"],"graphOnly":true},{"id":"ea-khalkha","title":"Khalkha Mongol principalities","region":"eastasia","dates":"16th–17th centuries · before 1691","wikiTitle":"Khalkha Mongols","location":"Mongolian plateau north of the Gobi","note":"Selected regional political frame north of the Gobi, not the full lifespan of Khalkha people. This branch is not identical to all Mongols or every Northern Yuan successor polity.","sources":["connection_eastasia_ea_mongolia_postyuan","connection_eastasia_ea_mongolia_qing","wikipedia_ea-khalkha"],"graphOnly":true},{"id":"ea-bogd","title":"Bogd Khanate of Mongolia","region":"eastasia","dates":"1911–1919 / 1921–1924 AD","wikiTitle":"Bogd Khanate of Mongolia","location":"Outer Mongolia","note":"Independence declared in 1911, with contested autonomy and Chinese military reoccupation in 1919; the Bogd Khan returned in 1921 before the 1924 republic.","sources":["connection_eastasia_ea_mongolia_qing","wikipedia_ea-bogd"],"graphOnly":true},{"id":"ea-mongolian-republic","title":"Mongolian People’s Republic","region":"eastasia","dates":"1924–1992 AD","wikiTitle":"Mongolian People's Republic","location":"Mongolia","note":"A Soviet-aligned socialist state, not a Soviet Union constituent republic. The democratic revolution began in 1990 before the constitutional state-name change in 1992.","sources":["connection_eastasia_ea_mongolia_republic","connection_eastasia_ea_mongolia_democracy","wikipedia_ea-mongolian-republic"],"graphOnly":true},{"id":"ea-mongolia-modern","title":"Mongolia · democratic constitutional era","region":"eastasia","dates":"1990/1992–present","wikiTitle":"Mongolia","location":"Mongolia","note":"The peaceful democratic transition began in 1990 and a new constitution followed in 1992; this was a change of political system within a continuing state, not the origin of Mongolian people.","sources":["connection_eastasia_ea_mongolia_democracy","wikipedia_ea-mongolia-modern"],"graphOnly":true},{"id":"cx-anglosaxon-realms","title":"Anglo-Saxon kingdoms and settlement","region":"europe","dates":"c. 5th–10th centuries AD","wikiTitle":"Anglo-Saxon England","location":"Britain, especially present-day England","note":"Several kingdoms formed amid migration, conflict and interaction with existing British communities; this was never one united state spanning the full frame.","sources":["connection_europe_euBritainEarly","wikipedia_cx-anglosaxon-realms"],"graphOnly":true},{"id":"cx-rus-principalities","title":"Rus’ principalities · regional realms","region":"europe","dates":"12th–14th centuries AD · selected frame","wikiTitle":"Kievan Rus'","location":"Eastern Europe","note":"An overlapping network of principalities, not a state created at one partition. Their later histories fed into several countries and cannot be assigned exclusively to modern Russia, Ukraine or Belarus.","sources":["connection_europe_euRusHistory","connection_europe_euRusPrincipalities","wikipedia_cx-rus-principalities"],"graphOnly":true},{"id":"cx-grandduchy-lithuania","title":"Grand Duchy of Lithuania","region":"europe","dates":"13th century–1795 AD","wikiTitle":"Grand Duchy of Lithuania","location":"Eastern and northeastern Europe","note":"A multiethnic polity that incorporated many western and southern Rus’ lands. It entered dynastic union with Poland and later the Polish–Lithuanian Commonwealth; this map selects its relationship with Rus’, not its entire history.","sources":["connection_europe_euRusLithuania","wikipedia_cx-grandduchy-lithuania"],"graphOnly":true},{"id":"cn-belarus","title":"Belarus · independent state","region":"europe","dates":"1991 AD–present","wikiTitle":"Belarus","location":"Eastern Europe","note":"Selected independent-state frame after Soviet dissolution; earlier regional histories and communities predate 1991.","sources":["connection_modern_branches_mbSovietArchive","wikipedia_cn-belarus"],"graphOnly":true},{"id":"cn-moldova","title":"Moldova · independent state","region":"europe","dates":"1991 AD–present","wikiTitle":"Moldova","location":"Eastern Europe","note":"Selected independent-state frame after Soviet dissolution; earlier regional histories and communities predate 1991.","sources":["connection_modern_branches_mbSovietArchive","wikipedia_cn-moldova"],"graphOnly":true},{"id":"cn-armenia","title":"Armenia · independent state","region":"westasia","dates":"1991 AD–present","wikiTitle":"Armenia","location":"South Caucasus","note":"Selected independent-state frame after Soviet dissolution; earlier regional histories and communities predate 1991.","sources":["connection_modern_branches_mbSovietArchive","wikipedia_cn-armenia"],"graphOnly":true},{"id":"cn-azerbaijan","title":"Azerbaijan · independent state","region":"westasia","dates":"1991 AD–present","wikiTitle":"Azerbaijan","location":"South Caucasus","note":"Selected independent-state frame after Soviet dissolution; earlier regional histories and communities predate 1991.","sources":["connection_modern_branches_mbSovietArchive","wikipedia_cn-azerbaijan"],"graphOnly":true},{"id":"cn-georgia","title":"Georgia · independent state","region":"westasia","dates":"1991 AD–present","wikiTitle":"Georgia (country)","location":"South Caucasus","note":"Selected independent-state frame after Soviet dissolution; earlier regional histories and communities predate 1991.","sources":["connection_modern_branches_mbSovietArchive","wikipedia_cn-georgia"],"graphOnly":true},{"id":"cn-kyrgyzstan","title":"Kyrgyzstan · independent state","region":"eastasia","dates":"1991 AD–present","wikiTitle":"Kyrgyzstan","location":"Central Asia","note":"Selected independent-state frame after Soviet dissolution; earlier regional histories and communities predate 1991.","sources":["connection_modern_branches_mbSovietArchive","wikipedia_cn-kyrgyzstan"],"graphOnly":true},{"id":"cn-tajikistan","title":"Tajikistan · independent state","region":"eastasia","dates":"1991 AD–present","wikiTitle":"Tajikistan","location":"Central Asia","note":"Selected independent-state frame after Soviet dissolution; earlier regional histories and communities predate 1991.","sources":["connection_modern_branches_mbSovietArchive","wikipedia_cn-tajikistan"],"graphOnly":true},{"id":"cn-turkmenistan","title":"Turkmenistan · independent state","region":"eastasia","dates":"1991 AD–present","wikiTitle":"Turkmenistan","location":"Central Asia","note":"Selected independent-state frame after Soviet dissolution; earlier regional histories and communities predate 1991.","sources":["connection_modern_branches_mbSovietArchive","wikipedia_cn-turkmenistan"],"graphOnly":true},{"id":"cn-uzbekistan","title":"Uzbekistan · independent state","region":"eastasia","dates":"1991 AD–present","wikiTitle":"Uzbekistan","location":"Central Asia","note":"Selected independent-state frame after Soviet dissolution; earlier regional histories and communities predate 1991.","sources":["connection_modern_branches_mbSovietArchive","wikipedia_cn-uzbekistan"],"graphOnly":true},{"id":"cn-estonia","title":"Estonia · restored independence","region":"europe","dates":"1990–1991 restoration · present","wikiTitle":"Estonia","location":"Baltic region","note":"Restored independence after Soviet occupation and annexation, rather than the beginning of the country’s history.","sources":["connection_modern_branches_mbBalticRestoration","connection_modern_branches_mbBalticRecognition","wikipedia_cn-estonia"],"graphOnly":true},{"id":"cn-latvia","title":"Latvia · restored independence","region":"europe","dates":"1990–1991 restoration · present","wikiTitle":"Latvia","location":"Baltic region","note":"Restored independence after Soviet occupation and annexation, rather than the beginning of the country’s history.","sources":["connection_modern_branches_mbBalticRestoration","connection_modern_branches_mbBalticRecognition","wikipedia_cn-latvia"],"graphOnly":true},{"id":"cn-lithuania","title":"Lithuania · restored independence","region":"europe","dates":"1990–1991 restoration · present","wikiTitle":"Lithuania","location":"Baltic region","note":"Restored independence after Soviet occupation and annexation, rather than the beginning of the country’s history.","sources":["connection_modern_branches_mbBalticRestoration","connection_modern_branches_mbBalticRecognition","wikipedia_cn-lithuania"],"graphOnly":true},{"id":"mb-abukhayr","title":"Abu’l-Khayr’s Uzbek steppe realm","region":"eastasia","dates":"15th century AD","wikiTitle":"Uzbek Khanate","location":"Eastern Dasht-i Qipchaq","note":"A post-Horde steppe realm; not the modern state of Uzbekistan or all Uzbek communities.","sources":["connection_modern_branches_mbCentralEarly","wikipedia_mb-abukhayr"],"graphOnly":true},{"id":"mb-kazakh-khanate","title":"Kazakh khanate and zhuzes","region":"eastasia","dates":"From c. 1465 · 18th–19th-century incorporation","wikiTitle":"Kazakh Khanate","location":"Kazakh steppe and adjoining regions","note":"Kerei and Janibek established a khanate after migration into Moghulistan. Later zhuzes had distinct, overlapping political paths.","sources":["connection_modern_branches_mbKazakhFoundation","wikipedia_mb-kazakh-khanate"],"graphOnly":true},{"id":"mb-bukhara-khanate","title":"Bukhara and Transoxiana · khanate eras","region":"eastasia","dates":"c. 1500–1785 AD · dynastic frame","wikiTitle":"Khanate of Bukhara","location":"Transoxiana and changing neighbouring territories","note":"Shibanid, Janid and early Manghit arrangements are grouped; capitals, borders and the location of effective authority changed.","sources":["connection_modern_branches_mbCentralEarly","connection_modern_branches_mbBukhara","wikipedia_mb-bukhara-khanate"],"graphOnly":true},{"id":"mb-bukhara-emirate","title":"Emirate of Bukhara","region":"eastasia","dates":"1785–1920 AD","wikiTitle":"Emirate of Bukhara","location":"Parts of present-day Uzbekistan, Tajikistan and neighbouring countries","note":"Manghit emirate; Russian domination after 1868 did not immediately abolish the emir’s government.","sources":["connection_modern_branches_mbBukhara","connection_modern_branches_mbManghits","wikipedia_mb-bukhara-emirate"],"graphOnly":true},{"id":"mb-khiva","title":"Khwarazm / Khanate of Khiva","region":"eastasia","dates":"1511–1920 AD · multiple dynasties","wikiTitle":"Khanate of Khiva","location":"Lower Amu Darya region","note":"Founded by a separate Jochid dynasty; not an offshoot of modern Uzbekistan or an ethnically uniform state.","sources":["connection_modern_branches_mbKhiva","wikipedia_mb-khiva"],"graphOnly":true},{"id":"mb-kokand","title":"Khanate of Kokand","region":"eastasia","dates":"c. 1709–1876 AD","wikiTitle":"Khanate of Kokand","location":"Fergana and changing adjoining territories","note":"A Fergana-based khanate whose expansion included diverse settled and nomadic communities.","sources":["connection_modern_branches_mbCentralRussian","wikipedia_mb-kokand"],"graphOnly":true},{"id":"mb-russian-central","title":"Russian rule in Central Asia","region":"eastasia","dates":"18th century–1917/1920 AD · changing forms","wikiTitle":"Russian conquest of Central Asia","location":"Kazakh steppe, Turkestan and protectorates","note":"A regional overview of annexed territories and unequal protectorates, not one uniform administration.","sources":["connection_modern_branches_mbCentralRussian","wikipedia_mb-russian-central"],"graphOnly":true},{"id":"mb-early-soviet-central","title":"Central Asia · revolution and early Soviet governments","region":"eastasia","dates":"1917–1936 AD · selected transition","wikiTitle":"Soviet Central Asia","location":"Central Asia","note":"War, autonomous experiments, Soviet republics and resistance preceded the five union-republic framework.","sources":["connection_modern_branches_mbCentralSoviet","wikipedia_mb-early-soviet-central"],"graphOnly":true},{"id":"mb-moghulistan","title":"Moghulistan · eastern Chagataid realms","region":"eastasia","dates":"Mid-14th–16th centuries AD · regional frame","wikiTitle":"Moghulistan","location":"Ili, Tian Shan and Tarim regions","note":"The eastern Chagataid political world continued after Timur’s rise in the west; rule later divided into regional branches.","sources":["connection_modern_branches_mbCentralMedieval","connection_modern_branches_mbChaghatay","wikipedia_mb-moghulistan"],"graphOnly":true},{"id":"mb-yarkent","title":"Yarkent Khanate","region":"eastasia","dates":"16th–late 17th centuries AD","wikiTitle":"Yarkent Khanate","location":"Southern Tarim Basin","note":"One eastern Chagataid realm, with power increasingly contested by Khoja lineages and regional lords.","sources":["connection_modern_branches_mbCentralMedieval","wikipedia_mb-yarkent"],"graphOnly":true},{"id":"mb-turpan","title":"Turpan · Chagataid and later oasis rule","region":"eastasia","dates":"Late 15th–early 18th centuries AD · regional frame","wikiTitle":"Turpan Khanate","location":"Turpan oasis and adjoining regions","note":"A selected regional frame; Chagataid rulers, local leaders and Dzungar overlords were distinct phases.","sources":["connection_modern_branches_mbCentralMedieval","connection_modern_branches_mbTurpanQing","wikipedia_mb-turpan"],"graphOnly":true},{"id":"mb-khojas","title":"Tarim Khoja governments under Dzungar supremacy","region":"eastasia","dates":"Late 1670s–1759 AD","wikiTitle":"Afaq Khoja","location":"Kashgaria / southern Tarim Basin","note":"Competing Sufi lineages ruled or influenced oasis governments; Dzungar khans demanded tribute and hostages.","sources":["connection_modern_branches_mbKhojas","wikipedia_mb-khojas"],"graphOnly":true},{"id":"mb-dzungar","title":"Dzungar Khanate","region":"eastasia","dates":"17th–mid-18th centuries AD","wikiTitle":"Dzungar Khanate","location":"Dzungaria and expanding Inner Asian territories","note":"An Oirat Mongol state, distinct from Chagataid realms. Qing conquest destroyed its government and devastated its population.","sources":["connection_modern_branches_mbDzungar","connection_modern_branches_mbDzungarLoss","wikipedia_mb-dzungar"],"graphOnly":true},{"id":"ws-herodian-judea","title":"Herodian Judea","region":"westasia","dates":"37 BC–6 AD · selected phase","wikiTitle":"Herodian kingdom","location":"Southern Levant","note":"A Roman client kingdom; dates combine Herod’s kingdom and Archelaus’s reduced ethnarchy.","sources":["connection_west_south_ws_herod","wikipedia_ws-herodian-judea"],"graphOnly":true},{"id":"ws-anatolian-beyliks","title":"Anatolian beyliks","region":"westasia","dates":"13th–15th centuries · selected polities","wikiTitle":"Anatolian beyliks","location":"Anatolia","note":"Many rival principalities emerged in a landscape of weakening Seljuq, Mongol, and Byzantine control.","sources":["connection_west_south_ws_anatoliamedieval","connection_west_south_ws_ottomanrise","wikipedia_ws-anatolian-beyliks"],"graphOnly":true},{"id":"ws-british-iraq","title":"British occupation & mandate project in Iraq","region":"westasia","dates":"1914–1932 · changing arrangements","wikiTitle":"Mandatory Iraq","location":"Mesopotamia / Iraq","note":"Wartime occupation, a mandate project, and treaty supervision overlapped with the monarchy established in 1921.","sources":["connection_west_south_ws_iraqmandate","connection_west_south_ws_iraqrepublic","wikipedia_ws-british-iraq"],"graphOnly":true},{"id":"ws-french-levant","title":"French mandate: Syria & Lebanon","region":"westasia","dates":"1920s–1940s · multiple administrations","wikiTitle":"Mandate for Syria and the Lebanon","location":"Eastern Mediterranean","note":"French rule created and reorganized several administrations, not one enduring national state.","sources":["connection_west_south_ws_syria","connection_west_south_ws_lebanon","wikipedia_ws-french-levant"],"graphOnly":true},{"id":"ws-lebanon","title":"Lebanon · independent state","region":"westasia","dates":"1943–present","wikiTitle":"Lebanon","location":"Eastern Mediterranean","note":"Independence in 1943 and final French troop withdrawal in 1946 were separate milestones.","sources":["connection_west_south_ws_lebanon","wikipedia_ws-lebanon"],"graphOnly":true},{"id":"ws-syria","title":"Syria · independent state","region":"westasia","dates":"1940s–present","wikiTitle":"Syria","location":"Eastern Mediterranean","note":"Independence involved wartime recognition and transfer of power followed by French withdrawal in 1946.","sources":["connection_west_south_ws_syria","wikipedia_ws-syria"],"graphOnly":true},{"id":"ws-hejaz-nejd","title":"Kingdom of Hejaz & Nejd","region":"westasia","dates":"1926–1932","wikiTitle":"Kingdom of Hejaz and Nejd","location":"Arabian Peninsula","note":"Ibn Saud’s dominions followed conquest and consolidation of distinct regions; this was not all Arabia.","sources":["connection_west_south_ws_saudi","connection_west_south_ws_saudiname","wikipedia_ws-hejaz-nejd"],"graphOnly":true},{"id":"ws-mandate-palestine","title":"British Mandate for Palestine","region":"westasia","dates":"1920s–1948","wikiTitle":"Mandatory Palestine","location":"Eastern Mediterranean · west of the Jordan River","note":"British administration followed Ottoman defeat; Transjordan was administered separately.","sources":["connection_west_south_ws_mandates","wikipedia_ws-mandate-palestine"],"graphOnly":true},{"id":"ws-transjordan","title":"Emirate of Transjordan","region":"westasia","dates":"1921–1946","wikiTitle":"Emirate of Transjordan","location":"East of the Jordan River","note":"An autonomous Arab administration within the mandate framework; its provisions differed from Palestine west of the Jordan.","sources":["connection_west_south_ws_jordan","wikipedia_ws-transjordan"],"graphOnly":true},{"id":"ws-jordan","title":"Jordan · independent kingdom","region":"westasia","dates":"1946–present","wikiTitle":"Jordan","location":"East of the Jordan River","note":"Independent as Transjordan in 1946, later renamed Jordan; borders and territorial claims changed.","sources":["connection_west_south_ws_jordan","wikipedia_ws-jordan"],"graphOnly":true},{"id":"ws-plo","title":"Palestine Liberation Organization","region":"westasia","dates":"1964–present","wikiTitle":"Palestine Liberation Organization","location":"Palestinian national movement","note":"A national representative organization, not a country or an unchanged government.","sources":["connection_west_south_ws_ploformation","wikipedia_ws-plo"],"graphOnly":true},{"id":"ws-deccan-sultanates","title":"Deccan sultanates","region":"southasia","dates":"late 15th–17th centuries · several states","wikiTitle":"Deccan sultanates","location":"Deccan Plateau","note":"Five major sultanates succeeded Bahmanid fragmentation; their political relations changed repeatedly.","sources":["connection_west_south_ws_vijayanagara","wikipedia_ws-deccan-sultanates"],"graphOnly":true},{"id":"ws-durrani","title":"Durrani Empire","region":"southasia","dates":"1747–1823 · principal phase","wikiTitle":"Durrani Empire","location":"Afghanistan and adjoining regions","note":"Durrani rule had regional continuations and a British-backed restoration after this principal phase.","sources":["connection_west_south_ws_afghancrs","wikipedia_ws-durrani"],"graphOnly":true},{"id":"ws-barakzai","title":"Afghanistan · Barakzai rule","region":"southasia","dates":"1826–1973 · interrupted","wikiTitle":"Barakzai dynasty","location":"Afghanistan","note":"Emirs and kings ruled with interruptions; territory and foreign-policy independence changed.","sources":["connection_west_south_ws_afghancrs","wikipedia_ws-barakzai"],"graphOnly":true},{"id":"ws-afghanistan-later","title":"Afghanistan · later regimes","region":"southasia","dates":"1973–present · selected eras","wikiTitle":"History of Afghanistan","location":"Afghanistan","note":"Groups republican, communist, wartime, and Taliban governments; these are distinct regimes, including Taliban takeover in 2021.","sources":["connection_west_south_ws_afghancrs","connection_west_south_ws_afghan2021","wikipedia_ws-afghanistan-later"],"graphOnly":true}];
